BEGIN;
CREATE TEMP TABLE _tema ON COMMIT DROP AS SELECT id FROM public.topics WHERE convocatoria_id = 1 AND numero = 1;
DO $$ BEGIN IF (SELECT count(*) FROM _tema) <> 1 THEN RAISE EXCEPTION 'tema 1 de la convocatoria 1 no encontrado o duplicado'; END IF; END $$;
WITH cc AS (SELECT * FROM jsonb_to_recordset('[{"id": "CE-a10-1-fundamento", "apartado": "Título I · Art. 10.1", "orden": 300, "pregunta": "¿Qué cinco elementos son fundamento del orden político y de la paz social (art. 10.1 CE)?", "respuesta": "La dignidad de la persona, los derechos inviolables que le son inherentes, el libre desarrollo de la personalidad, el respeto a la ley y el respeto a los derechos de los demás.", "fuente": "Constitución Española, art. 10.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "La dignidad de la persona, los derechos inviolables que le son inherentes, el libre desarrollo de la personalidad, el respeto a la ley y a los derechos de los demás son fundamento del orden político y de la paz social.", "tipo": "lista", "prioridad": 1, "conf": ["CE-a1-1-valores", "CE-a2-unidad"]}, {"id": "CE-a10-2-interpretacion", "apartado": "Título I · Art. 10.2", "orden": 310, "pregunta": "¿Conforme a qué se interpretan las normas sobre derechos fundamentales y libertades (art. 10.2 CE)?", "respuesta": "De conformidad con la Declaración Universal de Derechos Humanos y los tratados y acuerdos internacionales sobre esas materias ratificados por España.", "fuente": "Constitución Española, art. 10.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "se interpretarán de conformidad con la Declaración Universal de Derechos Humanos y los tratados y acuerdos internacionales sobre las mismas materias ratificados por España", "tipo": "regla", "prioridad": 1, "conf": ["CE-a39-4-ninos"]}, {"id": "CE-a11-1-nacionalidad-ley", "apartado": "Título I · Art. 11.1", "orden": 320, "pregunta": "¿Qué dice el art. 11.1 CE sobre la nacionalidad española?", "respuesta": "Que se adquiere, se conserva y se pierde de acuerdo con lo establecido por la ley.", "fuente": "Constitución Española, art. 11.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "La nacionalidad española se adquiere, se conserva y se pierde de acuerdo con lo establecido por la ley.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a11-2-origen"]}, {"id": "CE-a11-2-origen", "apartado": "Título I · Art. 11.2", "orden": 330, "pregunta": "¿Puede un español de origen ser privado de su nacionalidad (art. 11.2 CE)?", "respuesta": "No: ningún español de origen podrá ser privado de su nacionalidad.", "fuente": "Constitución Española, art. 11.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Ningún español de origen podrá ser privado de su nacionalidad.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a11-1-nacionalidad-ley", "CE-a11-3-doble-nacionalidad"]}, {"id": "CE-a11-3-doble-nacionalidad", "apartado": "Título I · Art. 11.3", "orden": 340, "pregunta": "¿Con qué países puede concertar el Estado tratados de doble nacionalidad (art. 11.3 CE)?", "respuesta": "Con los países iberoamericanos o con aquellos que hayan tenido o tengan una particular vinculación con España.", "fuente": "Constitución Española, art. 11.3 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "El Estado podrá concertar tratados de doble nacionalidad con los países iberoamericanos o con aquellos que hayan tenido o tengan una particular vinculación con España.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a11-2-origen"]}, {"id": "CE-a12-mayoria-edad", "apartado": "Título I · Art. 12", "orden": 350, "pregunta": "¿A qué edad son mayores de edad los españoles (art. 12 CE)?", "respuesta": "A los dieciocho años.", "fuente": "Constitución Española, art. 12 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Los españoles son mayores de edad a los dieciocho años.", "tipo": "dato", "prioridad": 1, "conf": []}, {"id": "CE-a13-1-extranjeros-libertades", "apartado": "Título I · Art. 13.1", "orden": 360, "pregunta": "¿En qué términos gozan los extranjeros en España de las libertades públicas del Título I (art. 13.1 CE)?", "respuesta": "En los términos que establezcan los tratados y la ley.", "fuente": "Constitución Española, art. 13.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Los extranjeros gozarán en España de las libertades públicas que garantiza el presente Título en los términos que establezcan los tratados y la ley.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a13-2-sufragio-municipal"]}, {"id": "CE-a13-2-sufragio-municipal", "apartado": "Título I · Art. 13.2", "orden": 370, "pregunta": "¿Qué derechos son solo de los españoles y qué excepción admite el art. 13.2 CE?", "respuesta": "Los del art. 23; salvo que, atendiendo a criterios de reciprocidad, un tratado o ley establezca el sufragio activo y pasivo de extranjeros en las elecciones municipales.", "fuente": "Constitución Española, art. 13.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Solamente los españoles serán titulares de los derechos reconocidos en el artículo 23, salvo lo que, atendiendo a criterios de reciprocidad, pueda establecerse por tratado o ley para el derecho de sufragio activo y pasivo en las elecciones municipales.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a23-1-participacion", "CE-a13-1-extranjeros-libertades"]}, {"id": "CE-a13-3-extradicion", "apartado": "Título I · Art. 13.3", "orden": 380, "pregunta": "¿Cuándo se concede la extradición y qué delitos quedan excluidos (art. 13.3 CE)?", "respuesta": "Solo en cumplimiento de un tratado o de la ley, atendiendo al principio de reciprocidad; quedan excluidos los delitos políticos, sin que lo sean los actos de terrorismo.", "fuente": "Constitución Española, art. 13.3 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Quedan excluidos de la extradición los delitos políticos, no considerándose como tales los actos de terrorismo.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a13-4-asilo"]}, {"id": "CE-a13-4-asilo", "apartado": "Título I · Art. 13.4", "orden": 390, "pregunta": "¿Quién establece en qué términos pueden gozar del derecho de asilo en España los ciudadanos de otros países y los apátridas (art. 13.4 CE)?", "respuesta": "La ley.", "fuente": "Constitución Española, art. 13.4 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "La ley establecerá los términos en que los ciudadanos de otros países y los apátridas podrán gozar del derecho de asilo en España.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a13-3-extradicion"]}, {"id": "CE-a14-igualdad", "apartado": "Título I · Art. 14", "orden": 400, "pregunta": "¿Qué establece el art. 14 CE y qué causas de discriminación cita expresamente?", "respuesta": "Que los españoles son iguales ante la ley, sin discriminación por razón de nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal o social.", "fuente": "Constitución Española, art. 14 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Los españoles son iguales ante la ley, sin que pueda prevalecer discriminación alguna por razón de nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal o social.", "tipo": "lista", "prioridad": 1, "conf": ["CE-a9-2-igualdad-real", "CE-a1-1-valores"]}, {"id": "CE-a15-vida-integridad", "apartado": "Título I · Art. 15", "orden": 410, "pregunta": "¿Qué derechos reconoce el art. 15 CE y qué prohíbe en todo caso?", "respuesta": "El derecho a la vida y a la integridad física y moral; prohíbe la tortura y las penas o tratos inhumanos o degradantes.", "fuente": "Constitución Española, art. 15 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Todos tienen derecho a la vida y a la integridad física y moral, sin que, en ningún caso, puedan ser sometidos a tortura ni a penas o tratos inhumanos o degradantes.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a15-pena-muerte"]}, {"id": "CE-a15-pena-muerte", "apartado": "Título I · Art. 15", "orden": 420, "pregunta": "¿Qué dice el art. 15 CE sobre la pena de muerte?", "respuesta": "Queda abolida, salvo lo que puedan disponer las leyes penales militares para tiempos de guerra.", "fuente": "Constitución Española, art. 15 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Queda abolida la pena de muerte, salvo lo que puedan disponer las leyes penales militares para tiempos de guerra.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a15-vida-integridad"]}, {"id": "CE-a16-1-libertad-ideologica", "apartado": "Título I · Art. 16.1", "orden": 430, "pregunta": "¿Qué libertad garantiza el art. 16.1 CE y cuál es su único límite?", "respuesta": "La libertad ideológica, religiosa y de culto de los individuos y las comunidades; su único límite, en sus manifestaciones, es el necesario para mantener el orden público protegido por la ley.", "fuente": "Constitución Española, art. 16.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Se garantiza la libertad ideológica, religiosa y de culto de los individuos y las comunidades sin más limitación, en sus manifestaciones, que la necesaria para el mantenimiento del orden público protegido por la ley.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a16-3-aconfesionalidad"]}, {"id": "CE-a16-2-no-declarar", "apartado": "Título I · Art. 16.2", "orden": 440, "pregunta": "¿Sobre qué nadie puede ser obligado a declarar (art. 16.2 CE)?", "respuesta": "Sobre su ideología, religión o creencias.", "fuente": "Constitución Española, art. 16.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Nadie podrá ser obligado a declarar sobre su ideología, religión o creencias.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a17-3-detenido", "CE-a24-2-garantias"]}, {"id": "CE-a16-3-aconfesionalidad", "apartado": "Título I · Art. 16.3", "orden": 450, "pregunta": "¿Qué dice el art. 16.3 CE sobre las confesiones y las relaciones con ellas?", "respuesta": "Ninguna confesión tendrá carácter estatal; los poderes públicos tendrán en cuenta las creencias religiosas de la sociedad y mantendrán relaciones de cooperación con la Iglesia Católica y las demás confesiones.", "fuente": "Constitución Española, art. 16.3 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Ninguna confesión tendrá carácter estatal.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a16-1-libertad-ideologica"]}, {"id": "CE-a17-1-libertad-seguridad", "apartado": "Título I · Art. 17.1", "orden": 460, "pregunta": "¿Qué derecho reconoce el art. 17.1 CE y cuándo puede alguien ser privado de libertad?", "respuesta": "El derecho a la libertad y a la seguridad; solo se puede privar de libertad con lo establecido en el art. 17 y en los casos y la forma previstos en la ley.", "fuente": "Constitución Española, art. 17.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Toda persona tiene derecho a la libertad y a la seguridad.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a17-2-72-horas"]}, {"id": "CE-a17-2-72-horas", "apartado": "Título I · Art. 17.2", "orden": 470, "pregunta": "¿Cuánto puede durar como máximo la detención preventiva (art. 17.2 CE)?", "respuesta": "El tiempo estrictamente necesario para las averiguaciones y, en todo caso, un máximo de setenta y dos horas; después, libertad o disposición de la autoridad judicial.", "fuente": "Constitución Española, art. 17.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "en todo caso, en el plazo máximo de setenta y dos horas, el detenido deberá ser puesto en libertad o a disposición de la autoridad judicial", "tipo": "plazo", "prioridad": 1, "conf": ["CE-a17-4-habeas-corpus"]}, {"id": "CE-a17-3-detenido", "apartado": "Título I · Art. 17.3", "orden": 480, "pregunta": "¿Qué derechos tiene todo detenido según el art. 17.3 CE?", "respuesta": "Ser informado de forma inmediata y comprensible de sus derechos y de las razones de su detención, no ser obligado a declarar y la asistencia de abogado en las diligencias policiales y judiciales.", "fuente": "Constitución Española, art. 17.3 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Toda persona detenida debe ser informada de forma inmediata, y de modo que le sea comprensible, de sus derechos y de las razones de su detención, no pudiendo ser obligada a declarar.", "tipo": "lista", "prioridad": 1, "conf": ["CE-a24-2-garantias", "CE-a55-1-excepcion-17-3"]}, {"id": "CE-a17-4-habeas-corpus", "apartado": "Título I · Art. 17.4", "orden": 490, "pregunta": "¿Para qué sirve el «habeas corpus» y qué más remite a la ley el art. 17.4 CE?", "respuesta": "Para la inmediata puesta a disposición judicial de toda persona detenida ilegalmente; la ley también fijará el plazo máximo de la prisión provisional.", "fuente": "Constitución Española, art. 17.4 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "La ley regulará un procedimiento de «habeas corpus» para producir la inmediata puesta a disposición judicial de toda persona detenida ilegalmente.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a17-2-72-horas"]}]'::jsonb) AS x(id text, apartado text, orden int, pregunta text, respuesta text, fuente text, cita text, tipo text, prioridad smallint, conf text[])) INSERT INTO public.concepts (id, topic_id, documento, apartado, orden, pregunta, respuesta, fuente, cita, tipo, prioridad, confundible_con, estado) SELECT cc.id, t.id, 'CE', cc.apartado, cc.orden, cc.pregunta, cc.respuesta, cc.fuente, cc.cita, cc.tipo, cc.prioridad, coalesce(cc.conf, '{}'), 'publicado' FROM cc, _tema t ON CONFLICT (id) DO UPDATE SET topic_id = EXCLUDED.topic_id, documento = EXCLUDED.documento, apartado = EXCLUDED.apartado, orden = EXCLUDED.orden, pregunta = EXCLUDED.pregunta, respuesta = EXCLUDED.respuesta, fuente = EXCLUDED.fuente, cita = EXCLUDED.cita, tipo = EXCLUDED.tipo, prioridad = EXCLUDED.prioridad, confundible_con = EXCLUDED.confundible_con, estado = EXCLUDED.estado;
CREATE TEMP TABLE _qq ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"c": "CE-a10-1-fundamento", "n": 1, "e": "Según el art. 10.1 CE, la dignidad de la persona es fundamento…", "o": [{"letra": "a", "texto": "del orden político y de la paz social"}, {"letra": "b", "texto": "del Estado social y democrático de Derecho"}], "k": "a", "x": "Art. 10.1 CE: la dignidad de la persona y los demás elementos que cita «son fundamento del orden político y de la paz social».", "f": "Art. 10.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a10-1-fundamento:N1"}, {"c": "CE-a10-1-fundamento", "n": 2, "e": "Según el art. 10.1 CE, ¿cuál de los siguientes es fundamento del orden político y de la paz social?", "o": [{"letra": "a", "texto": "El pluralismo político."}, {"letra": "b", "texto": "El libre desarrollo de la personalidad."}, {"letra": "c", "texto": "La indisoluble unidad de la Nación española."}], "k": "b", "x": "Art. 10.1 CE. La unidad de la Nación es el fundamento de la Constitución (art. 2) y el pluralismo político es un valor superior (art. 1.1).", "f": "Art. 10.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a10-1-fundamento:N2"}, {"c": "CE-a10-1-fundamento", "n": 3, "e": "¿Cuál de los siguientes NO figura en el art. 10.1 CE como fundamento del orden político y de la paz social?", "o": [{"letra": "a", "texto": "El respeto a la ley y a los derechos de los demás."}, {"letra": "b", "texto": "Los derechos inviolables inherentes a la persona."}, {"letra": "c", "texto": "La igualdad real y efectiva de los individuos."}], "k": "c", "x": "La igualdad real y efectiva aparece en el art. 9.2 como tarea de los poderes públicos; el art. 10.1 cita la dignidad, los derechos inviolables, el libre desarrollo de la personalidad, el respeto a la ley y a los derechos de los demás.", "f": "Art. 10.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a10-1-fundamento:N3"}, {"c": "CE-a10-2-interpretacion", "n": 1, "e": "Según el art. 10.2 CE, las normas sobre derechos fundamentales se interpretan de conformidad con…", "o": [{"letra": "a", "texto": "la Declaración Universal de Derechos Humanos"}, {"letra": "b", "texto": "la jurisprudencia del Tribunal Supremo"}], "k": "a", "x": "Art. 10.2 CE: de conformidad con la Declaración Universal de Derechos Humanos y los tratados y acuerdos internacionales ratificados por España.", "f": "Art. 10.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a10-2-interpretacion:N1"}, {"c": "CE-a10-2-interpretacion", "n": 2, "e": "Según el art. 10.2 CE, las normas relativas a los derechos fundamentales y a las libertades se interpretarán de conformidad con:", "o": [{"letra": "a", "texto": "La Declaración Universal de Derechos Humanos y los tratados y acuerdos internacionales sobre las mismas materias ratificados por España."}, {"letra": "b", "texto": "La Carta de las Naciones Unidas y las resoluciones de la Asamblea General sobre derechos humanos aprobadas con el voto de España."}, {"letra": "c", "texto": "El Convenio Europeo de Derechos Humanos, con exclusión de cualquier otro tratado."}], "k": "a", "x": "Art. 10.2 CE. La Constitución no cita la Carta de la ONU ni nombra el Convenio Europeo: habla de la Declaración Universal y de los tratados ratificados por España.", "f": "Art. 10.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a10-2-interpretacion:N2"}, {"c": "CE-a10-2-interpretacion", "n": 3, "e": "Según el art. 10.2 CE, ¿qué tratados internacionales sirven para interpretar las normas sobre derechos fundamentales?", "o": [{"letra": "a", "texto": "Los tratados y acuerdos sobre esas materias que hayan sido ratificados por España."}, {"letra": "b", "texto": "Todos los tratados sobre derechos humanos, aunque España no los haya ratificado."}, {"letra": "c", "texto": "Solo los tratados aprobados por ley orgánica de las Cortes Generales."}], "k": "a", "x": "Art. 10.2 CE: «tratados y acuerdos internacionales sobre las mismas materias ratificados por España».", "f": "Art. 10.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a10-2-interpretacion:N3"}, {"c": "CE-a11-1-nacionalidad-ley", "n": 1, "e": "Según el art. 11.1 CE, la nacionalidad española se adquiere, se conserva y se pierde de acuerdo con…", "o": [{"letra": "a", "texto": "lo establecido por la ley"}, {"letra": "b", "texto": "lo que decida el Gobierno"}], "k": "a", "x": "Art. 11.1 CE: de acuerdo con lo establecido por la ley.", "f": "Art. 11.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a11-1-nacionalidad-ley:N1"}, {"c": "CE-a11-1-nacionalidad-ley", "n": 2, "e": "Según el art. 11.1 CE, la nacionalidad española:", "o": [{"letra": "a", "texto": "Se regula en los tratados de doble nacionalidad firmados por España."}, {"letra": "b", "texto": "Se adquiere por nacimiento y solo puede perderse por resolución judicial."}, {"letra": "c", "texto": "Se adquiere, se conserva y se pierde de acuerdo con lo establecido por la ley."}], "k": "c", "x": "Art. 11.1 CE. Los tratados de doble nacionalidad aparecen en el art. 11.3.", "f": "Art. 11.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a11-1-nacionalidad-ley:N2"}, {"c": "CE-a11-1-nacionalidad-ley", "n": 3, "e": "¿Qué norma determina, según el art. 11.1 CE, cómo se adquiere, se conserva y se pierde la nacionalidad española?", "o": [{"letra": "a", "texto": "Una ley orgánica."}, {"letra": "b", "texto": "El Código Civil por mandato expreso de la Constitución."}, {"letra": "c", "texto": "La ley."}], "k": "c", "x": "El art. 11.1 CE se remite a «la ley», sin exigir ley orgánica ni nombrar el Código Civil.", "f": "Art. 11.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a11-1-nacionalidad-ley:N3"}, {"c": "CE-a11-2-origen", "n": 1, "e": "Según el art. 11.2 CE, ¿puede un español de origen ser privado de su nacionalidad?", "o": [{"letra": "a", "texto": "Sí, por sentencia firme"}, {"letra": "b", "texto": "No"}], "k": "b", "x": "Art. 11.2 CE: ningún español de origen podrá ser privado de su nacionalidad.", "f": "Art. 11.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a11-2-origen:N1"}, {"c": "CE-a11-2-origen", "n": 2, "e": "Según el art. 11.2 CE, ¿quién no podrá ser privado de su nacionalidad?", "o": [{"letra": "a", "texto": "Ningún español de origen."}, {"letra": "b", "texto": "Ningún español residente en España."}, {"letra": "c", "texto": "Ningún español mayor de edad."}], "k": "a", "x": "Art. 11.2 CE: la garantía protege a los españoles de origen.", "f": "Art. 11.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a11-2-origen:N2"}, {"c": "CE-a11-2-origen", "n": 3, "e": "¿Qué afirmación se ajusta al art. 11.2 CE?", "o": [{"letra": "a", "texto": "La prohibición de privar de la nacionalidad se refiere a los españoles de origen."}, {"letra": "b", "texto": "Ningún español, sea de origen o no, podrá ser privado de su nacionalidad."}, {"letra": "c", "texto": "Los españoles de origen solo pueden perder la nacionalidad por resolución judicial firme."}], "k": "a", "x": "El art. 11.2 habla solo de los españoles «de origen», y para ellos no admite privación alguna.", "f": "Art. 11.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a11-2-origen:N3"}, {"c": "CE-a11-3-doble-nacionalidad", "n": 1, "e": "Según el art. 11.3 CE, el Estado podrá concertar tratados de doble nacionalidad con…", "o": [{"letra": "a", "texto": "los Estados miembros de la Unión Europea"}, {"letra": "b", "texto": "los países iberoamericanos"}], "k": "b", "x": "Art. 11.3 CE: con los países iberoamericanos o con los que hayan tenido o tengan una particular vinculación con España.", "f": "Art. 11.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a11-3-doble-nacionalidad:N1"}, {"c": "CE-a11-3-doble-nacionalidad", "n": 2, "e": "Según el art. 11.3 CE, en los países iberoamericanos o con particular vinculación con España, los españoles podrán naturalizarse sin perder su nacionalidad de origen:", "o": [{"letra": "a", "texto": "Solo si residen en ellos durante al menos diez años."}, {"letra": "b", "texto": "Solo si esos países reconocen a sus ciudadanos un derecho recíproco."}, {"letra": "c", "texto": "Aun cuando esos países no reconozcan a sus ciudadanos un derecho recíproco."}], "k": "c", "x": "Art. 11.3 CE: «aun cuando no reconozcan a sus ciudadanos un derecho recíproco».", "f": "Art. 11.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a11-3-doble-nacionalidad:N2"}, {"c": "CE-a11-3-doble-nacionalidad", "n": 3, "e": "Según el art. 11.3 CE, ¿con qué países puede el Estado concertar tratados de doble nacionalidad?", "o": [{"letra": "a", "texto": "Con los iberoamericanos o con los que hayan tenido o tengan una particular vinculación con España."}, {"letra": "b", "texto": "Con cualquier país, siempre que exista reciprocidad."}, {"letra": "c", "texto": "Solo con los países iberoamericanos y con aquellos con los que España comparta lengua oficial."}], "k": "a", "x": "Art. 11.3 CE. No exige reciprocidad ni nombra a Portugal: habla de países iberoamericanos o con particular vinculación con España.", "f": "Art. 11.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a11-3-doble-nacionalidad:N3"}, {"c": "CE-a12-mayoria-edad", "n": 1, "e": "Según el art. 12 CE, los españoles son mayores de edad a los…", "o": [{"letra": "a", "texto": "dieciocho años"}, {"letra": "b", "texto": "veintiún años"}], "k": "a", "x": "Art. 12 CE: a los dieciocho años.", "f": "Art. 12 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a12-mayoria-edad:N1"}, {"c": "CE-a12-mayoria-edad", "n": 2, "e": "¿Qué artículo de la Constitución fija la mayoría de edad de los españoles?", "o": [{"letra": "a", "texto": "El art. 11."}, {"letra": "b", "texto": "El art. 14."}, {"letra": "c", "texto": "El art. 12."}], "k": "c", "x": "Art. 12 CE: «Los españoles son mayores de edad a los dieciocho años». El art. 11 trata de la nacionalidad y el 14, de la igualdad.", "f": "Art. 12 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a12-mayoria-edad:N2"}, {"c": "CE-a12-mayoria-edad", "n": 3, "e": "Según el art. 12 CE, la mayoría de edad a los dieciocho años:", "o": [{"letra": "a", "texto": "La fija la ley, que la Constitución remite al Código Civil."}, {"letra": "b", "texto": "Se aplica solo a efectos electorales."}, {"letra": "c", "texto": "La fija directamente la Constitución."}], "k": "c", "x": "El art. 12 fija directamente los dieciocho años, sin remitirse a ninguna ley.", "f": "Art. 12 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a12-mayoria-edad:N3"}, {"c": "CE-a13-1-extranjeros-libertades", "n": 1, "e": "Según el art. 13.1 CE, ¿gozan los extranjeros en España de las libertades públicas del Título I?", "o": [{"letra": "a", "texto": "No, solo los españoles"}, {"letra": "b", "texto": "Sí, en los términos que establezcan los tratados y la ley"}], "k": "b", "x": "Art. 13.1 CE.", "f": "Art. 13.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a13-1-extranjeros-libertades:N1"}, {"c": "CE-a13-1-extranjeros-libertades", "n": 2, "e": "Según el art. 13.1 CE, los extranjeros gozarán en España de las libertades públicas que garantiza el Título I:", "o": [{"letra": "a", "texto": "En los términos que establezcan los tratados y la ley."}, {"letra": "b", "texto": "Solo si existe reciprocidad con su país de origen."}, {"letra": "c", "texto": "En los mismos términos que los españoles, sin excepción alguna."}], "k": "a", "x": "Art. 13.1 CE: en los términos que establezcan los tratados y la ley. La reciprocidad se menciona en el art. 13.2 para el sufragio municipal.", "f": "Art. 13.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a13-1-extranjeros-libertades:N2"}, {"c": "CE-a13-1-extranjeros-libertades", "n": 3, "e": "El art. 13.1 CE remite el disfrute por los extranjeros de las libertades públicas del Título I a:", "o": [{"letra": "a", "texto": "Los tratados y la ley."}, {"letra": "b", "texto": "Una ley orgánica exclusivamente."}, {"letra": "c", "texto": "Los acuerdos bilaterales de reciprocidad."}], "k": "a", "x": "Art. 13.1 CE: «en los términos que establezcan los tratados y la ley».", "f": "Art. 13.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a13-1-extranjeros-libertades:N3"}, {"c": "CE-a13-2-sufragio-municipal", "n": 1, "e": "Según el art. 13.2 CE, los extranjeros pueden tener derecho de sufragio en las elecciones…", "o": [{"letra": "a", "texto": "municipales"}, {"letra": "b", "texto": "generales"}], "k": "a", "x": "Art. 13.2 CE: la excepción es para el sufragio activo y pasivo en las elecciones municipales, con criterios de reciprocidad.", "f": "Art. 13.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a13-2-sufragio-municipal:N1"}, {"c": "CE-a13-2-sufragio-municipal", "n": 2, "e": "Según el art. 13.2 CE, solamente los españoles serán titulares de los derechos reconocidos en el artículo:", "o": [{"letra": "a", "texto": "29"}, {"letra": "b", "texto": "23"}, {"letra": "c", "texto": "14"}], "k": "b", "x": "Art. 13.2 CE: derechos del art. 23 (participación en asuntos públicos y acceso a cargos públicos).", "f": "Art. 13.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a13-2-sufragio-municipal:N2"}, {"c": "CE-a13-2-sufragio-municipal", "n": 3, "e": "Según el art. 13.2 CE, para que un extranjero pueda votar y ser elegido en elecciones municipales es necesario:", "o": [{"letra": "a", "texto": "Que lo autorice una ley orgánica aprobada por mayoría de tres quintos."}, {"letra": "b", "texto": "Que lo establezca un tratado o una ley, atendiendo a criterios de reciprocidad."}, {"letra": "c", "texto": "Que tenga residencia legal en España durante al menos cinco años."}], "k": "b", "x": "Art. 13.2 CE: por tratado o ley, atendiendo a criterios de reciprocidad. La Constitución no fija años de residencia ni mayorías especiales. Este apartado se reformó en 1992 para añadir el sufragio pasivo.", "f": "Art. 13.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a13-2-sufragio-municipal:N3"}, {"c": "CE-a13-3-extradicion", "n": 1, "e": "Según el art. 13.3 CE, ¿se consideran delitos políticos, a efectos de extradición, los actos de terrorismo?", "o": [{"letra": "a", "texto": "Sí"}, {"letra": "b", "texto": "No"}], "k": "b", "x": "Art. 13.3 CE: quedan excluidos de la extradición los delitos políticos, «no considerándose como tales los actos de terrorismo».", "f": "Art. 13.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a13-3-extradicion:N1"}, {"c": "CE-a13-3-extradicion", "n": 2, "e": "Según el art. 13.3 CE, la extradición sólo se concederá:", "o": [{"letra": "a", "texto": "Cuando lo solicite un Estado miembro de la Unión Europea."}, {"letra": "b", "texto": "En cumplimiento de un tratado o de la ley, atendiendo al principio de reciprocidad."}, {"letra": "c", "texto": "Por acuerdo del Consejo de Ministros, previo informe del Consejo de Estado."}], "k": "b", "x": "Art. 13.3 CE.", "f": "Art. 13.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a13-3-extradicion:N2"}, {"c": "CE-a13-3-extradicion", "n": 3, "e": "¿Qué afirmación sobre la extradición se ajusta al art. 13.3 CE?", "o": [{"letra": "a", "texto": "Se excluyen los delitos políticos, pero el terrorismo no se considera delito político."}, {"letra": "b", "texto": "Se concede siempre que el delito tenga pena de prisión, sin atender a la reciprocidad."}, {"letra": "c", "texto": "Se excluyen los delitos políticos, incluidos los actos de terrorismo."}], "k": "a", "x": "Art. 13.3 CE: se exige tratado o ley y reciprocidad; los delitos políticos se excluyen, pero el terrorismo no se considera tal.", "f": "Art. 13.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a13-3-extradicion:N3"}, {"c": "CE-a13-4-asilo", "n": 1, "e": "Según el art. 13.4 CE, ¿pueden los apátridas gozar del derecho de asilo en España?", "o": [{"letra": "a", "texto": "Sí, en los términos que establezca la ley"}, {"letra": "b", "texto": "No, solo los ciudadanos de otros países"}], "k": "a", "x": "Art. 13.4 CE: los ciudadanos de otros países y los apátridas, en los términos que establezca la ley.", "f": "Art. 13.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a13-4-asilo:N1"}, {"c": "CE-a13-4-asilo", "n": 2, "e": "Según el art. 13.4 CE, los términos en que los ciudadanos de otros países y los apátridas podrán gozar del derecho de asilo en España los establecerá:", "o": [{"letra": "a", "texto": "El Gobierno por real decreto."}, {"letra": "b", "texto": "Un tratado internacional."}, {"letra": "c", "texto": "La ley."}], "k": "c", "x": "Art. 13.4 CE: «La ley establecerá los términos…».", "f": "Art. 13.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a13-4-asilo:N2"}, {"c": "CE-a13-4-asilo", "n": 3, "e": "El derecho de asilo del art. 13.4 CE se refiere a:", "o": [{"letra": "a", "texto": "Los ciudadanos de otros países y los apátridas."}, {"letra": "b", "texto": "Los extranjeros con residencia legal en España."}, {"letra": "c", "texto": "Únicamente los perseguidos por delitos políticos."}], "k": "a", "x": "Art. 13.4 CE: «los ciudadanos de otros países y los apátridas». No limita el asilo a perseguidos por delitos políticos ni a residentes.", "f": "Art. 13.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a13-4-asilo:N3"}, {"c": "CE-a14-igualdad", "n": 1, "e": "Según el art. 14 CE, los españoles son…", "o": [{"letra": "a", "texto": "iguales ante la ley"}, {"letra": "b", "texto": "iguales en derechos económicos"}], "k": "a", "x": "Art. 14 CE: los españoles son iguales ante la ley.", "f": "Art. 14 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a14-igualdad:N1"}, {"c": "CE-a14-igualdad", "n": 2, "e": "¿Cuál de estas causas de discriminación NO aparece citada expresamente en el art. 14 CE?", "o": [{"letra": "a", "texto": "Nacimiento."}, {"letra": "b", "texto": "Edad."}, {"letra": "c", "texto": "Opinión."}], "k": "b", "x": "El art. 14 cita nacimiento, raza, sexo, religión, opinión y «cualquier otra condición o circunstancia personal o social». La edad no se nombra expresamente.", "f": "Art. 14 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a14-igualdad:N2"}, {"c": "CE-a14-igualdad", "n": 3, "e": "El art. 14 CE, sobre la igualdad ante la ley, se encuentra:", "o": [{"letra": "a", "texto": "Dentro de la Sección primera del Capítulo segundo."}, {"letra": "b", "texto": "Al inicio del Capítulo segundo, antes de la Sección primera."}, {"letra": "c", "texto": "En el Título Preliminar, junto al art. 9."}], "k": "b", "x": "El art. 14 abre el Capítulo segundo («Derechos y libertades») y va antes de la Sección 1.ª, que empieza en el art. 15. Por eso el art. 53.2 lo cita aparte: «el artículo 14 y la Sección primera».", "f": "Art. 14 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a14-igualdad:N3"}, {"c": "CE-a15-vida-integridad", "n": 1, "e": "Según el art. 15 CE, ¿quiénes tienen derecho a la vida y a la integridad física y moral?", "o": [{"letra": "a", "texto": "Todos"}, {"letra": "b", "texto": "Solo los españoles"}], "k": "a", "x": "Art. 15 CE: «Todos tienen derecho a la vida…».", "f": "Art. 15 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a15-vida-integridad:N1"}, {"c": "CE-a15-vida-integridad", "n": 2, "e": "Según el art. 15 CE, todos tienen derecho a la vida y a la integridad:", "o": [{"letra": "a", "texto": "Personal y familiar."}, {"letra": "b", "texto": "Física y psíquica."}, {"letra": "c", "texto": "Física y moral."}], "k": "c", "x": "Art. 15 CE: integridad física y moral. «Intimidad personal y familiar» es del art. 18.1.", "f": "Art. 15 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a15-vida-integridad:N2"}, {"c": "CE-a15-vida-integridad", "n": 3, "e": "Según el art. 15 CE, la prohibición de someter a tortura o a penas o tratos inhumanos o degradantes:", "o": [{"letra": "a", "texto": "Puede suspenderse durante el estado de sitio."}, {"letra": "b", "texto": "Puede exceptuarse en tiempos de guerra por las leyes penales militares."}, {"letra": "c", "texto": "No admite excepciones en ningún caso."}], "k": "c", "x": "Art. 15 CE: «sin que, en ningún caso, puedan ser sometidos a tortura…». La excepción de tiempos de guerra se refiere solo a la pena de muerte, y el art. 15 no está entre los suspendibles del art. 55.", "f": "Art. 15 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a15-vida-integridad:N3"}, {"c": "CE-a15-pena-muerte", "n": 1, "e": "Según el texto del art. 15 CE, la pena de muerte…", "o": [{"letra": "a", "texto": "queda abolida, salvo lo que puedan disponer las leyes penales militares para tiempos de guerra"}, {"letra": "b", "texto": "queda abolida, salvo en los delitos de terrorismo cometidos durante el estado de sitio"}], "k": "a", "x": "Art. 15 CE: abolida «salvo lo que puedan disponer las leyes penales militares para tiempos de guerra». La Ley Orgánica 11/1995 la abolió también en tiempo de guerra, pero el texto constitucional conserva la salvedad.", "f": "Art. 15 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a15-pena-muerte:N1"}, {"c": "CE-a15-pena-muerte", "n": 2, "e": "Según el art. 15 CE, la abolición de la pena de muerte tiene como salvedad lo que puedan disponer:", "o": [{"letra": "a", "texto": "Las leyes orgánicas durante el estado de sitio."}, {"letra": "b", "texto": "El Código Penal para los delitos de terrorismo."}, {"letra": "c", "texto": "Las leyes penales militares para tiempos de guerra."}], "k": "c", "x": "Art. 15 CE. Hoy no existe en la práctica, porque la Ley Orgánica 11/1995 la abolió también en tiempo de guerra, pero el texto constitucional mantiene la salvedad.", "f": "Art. 15 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a15-pena-muerte:N2"}, {"c": "CE-a15-pena-muerte", "n": 3, "e": "Un compañero afirma: «el art. 15 CE permite la pena de muerte durante el estado de sitio». ¿Es correcto?", "o": [{"letra": "a", "texto": "Sí: durante el estado de sitio rigen las leyes penales militares, que pueden imponer la pena de muerte."}, {"letra": "b", "texto": "No: la salvedad del art. 15 se limita a las leyes penales militares para tiempos de guerra."}, {"letra": "c", "texto": "Sí, siempre que lo autorice el Congreso por mayoría absoluta."}], "k": "b", "x": "Art. 15 CE: la única salvedad es «lo que puedan disponer las leyes penales militares para tiempos de guerra». El estado de sitio no la activa.", "f": "Art. 15 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a15-pena-muerte:N3"}, {"c": "CE-a16-1-libertad-ideologica", "n": 1, "e": "Según el art. 16.1 CE, ¿qué libertad se garantiza?", "o": [{"letra": "a", "texto": "La libertad de cátedra"}, {"letra": "b", "texto": "La libertad ideológica, religiosa y de culto"}], "k": "b", "x": "Art. 16.1 CE. La libertad de cátedra está en el art. 20.1.c).", "f": "Art. 16.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a16-1-libertad-ideologica:N1"}, {"c": "CE-a16-1-libertad-ideologica", "n": 2, "e": "Según el art. 16.1 CE, la libertad ideológica, religiosa y de culto no tiene más limitación, en sus manifestaciones, que:", "o": [{"letra": "a", "texto": "La protección de la juventud y de la infancia."}, {"letra": "b", "texto": "El respeto a las creencias de los demás y a la cooperación con la Iglesia Católica y las otras confesiones."}, {"letra": "c", "texto": "La necesaria para el mantenimiento del orden público protegido por la ley."}], "k": "c", "x": "Art. 16.1 CE. La protección de la juventud y de la infancia es un límite de las libertades del art. 20 (art. 20.4).", "f": "Art. 16.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a16-1-libertad-ideologica:N2"}, {"c": "CE-a16-1-libertad-ideologica", "n": 3, "e": "Según el art. 16.1 CE, ¿de quiénes se garantiza la libertad ideológica, religiosa y de culto?", "o": [{"letra": "a", "texto": "De los individuos y las comunidades."}, {"letra": "b", "texto": "De los ciudadanos españoles y de las confesiones inscritas."}, {"letra": "c", "texto": "Solo de los individuos, nunca de las comunidades."}], "k": "a", "x": "Art. 16.1 CE: «de los individuos y las comunidades».", "f": "Art. 16.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a16-1-libertad-ideologica:N3"}, {"c": "CE-a16-2-no-declarar", "n": 1, "e": "Según el art. 16.2 CE, ¿puede alguien ser obligado a declarar sobre su religión?", "o": [{"letra": "a", "texto": "No"}, {"letra": "b", "texto": "Sí, si lo exige la ley"}], "k": "a", "x": "Art. 16.2 CE: nadie podrá ser obligado a declarar sobre su ideología, religión o creencias.", "f": "Art. 16.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a16-2-no-declarar:N1"}, {"c": "CE-a16-2-no-declarar", "n": 2, "e": "Según el art. 16.2 CE, nadie podrá ser obligado a declarar sobre su:", "o": [{"letra": "a", "texto": "Patrimonio, religión o creencias."}, {"letra": "b", "texto": "Ideología, afiliación sindical o religión."}, {"letra": "c", "texto": "Ideología, religión o creencias."}], "k": "c", "x": "Art. 16.2 CE: ideología, religión o creencias.", "f": "Art. 16.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a16-2-no-declarar:N2"}, {"c": "CE-a16-2-no-declarar", "n": 3, "e": "¿Qué artículo de la Constitución establece que nadie podrá ser obligado a declarar sobre su ideología, religión o creencias?", "o": [{"letra": "a", "texto": "El art. 16.2."}, {"letra": "b", "texto": "El art. 24.2."}, {"letra": "c", "texto": "El art. 17.3."}], "k": "a", "x": "Art. 16.2 CE. El 17.3 recoge que el detenido no puede ser obligado a declarar y el 24.2, el derecho a no declarar contra sí mismo.", "f": "Art. 16.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a16-2-no-declarar:N3"}, {"c": "CE-a16-3-aconfesionalidad", "n": 1, "e": "Según el art. 16.3 CE, ¿tiene alguna confesión carácter estatal?", "o": [{"letra": "a", "texto": "No, ninguna"}, {"letra": "b", "texto": "Sí, la católica"}], "k": "a", "x": "Art. 16.3 CE: ninguna confesión tendrá carácter estatal.", "f": "Art. 16.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a16-3-aconfesionalidad:N1"}, {"c": "CE-a16-3-aconfesionalidad", "n": 2, "e": "Según el art. 16.3 CE, los poderes públicos mantendrán relaciones de cooperación con:", "o": [{"letra": "a", "texto": "La Iglesia Católica y las demás confesiones."}, {"letra": "b", "texto": "Las confesiones inscritas en el registro de asociaciones."}, {"letra": "c", "texto": "La Iglesia Católica, exclusivamente."}], "k": "a", "x": "Art. 16.3 CE: con la Iglesia Católica y las demás confesiones.", "f": "Art. 16.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a16-3-aconfesionalidad:N2"}, {"c": "CE-a16-3-aconfesionalidad", "n": 3, "e": "¿Qué afirmación se ajusta al art. 16.3 CE?", "o": [{"letra": "a", "texto": "La religión católica tiene carácter oficial y las demás son toleradas."}, {"letra": "b", "texto": "Ninguna confesión tiene carácter estatal, pero los poderes públicos tienen en cuenta las creencias religiosas de la sociedad española."}, {"letra": "c", "texto": "El Estado es laico: los poderes públicos no tienen en cuenta las creencias religiosas ni mantienen relaciones con ninguna confesión."}], "k": "b", "x": "Art. 16.3 CE: aconfesionalidad con cooperación («tendrán en cuenta las creencias religiosas… y mantendrán las consiguientes relaciones de cooperación»).", "f": "Art. 16.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a16-3-aconfesionalidad:N3"}, {"c": "CE-a17-1-libertad-seguridad", "n": 1, "e": "Según el art. 17.1 CE, toda persona tiene derecho a la libertad y a la…", "o": [{"letra": "a", "texto": "seguridad"}, {"letra": "b", "texto": "propiedad"}], "k": "a", "x": "Art. 17.1 CE: derecho a la libertad y a la seguridad.", "f": "Art. 17.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a17-1-libertad-seguridad:N1"}, {"c": "CE-a17-1-libertad-seguridad", "n": 2, "e": "Según el art. 17.1 CE, nadie puede ser privado de su libertad sino:", "o": [{"letra": "a", "texto": "Por resolución judicial firme, en todo caso."}, {"letra": "b", "texto": "Con la observancia de lo establecido en este artículo y en los casos y en la forma previstos en la ley."}, {"letra": "c", "texto": "Por orden de la autoridad gubernativa en los casos de alteración del orden público."}], "k": "b", "x": "Art. 17.1 CE.", "f": "Art. 17.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a17-1-libertad-seguridad:N2"}, {"c": "CE-a17-1-libertad-seguridad", "n": 3, "e": "El derecho a la libertad y a la seguridad del art. 17.1 CE corresponde a:", "o": [{"letra": "a", "texto": "Toda persona."}, {"letra": "b", "texto": "Los ciudadanos, en los términos que establezca la ley."}, {"letra": "c", "texto": "Los españoles y los extranjeros con residencia legal."}], "k": "a", "x": "Art. 17.1 CE: «Toda persona tiene derecho…».", "f": "Art. 17.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a17-1-libertad-seguridad:N3"}, {"c": "CE-a17-2-72-horas", "n": 1, "e": "Según el art. 17.2 CE, el plazo máximo de la detención preventiva es de…", "o": [{"letra": "a", "texto": "setenta y dos horas"}, {"letra": "b", "texto": "cuarenta y ocho horas"}], "k": "a", "x": "Art. 17.2 CE: en todo caso, setenta y dos horas como máximo.", "f": "Art. 17.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a17-2-72-horas:N1"}, {"c": "CE-a17-2-72-horas", "n": 2, "e": "Según el art. 17.2 CE, la detención preventiva no podrá durar más del tiempo estrictamente necesario y, en todo caso, en el plazo máximo de setenta y dos horas el detenido deberá ser:", "o": [{"letra": "a", "texto": "Puesto a disposición del Ministerio Fiscal."}, {"letra": "b", "texto": "Informado de sus derechos y asistido por abogado."}, {"letra": "c", "texto": "Puesto en libertad o a disposición de la autoridad judicial."}], "k": "c", "x": "Art. 17.2 CE: en libertad o a disposición de la autoridad judicial.", "f": "Art. 17.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a17-2-72-horas:N2"}, {"c": "CE-a17-2-72-horas", "n": 3, "e": "Según el art. 17.2 CE, ¿qué afirmación es correcta sobre la duración de la detención preventiva?", "o": [{"letra": "a", "texto": "Nunca puede superar las setenta y dos horas ni lo estrictamente necesario para las averiguaciones."}, {"letra": "b", "texto": "Puede durar siempre setenta y dos horas completas, aunque las averiguaciones hayan terminado antes."}, {"letra": "c", "texto": "Puede prorrogarse otras setenta y dos horas por orden gubernativa."}], "k": "a", "x": "Art. 17.2 CE: «no podrá durar más del tiempo estrictamente necesario… y, en todo caso, en el plazo máximo de setenta y dos horas».", "f": "Art. 17.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a17-2-72-horas:N3"}, {"c": "CE-a17-3-detenido", "n": 1, "e": "Según el art. 17.3 CE, ¿puede ser obligada a declarar una persona detenida?", "o": [{"letra": "a", "texto": "Sí, ante la policía"}, {"letra": "b", "texto": "No"}], "k": "b", "x": "Art. 17.3 CE: no pudiendo ser obligada a declarar.", "f": "Art. 17.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a17-3-detenido:N1"}, {"c": "CE-a17-3-detenido", "n": 2, "e": "Según el art. 17.3 CE, toda persona detenida debe ser informada de sus derechos y de las razones de su detención:", "o": [{"letra": "a", "texto": "En presencia de su abogado y del juez."}, {"letra": "b", "texto": "De forma inmediata y de modo que le sea comprensible."}, {"letra": "c", "texto": "En el plazo de veinticuatro horas y por escrito."}], "k": "b", "x": "Art. 17.3 CE: «de forma inmediata, y de modo que le sea comprensible».", "f": "Art. 17.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a17-3-detenido:N2"}, {"c": "CE-a17-3-detenido", "n": 3, "e": "Según el art. 17.3 CE, la asistencia de abogado al detenido se garantiza:", "o": [{"letra": "a", "texto": "Solo en las diligencias judiciales; en las policiales, si lo autoriza el juez de guardia."}, {"letra": "b", "texto": "En las diligencias policiales y judiciales, en los términos que la ley establezca."}, {"letra": "c", "texto": "Solo cuando el detenido lo solicite expresamente y por escrito."}], "k": "b", "x": "Art. 17.3 CE: «en las diligencias policiales y judiciales, en los términos que la ley establezca».", "f": "Art. 17.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a17-3-detenido:N3"}, {"c": "CE-a17-4-habeas-corpus", "n": 1, "e": "Según el art. 17.4 CE, el procedimiento de «habeas corpus» sirve para la inmediata puesta a disposición judicial de toda persona…", "o": [{"letra": "a", "texto": "detenida ilegalmente"}, {"letra": "b", "texto": "condenada en rebeldía"}], "k": "a", "x": "Art. 17.4 CE: de toda persona detenida ilegalmente.", "f": "Art. 17.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a17-4-habeas-corpus:N1"}, {"c": "CE-a17-4-habeas-corpus", "n": 2, "e": "Según el art. 17.4 CE, ¿quién determinará el plazo máximo de duración de la prisión provisional?", "o": [{"letra": "a", "texto": "La autoridad judicial en cada caso."}, {"letra": "b", "texto": "La ley."}, {"letra": "c", "texto": "La propia Constitución: setenta y dos horas."}], "k": "b", "x": "Art. 17.4 CE: «por ley se determinará el plazo máximo de duración de la prisión provisional». Las setenta y dos horas son de la detención preventiva (art. 17.2).", "f": "Art. 17.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a17-4-habeas-corpus:N2"}, {"c": "CE-a17-4-habeas-corpus", "n": 3, "e": "¿Qué diferencia hay entre los apartados 2 y 4 del art. 17 CE?", "o": [{"letra": "a", "texto": "Ambos fijan en la Constitución el mismo plazo de setenta y dos horas."}, {"letra": "b", "texto": "El 17.2 remite a la ley el máximo de la detención preventiva; el 17.4 fija en 72 horas la prisión provisional."}, {"letra": "c", "texto": "El 17.2 fija el máximo de la detención preventiva; el 17.4 remite a la ley el de la prisión provisional."}], "k": "c", "x": "Detención preventiva: máximo 72 horas fijado por la Constitución (17.2). Prisión provisional: plazo máximo que fija la ley (17.4).", "f": "Art. 17.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a17-4-habeas-corpus:N3"}]'::jsonb) AS x(c text, n int, e text, o jsonb, k text, x text, f text, h text);
UPDATE public.questions q SET enunciado = qq.e, opciones = qq.o, correcta = qq.k, explicacion = qq.x, fuente_normativa = qq.f, nivel = qq.n, concept_id = qq.c, estado = 'publicada', topic_id = (SELECT id FROM _tema) FROM _qq qq WHERE q.hash_dedupe = qq.h;
INSERT INTO public.questions (topic_id, enunciado, opciones, correcta, explicacion, fuente_normativa, estado, nivel, origen_tipo, origen_archivo, concept_id, hash_dedupe) SELECT (SELECT id FROM _tema), qq.e, qq.o, qq.k, qq.x, qq.f, 'publicada', qq.n, 'propio', 'data/constitucion/titulo-i.json', qq.c, qq.h FROM _qq qq WHERE NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.hash_dedupe = qq.h);
COMMIT;
-- BLOQUE
BEGIN;
CREATE TEMP TABLE _tema ON COMMIT DROP AS SELECT id FROM public.topics WHERE convocatoria_id = 1 AND numero = 1;
DO $$ BEGIN IF (SELECT count(*) FROM _tema) <> 1 THEN RAISE EXCEPTION 'tema 1 de la convocatoria 1 no encontrado o duplicado'; END IF; END $$;
WITH cc AS (SELECT * FROM jsonb_to_recordset('[{"id": "CE-a18-1-honor", "apartado": "Título I · Art. 18.1", "orden": 500, "pregunta": "¿Qué tres derechos garantiza el art. 18.1 CE?", "respuesta": "El derecho al honor, a la intimidad personal y familiar y a la propia imagen.", "fuente": "Constitución Española, art. 18.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Se garantiza el derecho al honor, a la intimidad personal y familiar y a la propia imagen.", "tipo": "lista", "prioridad": 1, "conf": ["CE-a20-4-limites"]}, {"id": "CE-a18-2-domicilio", "apartado": "Título I · Art. 18.2", "orden": 510, "pregunta": "¿En qué tres supuestos se puede entrar o registrar un domicilio (art. 18.2 CE)?", "respuesta": "Con consentimiento del titular, con resolución judicial o en caso de flagrante delito.", "fuente": "Constitución Española, art. 18.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Ninguna entrada o registro podrá hacerse en él sin consentimiento del titular o resolución judicial, salvo en caso de flagrante delito.", "tipo": "lista", "prioridad": 1, "conf": ["CE-a18-3-comunicaciones", "CE-a55-1-suspension"]}, {"id": "CE-a18-3-comunicaciones", "apartado": "Título I · Art. 18.3", "orden": 520, "pregunta": "¿Qué garantiza el art. 18.3 CE y cuál es su excepción?", "respuesta": "El secreto de las comunicaciones, en especial postales, telegráficas y telefónicas, salvo resolución judicial.", "fuente": "Constitución Española, art. 18.3 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Se garantiza el secreto de las comunicaciones y, en especial, de las postales, telegráficas y telefónicas, salvo resolución judicial.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a18-2-domicilio"]}, {"id": "CE-a18-4-informatica", "apartado": "Título I · Art. 18.4", "orden": 530, "pregunta": "¿Para qué limitará la ley el uso de la informática (art. 18.4 CE)?", "respuesta": "Para garantizar el honor y la intimidad personal y familiar de los ciudadanos y el pleno ejercicio de sus derechos.", "fuente": "Constitución Española, art. 18.4 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "La ley limitará el uso de la informática para garantizar el honor y la intimidad personal y familiar de los ciudadanos y el pleno ejercicio de sus derechos.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a18-1-honor"]}, {"id": "CE-a19-residencia-circulacion", "apartado": "Título I · Art. 19", "orden": 540, "pregunta": "¿Qué derechos reconoce el art. 19 CE y qué límite prohíbe?", "respuesta": "Elegir libremente residencia, circular por el territorio nacional y entrar y salir libremente de España en los términos de la ley; este derecho no puede limitarse por motivos políticos o ideológicos.", "fuente": "Constitución Española, art. 19 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Este derecho no podrá ser limitado por motivos políticos o ideológicos.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a55-1-suspension"]}, {"id": "CE-a20-1-expresion", "apartado": "Título I · Art. 20.1", "orden": 550, "pregunta": "¿Qué cuatro derechos reconoce y protege el art. 20.1 CE?", "respuesta": "a) Expresar y difundir libremente pensamientos, ideas y opiniones; b) la producción y creación literaria, artística, científica y técnica; c) la libertad de cátedra; d) comunicar o recibir libremente información veraz.", "fuente": "Constitución Española, art. 20.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "A expresar y difundir libremente los pensamientos, ideas y opiniones mediante la palabra, el escrito o cualquier otro medio de reproducción.", "tipo": "lista", "prioridad": 1, "conf": ["CE-a20-1-informacion", "CE-a16-1-libertad-ideologica"]}, {"id": "CE-a20-1-informacion", "apartado": "Título I · Art. 20.1", "orden": 560, "pregunta": "¿Qué información protege el art. 20.1.d) CE y qué regulará la ley en este ámbito?", "respuesta": "Comunicar o recibir libremente información veraz por cualquier medio de difusión; la ley regulará la cláusula de conciencia y el secreto profesional.", "fuente": "Constitución Española, art. 20.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "A comunicar o recibir libremente información veraz por cualquier medio de difusión.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a20-1-expresion", "CE-a24-2-parentesco"]}, {"id": "CE-a20-2-censura", "apartado": "Título I · Art. 20.2", "orden": 570, "pregunta": "¿Puede restringirse el ejercicio de los derechos del art. 20 mediante censura previa?", "respuesta": "No: no puede restringirse mediante ningún tipo de censura previa (art. 20.2 CE).", "fuente": "Constitución Española, art. 20.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "El ejercicio de estos derechos no puede restringirse mediante ningún tipo de censura previa.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a20-5-secuestro"]}, {"id": "CE-a20-3-medios-publicos", "apartado": "Título I · Art. 20.3", "orden": 580, "pregunta": "¿Qué regulará la ley sobre los medios de comunicación públicos (art. 20.3 CE)?", "respuesta": "Su organización y control parlamentario, y garantizará el acceso de los grupos sociales y políticos significativos, respetando el pluralismo y las diversas lenguas de España.", "fuente": "Constitución Española, art. 20.3 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "La ley regulará la organización y el control parlamentario de los medios de comunicación social dependientes del Estado o de cualquier ente público", "tipo": "regla", "prioridad": 3, "conf": []}, {"id": "CE-a20-4-limites", "apartado": "Título I · Art. 20.4", "orden": 590, "pregunta": "¿Cuál es el límite de las libertades del art. 20 CE?", "respuesta": "El respeto a los derechos del Título I, a las leyes que lo desarrollen y, especialmente, al derecho al honor, a la intimidad, a la propia imagen y a la protección de la juventud y de la infancia.", "fuente": "Constitución Española, art. 20.4 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "especialmente, en el derecho al honor, a la intimidad, a la propia imagen y a la protección de la juventud y de la infancia", "tipo": "lista", "prioridad": 1, "conf": ["CE-a18-1-honor"]}, {"id": "CE-a20-5-secuestro", "apartado": "Título I · Art. 20.5", "orden": 600, "pregunta": "¿Cómo puede acordarse el secuestro de publicaciones, grabaciones y otros medios de información (art. 20.5 CE)?", "respuesta": "Solo en virtud de resolución judicial.", "fuente": "Constitución Española, art. 20.5 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Sólo podrá acordarse el secuestro de publicaciones, grabaciones y otros medios de información en virtud de resolución judicial.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a20-2-censura", "CE-a22-4-disolucion"]}, {"id": "CE-a21-1-reunion", "apartado": "Título I · Art. 21.1", "orden": 610, "pregunta": "¿Qué reunión reconoce el art. 21.1 CE y necesita autorización previa?", "respuesta": "La reunión pacífica y sin armas; su ejercicio no necesita autorización previa.", "fuente": "Constitución Española, art. 21.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Se reconoce el derecho de reunión pacífica y sin armas. El ejercicio de este derecho no necesitará autorización previa.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a21-2-manifestaciones", "CE-a22-1-asociacion"]}, {"id": "CE-a21-2-manifestaciones", "apartado": "Título I · Art. 21.2", "orden": 620, "pregunta": "¿Qué exige el art. 21.2 CE para reuniones en lugares de tránsito público y manifestaciones, y cuándo pueden prohibirse?", "respuesta": "Comunicación previa a la autoridad, que solo puede prohibirlas por razones fundadas de alteración del orden público, con peligro para personas o bienes.", "fuente": "Constitución Española, art. 21.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "que sólo podrá prohibirlas cuando existan razones fundadas de alteración del orden público, con peligro para personas o bienes", "tipo": "regla", "prioridad": 1, "conf": ["CE-a21-1-reunion"]}, {"id": "CE-a22-1-asociacion", "apartado": "Título I · Art. 22.1", "orden": 630, "pregunta": "¿Qué derecho reconoce el art. 22.1 CE?", "respuesta": "El derecho de asociación.", "fuente": "Constitución Española, art. 22.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Se reconoce el derecho de asociación.", "tipo": "dato", "prioridad": 2, "conf": ["CE-a21-1-reunion", "CE-a34-1-fundacion"]}, {"id": "CE-a22-2-ilegales", "apartado": "Título I · Art. 22.2", "orden": 640, "pregunta": "¿Qué asociaciones son ilegales según el art. 22.2 CE?", "respuesta": "Las que persigan fines o utilicen medios tipificados como delito.", "fuente": "Constitución Española, art. 22.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Las asociaciones que persigan fines o utilicen medios tipificados como delito son ilegales.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a22-5-prohibidas"]}, {"id": "CE-a22-3-registro", "apartado": "Título I · Art. 22.3", "orden": 650, "pregunta": "¿Con qué efectos se inscriben las asociaciones en un registro (art. 22.3 CE)?", "respuesta": "A los solos efectos de publicidad.", "fuente": "Constitución Española, art. 22.3 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Las asociaciones constituidas al amparo de este artículo deberán inscribirse en un registro a los solos efectos de publicidad.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a22-2-ilegales"]}, {"id": "CE-a22-4-disolucion", "apartado": "Título I · Art. 22.4", "orden": 660, "pregunta": "¿Cómo pueden disolverse o suspenderse las asociaciones (art. 22.4 CE)?", "respuesta": "Solo en virtud de resolución judicial motivada.", "fuente": "Constitución Española, art. 22.4 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Las asociaciones sólo podrán ser disueltas o suspendidas en sus actividades en virtud de resolución judicial motivada.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a20-5-secuestro", "CE-a34-2-remision"]}, {"id": "CE-a22-5-prohibidas", "apartado": "Título I · Art. 22.5", "orden": 670, "pregunta": "¿Qué asociaciones prohíbe el art. 22.5 CE?", "respuesta": "Las asociaciones secretas y las de carácter paramilitar.", "fuente": "Constitución Española, art. 22.5 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Se prohíben las asociaciones secretas y las de carácter paramilitar.", "tipo": "lista", "prioridad": 1, "conf": ["CE-a22-2-ilegales"]}, {"id": "CE-a23-1-participacion", "apartado": "Título I · Art. 23.1", "orden": 680, "pregunta": "¿Qué derecho reconoce el art. 23.1 CE?", "respuesta": "El de los ciudadanos a participar en los asuntos públicos, directamente o por medio de representantes libremente elegidos en elecciones periódicas por sufragio universal.", "fuente": "Constitución Española, art. 23.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Los ciudadanos tienen el derecho a participar en los asuntos públicos, directamente o por medio de representantes, libremente elegidos en elecciones periódicas por sufragio universal.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a13-2-sufragio-municipal", "CE-a23-2-acceso-cargos"]}, {"id": "CE-a23-2-acceso-cargos", "apartado": "Título I · Art. 23.2", "orden": 690, "pregunta": "¿Qué derecho recoge el art. 23.2 CE?", "respuesta": "El de acceder en condiciones de igualdad a las funciones y cargos públicos, con los requisitos que señalen las leyes.", "fuente": "Constitución Española, art. 23.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "tienen derecho a acceder en condiciones de igualdad a las funciones y cargos públicos, con los requisitos que señalen las leyes", "tipo": "regla", "prioridad": 1, "conf": ["CE-a23-1-participacion", "CE-a14-igualdad"]}]'::jsonb) AS x(id text, apartado text, orden int, pregunta text, respuesta text, fuente text, cita text, tipo text, prioridad smallint, conf text[])) INSERT INTO public.concepts (id, topic_id, documento, apartado, orden, pregunta, respuesta, fuente, cita, tipo, prioridad, confundible_con, estado) SELECT cc.id, t.id, 'CE', cc.apartado, cc.orden, cc.pregunta, cc.respuesta, cc.fuente, cc.cita, cc.tipo, cc.prioridad, coalesce(cc.conf, '{}'), 'publicado' FROM cc, _tema t ON CONFLICT (id) DO UPDATE SET topic_id = EXCLUDED.topic_id, documento = EXCLUDED.documento, apartado = EXCLUDED.apartado, orden = EXCLUDED.orden, pregunta = EXCLUDED.pregunta, respuesta = EXCLUDED.respuesta, fuente = EXCLUDED.fuente, cita = EXCLUDED.cita, tipo = EXCLUDED.tipo, prioridad = EXCLUDED.prioridad, confundible_con = EXCLUDED.confundible_con, estado = EXCLUDED.estado;
CREATE TEMP TABLE _qq ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"c": "CE-a18-1-honor", "n": 1, "e": "Según el art. 18.1 CE, se garantiza el derecho al honor, a la intimidad personal y familiar y…", "o": [{"letra": "a", "texto": "a la propia imagen"}, {"letra": "b", "texto": "a la libertad de expresión"}], "k": "a", "x": "Art. 18.1 CE.", "f": "Art. 18.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a18-1-honor:N1"}, {"c": "CE-a18-1-honor", "n": 2, "e": "Según el art. 18.1 CE, la intimidad que se garantiza es la:", "o": [{"letra": "a", "texto": "Personal y profesional."}, {"letra": "b", "texto": "Física y moral."}, {"letra": "c", "texto": "Personal y familiar."}], "k": "c", "x": "Art. 18.1 CE: intimidad personal y familiar. La integridad «física y moral» es del art. 15.", "f": "Art. 18.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a18-1-honor:N2"}, {"c": "CE-a18-1-honor", "n": 3, "e": "¿Cuál de los siguientes derechos NO figura en el art. 18.1 CE?", "o": [{"letra": "a", "texto": "El derecho a la protección de datos personales."}, {"letra": "b", "texto": "El derecho a la propia imagen de las personas."}, {"letra": "c", "texto": "El derecho al honor, junto con la intimidad."}], "k": "a", "x": "El art. 18.1 recoge honor, intimidad personal y familiar y propia imagen. El uso de la informática se trata en el art. 18.4, pero la expresión «protección de datos personales» no aparece en el art. 18.1.", "f": "Art. 18.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a18-1-honor:N3"}, {"c": "CE-a18-2-domicilio", "n": 1, "e": "Según el art. 18.2 CE, el domicilio es…", "o": [{"letra": "a", "texto": "inviolable"}, {"letra": "b", "texto": "de libre acceso para la autoridad"}], "k": "a", "x": "Art. 18.2 CE: «El domicilio es inviolable».", "f": "Art. 18.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a18-2-domicilio:N1"}, {"c": "CE-a18-2-domicilio", "n": 2, "e": "Según el art. 18.2 CE, ninguna entrada o registro podrá hacerse en el domicilio sin consentimiento del titular o resolución judicial, salvo en caso de:", "o": [{"letra": "a", "texto": "Alteración grave del orden público."}, {"letra": "b", "texto": "Orden de la autoridad gubernativa."}, {"letra": "c", "texto": "Flagrante delito."}], "k": "c", "x": "Art. 18.2 CE: salvo en caso de flagrante delito.", "f": "Art. 18.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a18-2-domicilio:N2"}, {"c": "CE-a18-2-domicilio", "n": 3, "e": "Según el art. 18.2 CE, ¿cuál de estos supuestos NO permite entrar en un domicilio?", "o": [{"letra": "a", "texto": "Una orden escrita del Delegado del Gobierno."}, {"letra": "b", "texto": "El consentimiento del titular del domicilio."}, {"letra": "c", "texto": "Una resolución judicial que la autorice."}], "k": "a", "x": "Art. 18.2 CE: solo consentimiento del titular, resolución judicial o flagrante delito. La orden gubernativa no habilita la entrada.", "f": "Art. 18.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a18-2-domicilio:N3"}, {"c": "CE-a18-3-comunicaciones", "n": 1, "e": "Según el art. 18.3 CE, el secreto de las comunicaciones puede levantarse por…", "o": [{"letra": "a", "texto": "orden policial"}, {"letra": "b", "texto": "resolución judicial"}], "k": "b", "x": "Art. 18.3 CE: salvo resolución judicial.", "f": "Art. 18.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a18-3-comunicaciones:N1"}, {"c": "CE-a18-3-comunicaciones", "n": 2, "e": "Según el art. 18.3 CE, se garantiza el secreto de las comunicaciones y, en especial, de las:", "o": [{"letra": "a", "texto": "Postales, telegráficas y telefónicas."}, {"letra": "b", "texto": "Postales, telefónicas y bancarias."}, {"letra": "c", "texto": "Telefónicas, electrónicas e informáticas."}], "k": "a", "x": "Art. 18.3 CE: postales, telegráficas y telefónicas.", "f": "Art. 18.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a18-3-comunicaciones:N2"}, {"c": "CE-a18-3-comunicaciones", "n": 3, "e": "A diferencia del domicilio (art. 18.2), el secreto de las comunicaciones del art. 18.3 CE:", "o": [{"letra": "a", "texto": "Cede también en caso de flagrante delito."}, {"letra": "b", "texto": "Solo cede por resolución judicial; no menciona el consentimiento ni el flagrante delito."}, {"letra": "c", "texto": "Cede por consentimiento de cualquiera de los comunicantes o por orden gubernativa."}], "k": "b", "x": "Art. 18.3 CE: la única excepción expresa es la resolución judicial.", "f": "Art. 18.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a18-3-comunicaciones:N3"}, {"c": "CE-a18-4-informatica", "n": 1, "e": "Según el art. 18.4 CE, ¿qué limitará la ley para garantizar el honor y la intimidad?", "o": [{"letra": "a", "texto": "El uso de la informática"}, {"letra": "b", "texto": "El uso de la prensa escrita"}], "k": "a", "x": "Art. 18.4 CE.", "f": "Art. 18.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a18-4-informatica:N1"}, {"c": "CE-a18-4-informatica", "n": 2, "e": "Según el art. 18.4 CE, la ley limitará el uso de la informática para garantizar:", "o": [{"letra": "a", "texto": "La seguridad nacional, el orden público y la persecución de los delitos cometidos a través de la red."}, {"letra": "b", "texto": "El honor y la intimidad personal y familiar y el pleno ejercicio de sus derechos."}, {"letra": "c", "texto": "La libertad de información y el secreto profesional."}], "k": "b", "x": "Art. 18.4 CE.", "f": "Art. 18.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a18-4-informatica:N2"}, {"c": "CE-a18-4-informatica", "n": 3, "e": "¿Qué apartado del art. 18 CE se refiere al uso de la informática?", "o": [{"letra": "a", "texto": "El apartado 3."}, {"letra": "b", "texto": "El apartado 1."}, {"letra": "c", "texto": "El apartado 4."}], "k": "c", "x": "Art. 18.4 CE. El 18.3 trata del secreto de las comunicaciones.", "f": "Art. 18.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a18-4-informatica:N3"}, {"c": "CE-a19-residencia-circulacion", "n": 1, "e": "Según el art. 19 CE, los españoles tienen derecho a elegir libremente su residencia y a…", "o": [{"letra": "a", "texto": "circular por el territorio nacional"}, {"letra": "b", "texto": "elegir libremente su nacionalidad"}], "k": "a", "x": "Art. 19 CE.", "f": "Art. 19 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a19-residencia-circulacion:N1"}, {"c": "CE-a19-residencia-circulacion", "n": 2, "e": "Según el art. 19 CE, el derecho a entrar y salir libremente de España no podrá ser limitado por motivos:", "o": [{"letra": "a", "texto": "Sanitarios o de seguridad."}, {"letra": "b", "texto": "Económicos o fiscales."}, {"letra": "c", "texto": "Políticos o ideológicos."}], "k": "c", "x": "Art. 19 CE: «no podrá ser limitado por motivos políticos o ideológicos».", "f": "Art. 19 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a19-residencia-circulacion:N2"}, {"c": "CE-a19-residencia-circulacion", "n": 3, "e": "Según el art. 19 CE, ¿quiénes son titulares del derecho a elegir libremente la residencia y a circular por el territorio nacional?", "o": [{"letra": "a", "texto": "Los españoles y los ciudadanos de la Unión Europea."}, {"letra": "b", "texto": "Los españoles."}, {"letra": "c", "texto": "Todas las personas."}], "k": "b", "x": "Art. 19 CE: «Los españoles tienen derecho…». Para los extranjeros rige el art. 13.1 (tratados y ley).", "f": "Art. 19 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a19-residencia-circulacion:N3"}, {"c": "CE-a20-1-expresion", "n": 1, "e": "¿Reconoce el art. 20.1 CE la libertad de cátedra?", "o": [{"letra": "a", "texto": "No, la reconoce el art. 27"}, {"letra": "b", "texto": "Sí"}], "k": "b", "x": "Art. 20.1.c) CE: «A la libertad de cátedra». El art. 27 reconoce la libertad de enseñanza.", "f": "Art. 20.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a20-1-expresion:N1"}, {"c": "CE-a20-1-expresion", "n": 2, "e": "Según el art. 20.1.b) CE, se reconoce y protege el derecho a la producción y creación:", "o": [{"letra": "a", "texto": "Literaria, artística, científica y técnica."}, {"letra": "b", "texto": "Científica, técnica e industrial."}, {"letra": "c", "texto": "Literaria, artística y cultural, en todas sus formas."}], "k": "a", "x": "Art. 20.1.b) CE: literaria, artística, científica y técnica.", "f": "Art. 20.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a20-1-expresion:N2"}, {"c": "CE-a20-1-expresion", "n": 3, "e": "Según el art. 20.1.a) CE, el derecho a expresar y difundir libremente pensamientos, ideas y opiniones se ejerce:", "o": [{"letra": "a", "texto": "Por cualquier medio, previa comunicación a la autoridad."}, {"letra": "b", "texto": "Mediante la palabra y el escrito, con exclusión de los medios audiovisuales."}, {"letra": "c", "texto": "Mediante la palabra, el escrito o cualquier otro medio de reproducción."}], "k": "c", "x": "Art. 20.1.a) CE. No hay comunicación previa: el art. 20.2 prohíbe incluso la censura previa.", "f": "Art. 20.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a20-1-expresion:N3"}, {"c": "CE-a20-1-informacion", "n": 1, "e": "Según el art. 20.1.d) CE, el derecho a comunicar o recibir libremente información se refiere a información…", "o": [{"letra": "a", "texto": "oficial"}, {"letra": "b", "texto": "veraz"}], "k": "b", "x": "Art. 20.1.d) CE: información veraz.", "f": "Art. 20.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a20-1-informacion:N1"}, {"c": "CE-a20-1-informacion", "n": 2, "e": "Según el art. 20.1.d) CE, la ley regulará en el ejercicio de las libertades de información:", "o": [{"letra": "a", "texto": "El registro obligatorio de los periodistas."}, {"letra": "b", "texto": "El derecho a la cláusula de conciencia y al secreto profesional."}, {"letra": "c", "texto": "La autorización previa de los medios de comunicación."}], "k": "b", "x": "Art. 20.1.d) CE.", "f": "Art. 20.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a20-1-informacion:N2"}, {"c": "CE-a20-1-informacion", "n": 3, "e": "El «secreto profesional» aparece en el Título I de la Constitución:", "o": [{"letra": "a", "texto": "Solo en el art. 20.1.d), referido a los periodistas y demás profesionales de la información."}, {"letra": "b", "texto": "En el art. 20.1.d) (información) y en el art. 24.2 (obligación de declarar)."}, {"letra": "c", "texto": "Solo en el art. 24.2, sobre la obligación de declarar."}], "k": "b", "x": "El art. 20.1.d) remite a la ley el secreto profesional de los informadores, y el art. 24.2 permite no declarar por razón de parentesco o secreto profesional.", "f": "Art. 20.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a20-1-informacion:N3"}, {"c": "CE-a20-2-censura", "n": 1, "e": "Según el art. 20.2 CE, ¿puede restringirse la libertad de expresión mediante censura previa?", "o": [{"letra": "a", "texto": "No, mediante ningún tipo"}, {"letra": "b", "texto": "Sí, por resolución judicial"}], "k": "a", "x": "Art. 20.2 CE: no mediante ningún tipo de censura previa.", "f": "Art. 20.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a20-2-censura:N1"}, {"c": "CE-a20-2-censura", "n": 2, "e": "Según el art. 20.2 CE, el ejercicio de los derechos del art. 20 no puede restringirse mediante:", "o": [{"letra": "a", "texto": "Las leyes que desarrollen el Título I."}, {"letra": "b", "texto": "Ningún tipo de censura previa."}, {"letra": "c", "texto": "Resolución judicial motivada."}], "k": "b", "x": "Art. 20.2 CE. La resolución judicial sí permite el secuestro de publicaciones (art. 20.5).", "f": "Art. 20.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a20-2-censura:N2"}, {"c": "CE-a20-2-censura", "n": 3, "e": "¿Qué diferencia hay entre los apartados 2 y 5 del art. 20 CE?", "o": [{"letra": "a", "texto": "El 20.2 prohíbe toda censura previa; el 20.5 permite el secuestro solo por resolución judicial."}, {"letra": "b", "texto": "El 20.2 permite la censura previa por resolución judicial; el 20.5 prohíbe el secuestro."}, {"letra": "c", "texto": "Ambos prohíben cualquier intervención sobre los medios de información, incluso la judicial."}], "k": "a", "x": "Art. 20.2: ningún tipo de censura previa. Art. 20.5: secuestro solo en virtud de resolución judicial.", "f": "Art. 20.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a20-2-censura:N3"}, {"c": "CE-a20-3-medios-publicos", "n": 1, "e": "Según el art. 20.3 CE, los medios de comunicación social dependientes del Estado están sometidos a control…", "o": [{"letra": "a", "texto": "del Gobierno"}, {"letra": "b", "texto": "parlamentario"}], "k": "b", "x": "Art. 20.3 CE: organización y control parlamentario.", "f": "Art. 20.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a20-3-medios-publicos:N1"}, {"c": "CE-a20-3-medios-publicos", "n": 2, "e": "Según el art. 20.3 CE, la ley garantizará el acceso a los medios de comunicación públicos de:", "o": [{"letra": "a", "texto": "Todos los partidos inscritos en el registro."}, {"letra": "b", "texto": "Las asociaciones declaradas de utilidad pública."}, {"letra": "c", "texto": "Los grupos sociales y políticos significativos."}], "k": "c", "x": "Art. 20.3 CE: de los grupos sociales y políticos significativos, respetando el pluralismo de la sociedad y de las diversas lenguas de España.", "f": "Art. 20.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a20-3-medios-publicos:N2"}, {"c": "CE-a20-3-medios-publicos", "n": 3, "e": "El art. 20.3 CE se aplica a los medios de comunicación social dependientes:", "o": [{"letra": "a", "texto": "Exclusivamente del Estado."}, {"letra": "b", "texto": "De las Comunidades Autónomas, en exclusiva."}, {"letra": "c", "texto": "Del Estado o de cualquier ente público."}], "k": "c", "x": "Art. 20.3 CE: «dependientes del Estado o de cualquier ente público».", "f": "Art. 20.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a20-3-medios-publicos:N3"}, {"c": "CE-a20-4-limites", "n": 1, "e": "Según el art. 20.4 CE, ¿es la protección de la juventud y de la infancia un límite de la libertad de expresión?", "o": [{"letra": "a", "texto": "Sí"}, {"letra": "b", "texto": "No"}], "k": "a", "x": "Art. 20.4 CE: la cita especialmente.", "f": "Art. 20.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a20-4-limites:N1"}, {"c": "CE-a20-4-limites", "n": 2, "e": "Según el art. 20.4 CE, las libertades del art. 20 tienen su límite especialmente en el derecho:", "o": [{"letra": "a", "texto": "Al honor, a la intimidad, a la propia imagen y a la protección de la juventud y de la infancia."}, {"letra": "b", "texto": "A la tutela judicial efectiva y a la presunción de inocencia."}, {"letra": "c", "texto": "A la vida, a la integridad física y moral, a la seguridad y a la tutela judicial efectiva."}], "k": "a", "x": "Art. 20.4 CE.", "f": "Art. 20.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a20-4-limites:N2"}, {"c": "CE-a20-4-limites", "n": 3, "e": "¿Cuál de estos NO aparece expresamente en el art. 20.4 CE como límite de las libertades del art. 20?", "o": [{"letra": "a", "texto": "La propia imagen."}, {"letra": "b", "texto": "La seguridad nacional."}, {"letra": "c", "texto": "Los preceptos de las leyes que desarrollen el Título I."}], "k": "b", "x": "Art. 20.4 CE: respeto a los derechos del Título, a las leyes que lo desarrollen y, especialmente, honor, intimidad, propia imagen y protección de la juventud y de la infancia. No cita la seguridad nacional.", "f": "Art. 20.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a20-4-limites:N3"}, {"c": "CE-a20-5-secuestro", "n": 1, "e": "Según el art. 20.5 CE, el secuestro de publicaciones solo puede acordarse por…", "o": [{"letra": "a", "texto": "orden del Ministerio del Interior"}, {"letra": "b", "texto": "resolución judicial"}], "k": "b", "x": "Art. 20.5 CE.", "f": "Art. 20.5 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a20-5-secuestro:N1"}, {"c": "CE-a20-5-secuestro", "n": 2, "e": "Según el art. 20.5 CE, sólo podrá acordarse el secuestro de publicaciones, grabaciones y otros medios de información:", "o": [{"letra": "a", "texto": "En virtud de resolución judicial o, en caso de urgencia, gubernativa."}, {"letra": "b", "texto": "Durante la vigencia del estado de excepción."}, {"letra": "c", "texto": "En virtud de resolución judicial."}], "k": "c", "x": "Art. 20.5 CE: solo por resolución judicial.", "f": "Art. 20.5 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a20-5-secuestro:N2"}, {"c": "CE-a20-5-secuestro", "n": 3, "e": "¿Qué objetos menciona el art. 20.5 CE al regular el secuestro?", "o": [{"letra": "a", "texto": "Libros, periódicos y archivos informáticos."}, {"letra": "b", "texto": "Publicaciones periódicas y emisiones de radio y televisión."}, {"letra": "c", "texto": "Publicaciones, grabaciones y otros medios de información."}], "k": "c", "x": "Art. 20.5 CE: «publicaciones, grabaciones y otros medios de información».", "f": "Art. 20.5 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a20-5-secuestro:N3"}, {"c": "CE-a21-1-reunion", "n": 1, "e": "Según el art. 21.1 CE, ¿necesita autorización previa el ejercicio del derecho de reunión?", "o": [{"letra": "a", "texto": "Sí"}, {"letra": "b", "texto": "No"}], "k": "b", "x": "Art. 21.1 CE: no necesitará autorización previa.", "f": "Art. 21.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a21-1-reunion:N1"}, {"c": "CE-a21-1-reunion", "n": 2, "e": "Según el art. 21.1 CE, se reconoce el derecho de reunión:", "o": [{"letra": "a", "texto": "Pacífica, previa comunicación a la autoridad."}, {"letra": "b", "texto": "Pacífica y sin armas."}, {"letra": "c", "texto": "Pacífica y en lugares cerrados."}], "k": "b", "x": "Art. 21.1 CE. La comunicación previa solo se exige para reuniones en lugares de tránsito público y manifestaciones (art. 21.2).", "f": "Art. 21.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a21-1-reunion:N2"}, {"c": "CE-a21-1-reunion", "n": 3, "e": "Para el derecho de reunión, el art. 21 CE distingue entre:", "o": [{"letra": "a", "texto": "Comunicación previa para todas las reuniones y autorización solo para las de más de veinte personas."}, {"letra": "b", "texto": "La autorización previa nunca se exige; la comunicación previa, en tránsito público y manifestaciones."}, {"letra": "c", "texto": "Autorización previa para las manifestaciones y comunicación previa para las reuniones en locales cerrados."}], "k": "b", "x": "Art. 21.1: sin autorización previa. Art. 21.2: comunicación previa en lugares de tránsito público y manifestaciones.", "f": "Art. 21.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a21-1-reunion:N3"}, {"c": "CE-a21-2-manifestaciones", "n": 1, "e": "Según el art. 21.2 CE, para las manifestaciones se dará a la autoridad…", "o": [{"letra": "a", "texto": "solicitud de autorización"}, {"letra": "b", "texto": "comunicación previa"}], "k": "b", "x": "Art. 21.2 CE: comunicación previa.", "f": "Art. 21.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a21-2-manifestaciones:N1"}, {"c": "CE-a21-2-manifestaciones", "n": 2, "e": "Según el art. 21.2 CE, la autoridad sólo podrá prohibir las reuniones en lugares de tránsito público y las manifestaciones cuando existan razones fundadas de:", "o": [{"letra": "a", "texto": "Coincidencia con otra manifestación ya comunicada."}, {"letra": "b", "texto": "Perjuicio para el tráfico o para los comercios de la zona."}, {"letra": "c", "texto": "Alteración del orden público, con peligro para personas o bienes."}], "k": "c", "x": "Art. 21.2 CE.", "f": "Art. 21.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a21-2-manifestaciones:N2"}, {"c": "CE-a21-2-manifestaciones", "n": 3, "e": "Según el art. 21.2 CE, para prohibir una manifestación comunicada no basta con:", "o": [{"letra": "a", "texto": "Que existan razones fundadas de alteración del orden público con peligro para personas."}, {"letra": "b", "texto": "Que exista riesgo de alteración del orden público sin peligro para personas o bienes."}, {"letra": "c", "texto": "Que existan razones fundadas de alteración del orden público con peligro para bienes."}], "k": "b", "x": "Art. 21.2 CE: exige razones fundadas de alteración del orden público «con peligro para personas o bienes».", "f": "Art. 21.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a21-2-manifestaciones:N3"}, {"c": "CE-a22-1-asociacion", "n": 1, "e": "¿Qué artículo de la Constitución reconoce el derecho de asociación?", "o": [{"letra": "a", "texto": "El art. 22"}, {"letra": "b", "texto": "El art. 21"}], "k": "a", "x": "Art. 22.1 CE. El art. 21 reconoce el derecho de reunión.", "f": "Art. 22.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a22-1-asociacion:N1"}, {"c": "CE-a22-1-asociacion", "n": 2, "e": "Según el art. 22 CE, ¿cuál de estas afirmaciones es correcta?", "o": [{"letra": "a", "texto": "Se reconoce el derecho de asociación, salvo para fines políticos."}, {"letra": "b", "texto": "Se reconoce el derecho de asociación."}, {"letra": "c", "texto": "Se reconoce el derecho de asociación, previa autorización administrativa."}], "k": "b", "x": "Art. 22.1 CE: «Se reconoce el derecho de asociación».", "f": "Art. 22.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a22-1-asociacion:N2"}, {"c": "CE-a22-1-asociacion", "n": 3, "e": "Los derechos de reunión, asociación y fundación se reconocen, respectivamente, en los artículos:", "o": [{"letra": "a", "texto": "20, 21 y 22."}, {"letra": "b", "texto": "21, 22 y 34."}, {"letra": "c", "texto": "21, 22 y 23."}], "k": "b", "x": "Reunión: art. 21. Asociación: art. 22. Fundación: art. 34.", "f": "Art. 22.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a22-1-asociacion:N3"}, {"c": "CE-a22-2-ilegales", "n": 1, "e": "Según el art. 22.2 CE, son ilegales las asociaciones que persigan fines o utilicen medios tipificados como…", "o": [{"letra": "a", "texto": "delito"}, {"letra": "b", "texto": "infracción administrativa"}], "k": "a", "x": "Art. 22.2 CE: tipificados como delito.", "f": "Art. 22.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a22-2-ilegales:N1"}, {"c": "CE-a22-2-ilegales", "n": 2, "e": "Según el art. 22.2 CE, son ilegales las asociaciones que:", "o": [{"letra": "a", "texto": "Persigan fines políticos sin ser partidos."}, {"letra": "b", "texto": "No se inscriban en el registro correspondiente."}, {"letra": "c", "texto": "Persigan fines o utilicen medios tipificados como delito."}], "k": "c", "x": "Art. 22.2 CE. La inscripción registral es solo a efectos de publicidad (art. 22.3).", "f": "Art. 22.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a22-2-ilegales:N2"}, {"c": "CE-a22-2-ilegales", "n": 3, "e": "Una asociación que no persigue fines delictivos, pero utiliza medios tipificados como delito, según el art. 22.2 CE:", "o": [{"letra": "a", "texto": "Es ilegal, porque basta con que los medios estén tipificados como delito."}, {"letra": "b", "texto": "Es legal, porque la Constitución solo atiende a los fines que persigue la asociación."}, {"letra": "c", "texto": "Es legal mientras esté inscrita en el registro."}], "k": "a", "x": "Art. 22.2 CE: «persigan fines o utilicen medios tipificados como delito»; basta con uno de los dos.", "f": "Art. 22.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a22-2-ilegales:N3"}, {"c": "CE-a22-3-registro", "n": 1, "e": "Según el art. 22.3 CE, las asociaciones se inscriben en un registro a los solos efectos de…", "o": [{"letra": "a", "texto": "autorización"}, {"letra": "b", "texto": "publicidad"}], "k": "b", "x": "Art. 22.3 CE: a los solos efectos de publicidad.", "f": "Art. 22.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a22-3-registro:N1"}, {"c": "CE-a22-3-registro", "n": 2, "e": "Según el art. 22.3 CE, la inscripción de las asociaciones en un registro:", "o": [{"letra": "a", "texto": "Es voluntaria y constitutiva de la asociación."}, {"letra": "b", "texto": "Es obligatoria y necesaria para su legalidad."}, {"letra": "c", "texto": "Es obligatoria y a los solos efectos de publicidad."}], "k": "c", "x": "Art. 22.3 CE: «deberán inscribirse… a los solos efectos de publicidad».", "f": "Art. 22.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a22-3-registro:N2"}, {"c": "CE-a22-3-registro", "n": 3, "e": "Una asociación lícita que no se ha inscrito en el registro, según el art. 22 CE:", "o": [{"letra": "a", "texto": "No existe jurídicamente hasta su inscripción."}, {"letra": "b", "texto": "Es ilegal y la Administración puede disolverla hasta que regularice su inscripción."}, {"letra": "c", "texto": "No es ilegal por ello, porque la inscripción es a los solos efectos de publicidad."}], "k": "c", "x": "La ilegalidad depende de fines o medios delictivos (22.2); la inscripción tiene efectos de publicidad (22.3) y la disolución exige resolución judicial motivada (22.4).", "f": "Art. 22.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a22-3-registro:N3"}, {"c": "CE-a22-4-disolucion", "n": 1, "e": "Según el art. 22.4 CE, ¿puede la Administración disolver una asociación?", "o": [{"letra": "a", "texto": "No, solo una resolución judicial motivada"}, {"letra": "b", "texto": "Sí, por resolución motivada"}], "k": "a", "x": "Art. 22.4 CE: solo en virtud de resolución judicial motivada.", "f": "Art. 22.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a22-4-disolucion:N1"}, {"c": "CE-a22-4-disolucion", "n": 2, "e": "Según el art. 22.4 CE, las asociaciones sólo podrán ser disueltas o suspendidas en sus actividades en virtud de:", "o": [{"letra": "a", "texto": "Resolución judicial motivada."}, {"letra": "b", "texto": "Resolución del Ministerio del Interior."}, {"letra": "c", "texto": "Sentencia firme del Tribunal Constitucional."}], "k": "a", "x": "Art. 22.4 CE.", "f": "Art. 22.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a22-4-disolucion:N2"}, {"c": "CE-a22-4-disolucion", "n": 3, "e": "Según el art. 22.4 CE, la resolución judicial que disuelva o suspenda una asociación debe ser:", "o": [{"letra": "a", "texto": "Motivada."}, {"letra": "b", "texto": "Previa al registro de la asociación."}, {"letra": "c", "texto": "Firme y dictada por el Tribunal Supremo."}], "k": "a", "x": "Art. 22.4 CE: «resolución judicial motivada».", "f": "Art. 22.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a22-4-disolucion:N3"}, {"c": "CE-a22-5-prohibidas", "n": 1, "e": "Según el art. 22.5 CE, se prohíben las asociaciones secretas y las de carácter…", "o": [{"letra": "a", "texto": "religioso"}, {"letra": "b", "texto": "paramilitar"}], "k": "b", "x": "Art. 22.5 CE.", "f": "Art. 22.5 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a22-5-prohibidas:N1"}, {"c": "CE-a22-5-prohibidas", "n": 2, "e": "Según el art. 22.5 CE, se prohíben las asociaciones:", "o": [{"letra": "a", "texto": "Secretas y las de carácter paramilitar."}, {"letra": "b", "texto": "Secretas y las que no tengan estructura democrática."}, {"letra": "c", "texto": "No inscritas y las de carácter político."}], "k": "a", "x": "Art. 22.5 CE.", "f": "Art. 22.5 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a22-5-prohibidas:N2"}, {"c": "CE-a22-5-prohibidas", "n": 3, "e": "¿Qué apartado del art. 22 CE prohíbe las asociaciones secretas y paramilitares?", "o": [{"letra": "a", "texto": "El 2."}, {"letra": "b", "texto": "El 5."}, {"letra": "c", "texto": "El 4."}], "k": "b", "x": "Art. 22.5 CE. El 22.2 declara ilegales las de fines o medios delictivos y el 22.4 regula la disolución.", "f": "Art. 22.5 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a22-5-prohibidas:N3"}, {"c": "CE-a23-1-participacion", "n": 1, "e": "Según el art. 23.1 CE, los ciudadanos pueden participar en los asuntos públicos directamente o…", "o": [{"letra": "a", "texto": "solo a través de los partidos políticos"}, {"letra": "b", "texto": "por medio de representantes"}], "k": "b", "x": "Art. 23.1 CE.", "f": "Art. 23.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a23-1-participacion:N1"}, {"c": "CE-a23-1-participacion", "n": 2, "e": "Según el art. 23.1 CE, los representantes son libremente elegidos en elecciones periódicas por sufragio:", "o": [{"letra": "a", "texto": "Directo de los mayores de veintiún años."}, {"letra": "b", "texto": "Universal."}, {"letra": "c", "texto": "Universal, libre y secreto, cada cuatro años."}], "k": "b", "x": "Art. 23.1 CE: «en elecciones periódicas por sufragio universal». No fija la periodicidad.", "f": "Art. 23.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a23-1-participacion:N2"}, {"c": "CE-a23-1-participacion", "n": 3, "e": "Según el art. 23.1 CE, ¿quiénes tienen el derecho a participar en los asuntos públicos?", "o": [{"letra": "a", "texto": "Todas las personas residentes en España."}, {"letra": "b", "texto": "Los partidos políticos, como instrumento fundamental."}, {"letra": "c", "texto": "Los ciudadanos."}], "k": "c", "x": "Art. 23.1 CE: «Los ciudadanos tienen el derecho a participar en los asuntos públicos». Los partidos son instrumento fundamental para la participación (art. 6), pero el derecho es de los ciudadanos; y el art. 13.2 reserva este derecho a los españoles, salvo el sufragio municipal.", "f": "Art. 23.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a23-1-participacion:N3"}, {"c": "CE-a23-2-acceso-cargos", "n": 1, "e": "Según el art. 23.2 CE, se accede a las funciones y cargos públicos en condiciones de…", "o": [{"letra": "a", "texto": "libre designación"}, {"letra": "b", "texto": "igualdad"}], "k": "b", "x": "Art. 23.2 CE.", "f": "Art. 23.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a23-2-acceso-cargos:N1"}, {"c": "CE-a23-2-acceso-cargos", "n": 2, "e": "El derecho de un opositor a bombero a acceder en condiciones de igualdad a una plaza pública se reconoce en el art.:", "o": [{"letra": "a", "texto": "23.2 CE."}, {"letra": "b", "texto": "35.1 CE."}, {"letra": "c", "texto": "14 CE, exclusivamente."}], "k": "a", "x": "Art. 23.2 CE: acceso en condiciones de igualdad a las funciones y cargos públicos.", "f": "Art. 23.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a23-2-acceso-cargos:N2"}, {"c": "CE-a23-2-acceso-cargos", "n": 3, "e": "Según el art. 23.2 CE, el acceso a las funciones y cargos públicos se produce:", "o": [{"letra": "a", "texto": "En condiciones de igualdad, con los requisitos que fije cada Administración por reglamento."}, {"letra": "b", "texto": "En condiciones de igualdad, con los requisitos que señalen las leyes."}, {"letra": "c", "texto": "Por mérito y capacidad, con los requisitos que fije la Constitución."}], "k": "b", "x": "Art. 23.2 CE: «con los requisitos que señalen las leyes». Mérito y capacidad aparecen en el art. 103.3, no en el 23.2.", "f": "Art. 23.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a23-2-acceso-cargos:N3"}]'::jsonb) AS x(c text, n int, e text, o jsonb, k text, x text, f text, h text);
UPDATE public.questions q SET enunciado = qq.e, opciones = qq.o, correcta = qq.k, explicacion = qq.x, fuente_normativa = qq.f, nivel = qq.n, concept_id = qq.c, estado = 'publicada', topic_id = (SELECT id FROM _tema) FROM _qq qq WHERE q.hash_dedupe = qq.h;
INSERT INTO public.questions (topic_id, enunciado, opciones, correcta, explicacion, fuente_normativa, estado, nivel, origen_tipo, origen_archivo, concept_id, hash_dedupe) SELECT (SELECT id FROM _tema), qq.e, qq.o, qq.k, qq.x, qq.f, 'publicada', qq.n, 'propio', 'data/constitucion/titulo-i.json', qq.c, qq.h FROM _qq qq WHERE NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.hash_dedupe = qq.h);
COMMIT;
-- BLOQUE
BEGIN;
CREATE TEMP TABLE _tema ON COMMIT DROP AS SELECT id FROM public.topics WHERE convocatoria_id = 1 AND numero = 1;
DO $$ BEGIN IF (SELECT count(*) FROM _tema) <> 1 THEN RAISE EXCEPTION 'tema 1 de la convocatoria 1 no encontrado o duplicado'; END IF; END $$;
WITH cc AS (SELECT * FROM jsonb_to_recordset('[{"id": "CE-a24-1-tutela", "apartado": "Título I · Art. 24.1", "orden": 700, "pregunta": "¿Qué derecho reconoce el art. 24.1 CE y qué no puede producirse en ningún caso?", "respuesta": "El derecho a obtener la tutela efectiva de jueces y tribunales en el ejercicio de derechos e intereses legítimos; en ningún caso puede producirse indefensión.", "fuente": "Constitución Española, art. 24.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Todas las personas tienen derecho a obtener la tutela efectiva de los jueces y tribunales en el ejercicio de sus derechos e intereses legítimos, sin que, en ningún caso, pueda producirse indefensión.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a24-2-garantias"]}, {"id": "CE-a24-2-garantias", "apartado": "Título I · Art. 24.2", "orden": 710, "pregunta": "Enumera las garantías procesales del art. 24.2 CE.", "respuesta": "Juez ordinario predeterminado por la ley, defensa y asistencia de letrado, ser informados de la acusación, proceso público sin dilaciones indebidas y con todas las garantías, medios de prueba pertinentes, no declarar contra sí mismos, no confesarse culpables y presunción de inocencia.", "fuente": "Constitución Española, art. 24.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "a no declarar contra sí mismos, a no confesarse culpables y a la presunción de inocencia", "tipo": "lista", "prioridad": 1, "conf": ["CE-a24-1-tutela", "CE-a17-3-detenido"]}, {"id": "CE-a24-2-parentesco", "apartado": "Título I · Art. 24.2", "orden": 720, "pregunta": "¿Por qué razones regulará la ley que no se esté obligado a declarar sobre hechos presuntamente delictivos (art. 24.2 CE)?", "respuesta": "Por razón de parentesco o de secreto profesional.", "fuente": "Constitución Española, art. 24.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "La ley regulará los casos en que, por razón de parentesco o de secreto profesional, no se estará obligado a declarar sobre hechos presuntamente delictivos.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a20-1-informacion", "CE-a16-2-no-declarar"]}, {"id": "CE-a25-1-legalidad-penal", "apartado": "Título I · Art. 25.1", "orden": 730, "pregunta": "¿Qué principio recoge el art. 25.1 CE?", "respuesta": "Nadie puede ser condenado o sancionado por acciones u omisiones que, en el momento de producirse, no constituyan delito, falta o infracción administrativa según la legislación vigente entonces.", "fuente": "Constitución Española, art. 25.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Nadie puede ser condenado o sancionado por acciones u omisiones que en el momento de producirse no constituyan delito, falta o infracción administrativa, según la legislación vigente en aquel momento.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a9-3-irretroactividad"]}, {"id": "CE-a25-2-reinsercion", "apartado": "Título I · Art. 25.2", "orden": 740, "pregunta": "¿Hacia qué se orientan las penas privativas de libertad y qué no pueden consistir (art. 25.2 CE)?", "respuesta": "Hacia la reeducación y reinserción social; no pueden consistir en trabajos forzados.", "fuente": "Constitución Española, art. 25.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Las penas privativas de libertad y las medidas de seguridad estarán orientadas hacia la reeducación y reinserción social y no podrán consistir en trabajos forzados.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a25-2-preso"]}, {"id": "CE-a25-2-preso", "apartado": "Título I · Art. 25.2", "orden": 750, "pregunta": "¿Qué derechos tiene en todo caso el condenado a prisión (art. 25.2 CE)?", "respuesta": "Los derechos fundamentales del Capítulo, salvo los limitados por el fallo, el sentido de la pena y la ley penitenciaria; y en todo caso trabajo remunerado, beneficios de la Seguridad Social, acceso a la cultura y desarrollo integral de su personalidad.", "fuente": "Constitución Española, art. 25.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "En todo caso, tendrá derecho a un trabajo remunerado y a los beneficios correspondientes de la Seguridad Social, así como al acceso a la cultura y al desarrollo integral de su personalidad.", "tipo": "lista", "prioridad": 2, "conf": ["CE-a25-2-reinsercion"]}, {"id": "CE-a25-3-administracion", "apartado": "Título I · Art. 25.3", "orden": 760, "pregunta": "¿Qué sanciones no puede imponer la Administración civil (art. 25.3 CE)?", "respuesta": "Las que, directa o subsidiariamente, impliquen privación de libertad.", "fuente": "Constitución Española, art. 25.3 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "La Administración civil no podrá imponer sanciones que, directa o subsidiariamente, impliquen privación de libertad.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a26-tribunales-honor"]}, {"id": "CE-a26-tribunales-honor", "apartado": "Título I · Art. 26", "orden": 770, "pregunta": "¿Dónde prohíbe el art. 26 CE los Tribunales de Honor?", "respuesta": "En el ámbito de la Administración civil y de las organizaciones profesionales.", "fuente": "Constitución Española, art. 26 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Se prohíben los Tribunales de Honor en el ámbito de la Administración civil y de las organizaciones profesionales.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a25-3-administracion"]}, {"id": "CE-a27-1-educacion", "apartado": "Título I · Art. 27.1", "orden": 780, "pregunta": "¿Qué derecho y qué libertad reconoce el art. 27.1 CE?", "respuesta": "El derecho de todos a la educación y la libertad de enseñanza.", "fuente": "Constitución Española, art. 27.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Todos tienen el derecho a la educación. Se reconoce la libertad de enseñanza.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a20-1-expresion"]}, {"id": "CE-a27-2-objeto", "apartado": "Título I · Art. 27.2", "orden": 790, "pregunta": "¿Cuál es el objeto de la educación según el art. 27.2 CE?", "respuesta": "El pleno desarrollo de la personalidad humana en el respeto a los principios democráticos de convivencia y a los derechos y libertades fundamentales.", "fuente": "Constitución Española, art. 27.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "La educación tendrá por objeto el pleno desarrollo de la personalidad humana en el respeto a los principios democráticos de convivencia y a los derechos y libertades fundamentales.", "tipo": "definicion", "prioridad": 2, "conf": ["CE-a10-1-fundamento"]}, {"id": "CE-a27-3-formacion-religiosa", "apartado": "Título I · Art. 27.3", "orden": 800, "pregunta": "¿Qué derecho de los padres garantizan los poderes públicos según el art. 27.3 CE?", "respuesta": "Que sus hijos reciban la formación religiosa y moral que esté de acuerdo con sus propias convicciones.", "fuente": "Constitución Española, art. 27.3 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Los poderes públicos garantizan el derecho que asiste a los padres para que sus hijos reciban la formación religiosa y moral que esté de acuerdo con sus propias convicciones.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a16-3-aconfesionalidad"]}, {"id": "CE-a27-4-basica", "apartado": "Título I · Art. 27.4", "orden": 810, "pregunta": "¿Cómo es la enseñanza básica según el art. 27.4 CE?", "respuesta": "Obligatoria y gratuita.", "fuente": "Constitución Española, art. 27.4 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "La enseñanza básica es obligatoria y gratuita.", "tipo": "dato", "prioridad": 1, "conf": ["CE-a27-5-programacion"]}, {"id": "CE-a27-5-programacion", "apartado": "Título I · Art. 27.5", "orden": 820, "pregunta": "¿Cómo garantizan los poderes públicos el derecho a la educación (art. 27.5 CE)?", "respuesta": "Mediante una programación general de la enseñanza, con participación efectiva de todos los sectores afectados, y la creación de centros docentes.", "fuente": "Constitución Española, art. 27.5 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "mediante una programación general de la enseñanza, con participación efectiva de todos los sectores afectados y la creación de centros docentes", "tipo": "regla", "prioridad": 3, "conf": ["CE-a27-7-control-gestion"]}, {"id": "CE-a27-6-creacion-centros", "apartado": "Título I · Art. 27.6", "orden": 830, "pregunta": "¿A quién reconoce el art. 27.6 CE la libertad de creación de centros docentes?", "respuesta": "A las personas físicas y jurídicas, dentro del respeto a los principios constitucionales.", "fuente": "Constitución Española, art. 27.6 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Se reconoce a las personas físicas y jurídicas la libertad de creación de centros docentes, dentro del respeto a los principios constitucionales.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a27-9-ayudas"]}, {"id": "CE-a27-7-control-gestion", "apartado": "Título I · Art. 27.7", "orden": 840, "pregunta": "¿Quiénes intervienen en el control y gestión de los centros sostenidos con fondos públicos (art. 27.7 CE)?", "respuesta": "Los profesores, los padres y, en su caso, los alumnos, en los términos que la ley establezca.", "fuente": "Constitución Española, art. 27.7 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Los profesores, los padres y, en su caso, los alumnos intervendrán en el control y gestión de todos los centros sostenidos por la Administración con fondos públicos", "tipo": "regla", "prioridad": 2, "conf": ["CE-a27-5-programacion"]}, {"id": "CE-a27-8-inspeccion", "apartado": "Título I · Art. 27.8", "orden": 850, "pregunta": "¿Qué harán los poderes públicos con el sistema educativo según el art. 27.8 CE?", "respuesta": "Lo inspeccionarán y homologarán para garantizar el cumplimiento de las leyes.", "fuente": "Constitución Española, art. 27.8 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Los poderes públicos inspeccionarán y homologarán el sistema educativo para garantizar el cumplimiento de las leyes.", "tipo": "regla", "prioridad": 3, "conf": ["CE-a27-5-programacion"]}, {"id": "CE-a27-9-ayudas", "apartado": "Título I · Art. 27.9", "orden": 860, "pregunta": "¿A qué centros ayudarán los poderes públicos (art. 27.9 CE)?", "respuesta": "A los centros docentes que reúnan los requisitos que la ley establezca.", "fuente": "Constitución Española, art. 27.9 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Los poderes públicos ayudarán a los centros docentes que reúnan los requisitos que la ley establezca.", "tipo": "regla", "prioridad": 3, "conf": ["CE-a27-6-creacion-centros"]}, {"id": "CE-a27-10-universidades", "apartado": "Título I · Art. 27.10", "orden": 870, "pregunta": "¿Qué reconoce el art. 27.10 CE a las Universidades?", "respuesta": "Su autonomía, en los términos que la ley establezca.", "fuente": "Constitución Española, art. 27.10 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Se reconoce la autonomía de las Universidades, en los términos que la ley establezca.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a27-1-educacion"]}, {"id": "CE-a28-1-sindicacion", "apartado": "Título I · Art. 28.1", "orden": 880, "pregunta": "¿Qué dice el art. 28.1 CE sobre el derecho a sindicarse y sus limitaciones?", "respuesta": "Todos tienen derecho a sindicarse libremente; la ley podrá limitarlo o exceptuarlo para las Fuerzas o Institutos armados y demás Cuerpos con disciplina militar, y regulará sus peculiaridades para los funcionarios públicos. Nadie podrá ser obligado a afiliarse.", "fuente": "Constitución Española, art. 28.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "La ley podrá limitar o exceptuar el ejercicio de este derecho a las Fuerzas o Institutos armados o a los demás Cuerpos sometidos a disciplina militar y regulará las peculiaridades de su ejercicio para los funcionarios públicos.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a7-sindicatos-regimen", "CE-a29-2-militares"]}, {"id": "CE-a28-2-huelga", "apartado": "Título I · Art. 28.2", "orden": 890, "pregunta": "¿Qué reconoce el art. 28.2 CE y qué garantías debe incluir la ley que lo regule?", "respuesta": "El derecho a la huelga de los trabajadores para la defensa de sus intereses; la ley establecerá garantías para asegurar el mantenimiento de los servicios esenciales de la comunidad.", "fuente": "Constitución Española, art. 28.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Se reconoce el derecho a la huelga de los trabajadores para la defensa de sus intereses.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a37-2-conflicto"]}]'::jsonb) AS x(id text, apartado text, orden int, pregunta text, respuesta text, fuente text, cita text, tipo text, prioridad smallint, conf text[])) INSERT INTO public.concepts (id, topic_id, documento, apartado, orden, pregunta, respuesta, fuente, cita, tipo, prioridad, confundible_con, estado) SELECT cc.id, t.id, 'CE', cc.apartado, cc.orden, cc.pregunta, cc.respuesta, cc.fuente, cc.cita, cc.tipo, cc.prioridad, coalesce(cc.conf, '{}'), 'publicado' FROM cc, _tema t ON CONFLICT (id) DO UPDATE SET topic_id = EXCLUDED.topic_id, documento = EXCLUDED.documento, apartado = EXCLUDED.apartado, orden = EXCLUDED.orden, pregunta = EXCLUDED.pregunta, respuesta = EXCLUDED.respuesta, fuente = EXCLUDED.fuente, cita = EXCLUDED.cita, tipo = EXCLUDED.tipo, prioridad = EXCLUDED.prioridad, confundible_con = EXCLUDED.confundible_con, estado = EXCLUDED.estado;
CREATE TEMP TABLE _qq ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"c": "CE-a24-1-tutela", "n": 1, "e": "Según el art. 24.1 CE, en el ejercicio de la tutela judicial efectiva no puede producirse en ningún caso…", "o": [{"letra": "a", "texto": "una sentencia desfavorable"}, {"letra": "b", "texto": "indefensión"}], "k": "b", "x": "Art. 24.1 CE: sin que, en ningún caso, pueda producirse indefensión.", "f": "Art. 24.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a24-1-tutela:N1"}, {"c": "CE-a24-1-tutela", "n": 2, "e": "Según el art. 24.1 CE, ¿quiénes tienen derecho a obtener la tutela efectiva de los jueces y tribunales?", "o": [{"letra": "a", "texto": "Todas las personas."}, {"letra": "b", "texto": "Los ciudadanos con residencia legal."}, {"letra": "c", "texto": "Los españoles."}], "k": "a", "x": "Art. 24.1 CE: «Todas las personas».", "f": "Art. 24.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a24-1-tutela:N2"}, {"c": "CE-a24-1-tutela", "n": 3, "e": "Según el art. 24.1 CE, la tutela judicial efectiva se refiere al ejercicio de:", "o": [{"letra": "a", "texto": "Derechos subjetivos reconocidos en una ley orgánica."}, {"letra": "b", "texto": "Derechos e intereses legítimos."}, {"letra": "c", "texto": "Derechos fundamentales, exclusivamente."}], "k": "b", "x": "Art. 24.1 CE: «en el ejercicio de sus derechos e intereses legítimos».", "f": "Art. 24.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a24-1-tutela:N3"}, {"c": "CE-a24-2-garantias", "n": 1, "e": "¿Recoge el art. 24.2 CE la presunción de inocencia?", "o": [{"letra": "a", "texto": "No, la recoge el art. 25"}, {"letra": "b", "texto": "Sí"}], "k": "b", "x": "Art. 24.2 CE: «…y a la presunción de inocencia».", "f": "Art. 24.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a24-2-garantias:N1"}, {"c": "CE-a24-2-garantias", "n": 2, "e": "Según el art. 24.2 CE, todos tienen derecho a un proceso público:", "o": [{"letra": "a", "texto": "Sin dilaciones indebidas y con todas las garantías."}, {"letra": "b", "texto": "Con jurado en los delitos graves."}, {"letra": "c", "texto": "Y gratuito en todas sus instancias, con abogado de oficio."}], "k": "a", "x": "Art. 24.2 CE: «a un proceso público sin dilaciones indebidas y con todas las garantías».", "f": "Art. 24.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a24-2-garantias:N2"}, {"c": "CE-a24-2-garantias", "n": 3, "e": "¿Cuál de estos derechos NO figura en el art. 24.2 CE?", "o": [{"letra": "a", "texto": "El derecho a la doble instancia penal."}, {"letra": "b", "texto": "El derecho a utilizar los medios de prueba pertinentes para la defensa."}, {"letra": "c", "texto": "El derecho al Juez ordinario predeterminado por la ley."}], "k": "a", "x": "El art. 24.2 recoge el Juez ordinario predeterminado por la ley y los medios de prueba pertinentes, pero no menciona la doble instancia.", "f": "Art. 24.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a24-2-garantias:N3"}, {"c": "CE-a24-2-parentesco", "n": 1, "e": "Según el art. 24.2 CE, ¿puede eximirse de declarar sobre hechos delictivos por razón de parentesco?", "o": [{"letra": "a", "texto": "Sí, en los casos que regule la ley"}, {"letra": "b", "texto": "No, nunca"}], "k": "a", "x": "Art. 24.2 CE, párrafo segundo.", "f": "Art. 24.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a24-2-parentesco:N1"}, {"c": "CE-a24-2-parentesco", "n": 2, "e": "Según el art. 24.2 CE, la ley regulará los casos en que no se estará obligado a declarar sobre hechos presuntamente delictivos por razón de:", "o": [{"letra": "a", "texto": "Ideología o creencias religiosas."}, {"letra": "b", "texto": "Amistad íntima o enemistad manifiesta."}, {"letra": "c", "texto": "Parentesco o de secreto profesional."}], "k": "c", "x": "Art. 24.2 CE: parentesco o secreto profesional. La ideología o creencias se protegen en el art. 16.2, que es otra cosa.", "f": "Art. 24.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a24-2-parentesco:N2"}, {"c": "CE-a24-2-parentesco", "n": 3, "e": "La dispensa de declarar sobre hechos presuntamente delictivos por parentesco o secreto profesional:", "o": [{"letra": "a", "texto": "La regula la ley por mandato del art. 24.2 CE."}, {"letra": "b", "texto": "Solo alcanza a los abogados, según el art. 24.2 CE."}, {"letra": "c", "texto": "La fija directamente el art. 24.2 CE para los parientes hasta el cuarto grado."}], "k": "a", "x": "Art. 24.2 CE: «La ley regulará los casos…». La Constitución no fija grados de parentesco.", "f": "Art. 24.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a24-2-parentesco:N3"}, {"c": "CE-a25-1-legalidad-penal", "n": 1, "e": "Según el art. 25.1 CE, ¿se puede sancionar una conducta que no era infracción cuando se cometió?", "o": [{"letra": "a", "texto": "No"}, {"letra": "b", "texto": "Sí, si una ley posterior la tipifica"}], "k": "a", "x": "Art. 25.1 CE: según la legislación vigente en aquel momento.", "f": "Art. 25.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a25-1-legalidad-penal:N1"}, {"c": "CE-a25-1-legalidad-penal", "n": 2, "e": "Según el art. 25.1 CE, nadie puede ser condenado o sancionado por acciones u omisiones que en el momento de producirse no constituyan:", "o": [{"letra": "a", "texto": "Delito, falta o infracción administrativa."}, {"letra": "b", "texto": "Delito o falta, exclusivamente."}, {"letra": "c", "texto": "Delito tipificado en una ley orgánica."}], "k": "a", "x": "Art. 25.1 CE: incluye también la infracción administrativa.", "f": "Art. 25.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a25-1-legalidad-penal:N2"}, {"c": "CE-a25-1-legalidad-penal", "n": 3, "e": "Una multa administrativa por una conducta que solo se tipificó como infracción después de realizarla:", "o": [{"letra": "a", "texto": "Es válida si la ley posterior que tipifica la infracción es una ley orgánica."}, {"letra": "b", "texto": "Vulnera el art. 25.1 CE, que alcanza también a las infracciones administrativas."}, {"letra": "c", "texto": "No vulnera el art. 25.1 CE, que solo se refiere a los delitos."}], "k": "b", "x": "Art. 25.1 CE: «delito, falta o infracción administrativa, según la legislación vigente en aquel momento».", "f": "Art. 25.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a25-1-legalidad-penal:N3"}, {"c": "CE-a25-2-reinsercion", "n": 1, "e": "Según el art. 25.2 CE, ¿pueden las penas privativas de libertad consistir en trabajos forzados?", "o": [{"letra": "a", "texto": "Sí, en casos graves"}, {"letra": "b", "texto": "No"}], "k": "b", "x": "Art. 25.2 CE: no podrán consistir en trabajos forzados.", "f": "Art. 25.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a25-2-reinsercion:N1"}, {"c": "CE-a25-2-reinsercion", "n": 2, "e": "Según el art. 25.2 CE, las penas privativas de libertad y las medidas de seguridad estarán orientadas hacia:", "o": [{"letra": "a", "texto": "La reeducación y reinserción social."}, {"letra": "b", "texto": "La protección de la víctima y la prevención general."}, {"letra": "c", "texto": "La retribución del daño causado."}], "k": "a", "x": "Art. 25.2 CE.", "f": "Art. 25.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a25-2-reinsercion:N2"}, {"c": "CE-a25-2-reinsercion", "n": 3, "e": "Según el art. 25.2 CE, la orientación hacia la reeducación y reinserción social se aplica a:", "o": [{"letra": "a", "texto": "Las penas privativas de libertad y las medidas de seguridad."}, {"letra": "b", "texto": "Solo a las penas de prisión, no a las medidas de seguridad."}, {"letra": "c", "texto": "Todas las penas y sanciones administrativas."}], "k": "a", "x": "Art. 25.2 CE: «Las penas privativas de libertad y las medidas de seguridad».", "f": "Art. 25.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a25-2-reinsercion:N3"}, {"c": "CE-a25-2-preso", "n": 1, "e": "Según el art. 25.2 CE, el condenado a prisión tiene derecho a un trabajo…", "o": [{"letra": "a", "texto": "obligatorio y no remunerado"}, {"letra": "b", "texto": "remunerado"}], "k": "b", "x": "Art. 25.2 CE: trabajo remunerado.", "f": "Art. 25.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a25-2-preso:N1"}, {"c": "CE-a25-2-preso", "n": 2, "e": "Según el art. 25.2 CE, el condenado a pena de prisión gozará de los derechos fundamentales del Capítulo, excepto los limitados expresamente por:", "o": [{"letra": "a", "texto": "El contenido del fallo condenatorio, el sentido de la pena y la ley penitenciaria."}, {"letra": "b", "texto": "El Código Penal y el reglamento del centro."}, {"letra": "c", "texto": "El director del centro penitenciario y el juez de vigilancia penitenciaria."}], "k": "a", "x": "Art. 25.2 CE.", "f": "Art. 25.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a25-2-preso:N2"}, {"c": "CE-a25-2-preso", "n": 3, "e": "¿Cuál de estos derechos NO reconoce en todo caso el art. 25.2 CE al condenado a prisión?", "o": [{"letra": "a", "texto": "Los beneficios correspondientes de la Seguridad Social."}, {"letra": "b", "texto": "El derecho a permisos de salida periódicos."}, {"letra": "c", "texto": "El acceso a la cultura."}], "k": "b", "x": "El art. 25.2 garantiza trabajo remunerado, Seguridad Social, acceso a la cultura y desarrollo integral de la personalidad. Los permisos no los menciona.", "f": "Art. 25.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a25-2-preso:N3"}, {"c": "CE-a25-3-administracion", "n": 1, "e": "Según el art. 25.3 CE, ¿puede la Administración civil imponer sanciones que impliquen privación de libertad?", "o": [{"letra": "a", "texto": "Sí, de forma subsidiaria"}, {"letra": "b", "texto": "No"}], "k": "b", "x": "Art. 25.3 CE: ni directa ni subsidiariamente.", "f": "Art. 25.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a25-3-administracion:N1"}, {"c": "CE-a25-3-administracion", "n": 2, "e": "Según el art. 25.3 CE, la Administración civil no podrá imponer sanciones que impliquen privación de libertad:", "o": [{"letra": "a", "texto": "Superiores a treinta días."}, {"letra": "b", "texto": "Sin audiencia previa del interesado."}, {"letra": "c", "texto": "Directa o subsidiariamente."}], "k": "c", "x": "Art. 25.3 CE: «directa o subsidiariamente».", "f": "Art. 25.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a25-3-administracion:N2"}, {"c": "CE-a25-3-administracion", "n": 3, "e": "La prohibición de sanciones privativas de libertad del art. 25.3 CE se refiere expresamente a:", "o": [{"letra": "a", "texto": "Todas las Administraciones, incluida la militar."}, {"letra": "b", "texto": "Los jueces de instrucción."}, {"letra": "c", "texto": "La Administración civil."}], "k": "c", "x": "Art. 25.3 CE: «La Administración civil». La Constitución no extiende expresamente esta prohibición a la Administración militar.", "f": "Art. 25.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a25-3-administracion:N3"}, {"c": "CE-a26-tribunales-honor", "n": 1, "e": "Según el art. 26 CE, se prohíben los Tribunales de…", "o": [{"letra": "a", "texto": "Honor"}, {"letra": "b", "texto": "Excepción"}], "k": "a", "x": "Art. 26 CE: Tribunales de Honor.", "f": "Art. 26 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a26-tribunales-honor:N1"}, {"c": "CE-a26-tribunales-honor", "n": 2, "e": "Según el art. 26 CE, se prohíben los Tribunales de Honor en el ámbito de:", "o": [{"letra": "a", "texto": "La Administración civil y de la Administración militar."}, {"letra": "b", "texto": "La Administración civil y de las organizaciones profesionales."}, {"letra": "c", "texto": "Las Fuerzas Armadas y los Colegios Profesionales."}], "k": "b", "x": "Art. 26 CE.", "f": "Art. 26 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a26-tribunales-honor:N2"}, {"c": "CE-a26-tribunales-honor", "n": 3, "e": "¿Qué artículo de la Constitución prohíbe los Tribunales de Honor?", "o": [{"letra": "a", "texto": "El 25."}, {"letra": "b", "texto": "El 26."}, {"letra": "c", "texto": "El 24."}], "k": "b", "x": "Art. 26 CE.", "f": "Art. 26 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a26-tribunales-honor:N3"}, {"c": "CE-a27-1-educacion", "n": 1, "e": "Según el art. 27.1 CE, ¿quiénes tienen derecho a la educación?", "o": [{"letra": "a", "texto": "Todos"}, {"letra": "b", "texto": "Los españoles menores de edad"}], "k": "a", "x": "Art. 27.1 CE: «Todos tienen el derecho a la educación».", "f": "Art. 27.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-1-educacion:N1"}, {"c": "CE-a27-1-educacion", "n": 2, "e": "Según el art. 27.1 CE, se reconoce la libertad:", "o": [{"letra": "a", "texto": "De enseñanza."}, {"letra": "b", "texto": "De elección de centro docente público."}, {"letra": "c", "texto": "De cátedra."}], "k": "a", "x": "Art. 27.1 CE: libertad de enseñanza. La libertad de cátedra está en el art. 20.1.c).", "f": "Art. 27.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-1-educacion:N2"}, {"c": "CE-a27-1-educacion", "n": 3, "e": "«Libertad de enseñanza» y «libertad de cátedra» aparecen, respectivamente, en los artículos:", "o": [{"letra": "a", "texto": "27.1 y 20.1.c)."}, {"letra": "b", "texto": "27.1 y 27.10."}, {"letra": "c", "texto": "20.1.c) y 27.1."}], "k": "a", "x": "Libertad de enseñanza: art. 27.1. Libertad de cátedra: art. 20.1.c).", "f": "Art. 27.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-1-educacion:N3"}, {"c": "CE-a27-2-objeto", "n": 1, "e": "Según el art. 27.2 CE, la educación tendrá por objeto el pleno desarrollo de…", "o": [{"letra": "a", "texto": "la personalidad humana"}, {"letra": "b", "texto": "la economía nacional"}], "k": "a", "x": "Art. 27.2 CE.", "f": "Art. 27.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-2-objeto:N1"}, {"c": "CE-a27-2-objeto", "n": 2, "e": "Según el art. 27.2 CE, la educación tendrá por objeto el pleno desarrollo de la personalidad humana en el respeto a:", "o": [{"letra": "a", "texto": "La unidad de la Nación y a la Corona."}, {"letra": "b", "texto": "Los principios democráticos de convivencia y a los derechos y libertades fundamentales."}, {"letra": "c", "texto": "Las creencias religiosas y morales mayoritarias de la sociedad española."}], "k": "b", "x": "Art. 27.2 CE.", "f": "Art. 27.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-2-objeto:N2"}, {"c": "CE-a27-2-objeto", "n": 3, "e": "El «pleno desarrollo de la personalidad humana» aparece en el art. 27.2 CE como:", "o": [{"letra": "a", "texto": "Un valor superior del ordenamiento jurídico."}, {"letra": "b", "texto": "El objeto de la educación."}, {"letra": "c", "texto": "Un fundamento del orden político y de la paz social."}], "k": "b", "x": "Art. 27.2 CE: objeto de la educación. El art. 10.1 habla del «libre desarrollo de la personalidad» como fundamento del orden político.", "f": "Art. 27.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-2-objeto:N3"}, {"c": "CE-a27-3-formacion-religiosa", "n": 1, "e": "Según el art. 27.3 CE, los padres tienen derecho a que sus hijos reciban la formación religiosa y moral acorde con…", "o": [{"letra": "a", "texto": "las creencias mayoritarias de la sociedad"}, {"letra": "b", "texto": "sus propias convicciones"}], "k": "b", "x": "Art. 27.3 CE.", "f": "Art. 27.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-3-formacion-religiosa:N1"}, {"c": "CE-a27-3-formacion-religiosa", "n": 2, "e": "Según el art. 27.3 CE, ¿qué formación garantizan los poderes públicos de acuerdo con las convicciones de los padres?", "o": [{"letra": "a", "texto": "La formación cívica y profesional."}, {"letra": "b", "texto": "La formación religiosa, exclusivamente."}, {"letra": "c", "texto": "La formación religiosa y moral."}], "k": "c", "x": "Art. 27.3 CE: formación religiosa y moral.", "f": "Art. 27.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-3-formacion-religiosa:N2"}, {"c": "CE-a27-3-formacion-religiosa", "n": 3, "e": "Según el art. 27.3 CE, el derecho a la formación religiosa y moral corresponde:", "o": [{"letra": "a", "texto": "A las confesiones religiosas con acuerdo con el Estado."}, {"letra": "b", "texto": "A los padres, para sus hijos."}, {"letra": "c", "texto": "A los alumnos mayores de edad."}], "k": "b", "x": "Art. 27.3 CE: «el derecho que asiste a los padres para que sus hijos reciban…».", "f": "Art. 27.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-3-formacion-religiosa:N3"}, {"c": "CE-a27-4-basica", "n": 1, "e": "Según el art. 27.4 CE, la enseñanza básica es…", "o": [{"letra": "a", "texto": "voluntaria y gratuita"}, {"letra": "b", "texto": "obligatoria y gratuita"}], "k": "b", "x": "Art. 27.4 CE.", "f": "Art. 27.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-4-basica:N1"}, {"c": "CE-a27-4-basica", "n": 2, "e": "Según el art. 27.4 CE, ¿qué enseñanza es obligatoria y gratuita?", "o": [{"letra": "a", "texto": "La básica."}, {"letra": "b", "texto": "La básica y la universitaria."}, {"letra": "c", "texto": "Toda la enseñanza pública."}], "k": "a", "x": "Art. 27.4 CE: la enseñanza básica.", "f": "Art. 27.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-4-basica:N2"}, {"c": "CE-a27-4-basica", "n": 3, "e": "¿Qué fija directamente el art. 27.4 CE sobre la enseñanza básica?", "o": [{"letra": "a", "texto": "Que es obligatoria y gratuita hasta los dieciséis años."}, {"letra": "b", "texto": "Que es gratuita en los centros públicos y obligatoria hasta los dieciocho años."}, {"letra": "c", "texto": "Que es obligatoria y gratuita, sin fijar las edades."}], "k": "c", "x": "El art. 27.4 solo dice «obligatoria y gratuita»; las edades las fija la ley.", "f": "Art. 27.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-4-basica:N3"}, {"c": "CE-a27-5-programacion", "n": 1, "e": "Según el art. 27.5 CE, los poderes públicos garantizan el derecho a la educación mediante una programación general de la enseñanza y…", "o": [{"letra": "a", "texto": "la privatización de los centros"}, {"letra": "b", "texto": "la creación de centros docentes"}], "k": "b", "x": "Art. 27.5 CE.", "f": "Art. 27.5 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-5-programacion:N1"}, {"c": "CE-a27-5-programacion", "n": 2, "e": "Según el art. 27.5 CE, la programación general de la enseñanza se hará:", "o": [{"letra": "a", "texto": "Por las Universidades, en el marco de su autonomía."}, {"letra": "b", "texto": "Por el Gobierno, oídas las Comunidades Autónomas."}, {"letra": "c", "texto": "Con participación efectiva de todos los sectores afectados."}], "k": "c", "x": "Art. 27.5 CE.", "f": "Art. 27.5 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-5-programacion:N2"}, {"c": "CE-a27-5-programacion", "n": 3, "e": "¿Qué apartado del art. 27 CE garantiza el derecho de todos a la educación mediante una programación general de la enseñanza?", "o": [{"letra": "a", "texto": "El 8."}, {"letra": "b", "texto": "El 1."}, {"letra": "c", "texto": "El 5."}], "k": "c", "x": "Art. 27.5 CE. El 27.1 reconoce el derecho y el 27.8 trata de la inspección y homologación.", "f": "Art. 27.5 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-5-programacion:N3"}, {"c": "CE-a27-6-creacion-centros", "n": 1, "e": "Según el art. 27.6 CE, ¿pueden las personas jurídicas crear centros docentes?", "o": [{"letra": "a", "texto": "No, solo las personas físicas"}, {"letra": "b", "texto": "Sí"}], "k": "b", "x": "Art. 27.6 CE: personas físicas y jurídicas.", "f": "Art. 27.6 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-6-creacion-centros:N1"}, {"c": "CE-a27-6-creacion-centros", "n": 2, "e": "Según el art. 27.6 CE, la libertad de creación de centros docentes se ejerce:", "o": [{"letra": "a", "texto": "Dentro del respeto a los principios constitucionales."}, {"letra": "b", "texto": "Previa autorización del Ministerio de Educación."}, {"letra": "c", "texto": "Solo por entidades sin ánimo de lucro."}], "k": "a", "x": "Art. 27.6 CE.", "f": "Art. 27.6 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-6-creacion-centros:N2"}, {"c": "CE-a27-6-creacion-centros", "n": 3, "e": "El art. 27.6 CE reconoce la libertad de creación de centros docentes a:", "o": [{"letra": "a", "texto": "Los poderes públicos y las Universidades."}, {"letra": "b", "texto": "Las confesiones religiosas y las asociaciones de padres."}, {"letra": "c", "texto": "Las personas físicas y jurídicas."}], "k": "c", "x": "Art. 27.6 CE.", "f": "Art. 27.6 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-6-creacion-centros:N3"}, {"c": "CE-a27-7-control-gestion", "n": 1, "e": "Según el art. 27.7 CE, ¿intervienen los padres en el control y gestión de los centros sostenidos con fondos públicos?", "o": [{"letra": "a", "texto": "Sí"}, {"letra": "b", "texto": "No, solo los profesores"}], "k": "a", "x": "Art. 27.7 CE: profesores, padres y, en su caso, alumnos.", "f": "Art. 27.7 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-7-control-gestion:N1"}, {"c": "CE-a27-7-control-gestion", "n": 2, "e": "Según el art. 27.7 CE, intervendrán en el control y gestión de los centros sostenidos por la Administración con fondos públicos:", "o": [{"letra": "a", "texto": "Los profesores, los padres y, en su caso, los alumnos."}, {"letra": "b", "texto": "Los padres y los ayuntamientos."}, {"letra": "c", "texto": "Los profesores y la Administración educativa."}], "k": "a", "x": "Art. 27.7 CE.", "f": "Art. 27.7 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-7-control-gestion:N2"}, {"c": "CE-a27-7-control-gestion", "n": 3, "e": "Según el art. 27.7 CE, la intervención de los alumnos en el control y gestión de los centros sostenidos con fondos públicos:", "o": [{"letra": "a", "texto": "No está prevista en la Constitución."}, {"letra": "b", "texto": "Se produce «en su caso», en los términos que la ley establezca."}, {"letra": "c", "texto": "Es obligatoria en todos los niveles educativos, incluida la Universidad."}], "k": "b", "x": "Art. 27.7 CE: «y, en su caso, los alumnos».", "f": "Art. 27.7 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-7-control-gestion:N3"}, {"c": "CE-a27-8-inspeccion", "n": 1, "e": "Según el art. 27.8 CE, los poderes públicos inspeccionarán y homologarán…", "o": [{"letra": "a", "texto": "los títulos extranjeros"}, {"letra": "b", "texto": "el sistema educativo"}], "k": "b", "x": "Art. 27.8 CE.", "f": "Art. 27.8 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-8-inspeccion:N1"}, {"c": "CE-a27-8-inspeccion", "n": 2, "e": "Según el art. 27.8 CE, los poderes públicos inspeccionarán y homologarán el sistema educativo para:", "o": [{"letra": "a", "texto": "Garantizar la calidad de la enseñanza privada."}, {"letra": "b", "texto": "Garantizar el cumplimiento de las leyes."}, {"letra": "c", "texto": "Asegurar la libertad de cátedra."}], "k": "b", "x": "Art. 27.8 CE.", "f": "Art. 27.8 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-8-inspeccion:N2"}, {"c": "CE-a27-8-inspeccion", "n": 3, "e": "Según el art. 27.8 CE, ¿qué dos acciones realizan los poderes públicos sobre el sistema educativo?", "o": [{"letra": "a", "texto": "Financiar y dirigir."}, {"letra": "b", "texto": "Autorizar y sancionar."}, {"letra": "c", "texto": "Inspeccionar y homologar."}], "k": "c", "x": "Art. 27.8 CE: «inspeccionarán y homologarán».", "f": "Art. 27.8 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-8-inspeccion:N3"}, {"c": "CE-a27-9-ayudas", "n": 1, "e": "Según el art. 27.9 CE, ¿ayudan los poderes públicos a los centros docentes?", "o": [{"letra": "a", "texto": "Sí, a los que reúnan los requisitos que la ley establezca"}, {"letra": "b", "texto": "No, solo a los centros públicos"}], "k": "a", "x": "Art. 27.9 CE.", "f": "Art. 27.9 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-9-ayudas:N1"}, {"c": "CE-a27-9-ayudas", "n": 2, "e": "Según el art. 27.9 CE, los poderes públicos ayudarán a los centros docentes que:", "o": [{"letra": "a", "texto": "Reúnan los requisitos que la ley establezca."}, {"letra": "b", "texto": "Sean de titularidad pública o concertados con la Administración."}, {"letra": "c", "texto": "No tengan ideario propio."}], "k": "a", "x": "Art. 27.9 CE.", "f": "Art. 27.9 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-9-ayudas:N2"}, {"c": "CE-a27-9-ayudas", "n": 3, "e": "Los requisitos para que un centro docente reciba ayuda de los poderes públicos (art. 27.9 CE) los establece:", "o": [{"letra": "a", "texto": "El Gobierno, por real decreto."}, {"letra": "b", "texto": "La propia Constitución."}, {"letra": "c", "texto": "La ley."}], "k": "c", "x": "Art. 27.9 CE: «que reúnan los requisitos que la ley establezca».", "f": "Art. 27.9 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-9-ayudas:N3"}, {"c": "CE-a27-10-universidades", "n": 1, "e": "Según el art. 27.10 CE, se reconoce la autonomía de…", "o": [{"letra": "a", "texto": "las Universidades"}, {"letra": "b", "texto": "los colegios públicos"}], "k": "a", "x": "Art. 27.10 CE.", "f": "Art. 27.10 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-10-universidades:N1"}, {"c": "CE-a27-10-universidades", "n": 2, "e": "Según el art. 27.10 CE, la autonomía de las Universidades se reconoce:", "o": [{"letra": "a", "texto": "En los términos que fije cada Comunidad Autónoma por decreto."}, {"letra": "b", "texto": "Sin límite alguno."}, {"letra": "c", "texto": "En los términos que la ley establezca."}], "k": "c", "x": "Art. 27.10 CE.", "f": "Art. 27.10 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-10-universidades:N2"}, {"c": "CE-a27-10-universidades", "n": 3, "e": "¿En qué apartado del art. 27 CE se reconoce la autonomía universitaria?", "o": [{"letra": "a", "texto": "En el 6."}, {"letra": "b", "texto": "En el 10."}, {"letra": "c", "texto": "En el 1."}], "k": "b", "x": "Art. 27.10 CE.", "f": "Art. 27.10 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a27-10-universidades:N3"}, {"c": "CE-a28-1-sindicacion", "n": 1, "e": "Según el art. 28.1 CE, ¿puede alguien ser obligado a afiliarse a un sindicato?", "o": [{"letra": "a", "texto": "Sí, en los servicios esenciales"}, {"letra": "b", "texto": "No"}], "k": "b", "x": "Art. 28.1 CE: «Nadie podrá ser obligado a afiliarse a un sindicato».", "f": "Art. 28.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a28-1-sindicacion:N1"}, {"c": "CE-a28-1-sindicacion", "n": 2, "e": "Según el art. 28.1 CE, respecto de los funcionarios públicos, la ley:", "o": [{"letra": "a", "texto": "Regulará las peculiaridades del ejercicio del derecho a sindicarse."}, {"letra": "b", "texto": "Podrá exceptuar su derecho a sindicarse."}, {"letra": "c", "texto": "Prohibirá su afiliación a sindicatos de ámbito nacional."}], "k": "a", "x": "Art. 28.1 CE. Limitar o exceptuar se prevé para las Fuerzas o Institutos armados y Cuerpos con disciplina militar; para los funcionarios, solo regular peculiaridades.", "f": "Art. 28.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a28-1-sindicacion:N2"}, {"c": "CE-a28-1-sindicacion", "n": 3, "e": "Según el art. 28.1 CE, la libertad sindical comprende:", "o": [{"letra": "a", "texto": "Fundar sindicatos, afiliarse al de su elección y que los sindicatos formen confederaciones e internacionales."}, {"letra": "b", "texto": "Solo el derecho a afiliarse a los sindicatos ya existentes."}, {"letra": "c", "texto": "Fundar sindicatos y afiliarse al de su elección, pero no que los sindicatos formen confederaciones."}], "k": "a", "x": "Art. 28.1 CE.", "f": "Art. 28.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a28-1-sindicacion:N3"}, {"c": "CE-a28-2-huelga", "n": 1, "e": "Según el art. 28.2 CE, el derecho a la huelga se reconoce a…", "o": [{"letra": "a", "texto": "los trabajadores"}, {"letra": "b", "texto": "los trabajadores y los empresarios"}], "k": "a", "x": "Art. 28.2 CE: huelga de los trabajadores. Las medidas de conflicto colectivo de trabajadores y empresarios están en el art. 37.2.", "f": "Art. 28.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a28-2-huelga:N1"}, {"c": "CE-a28-2-huelga", "n": 2, "e": "Según el art. 28.2 CE, la ley que regule el derecho de huelga establecerá las garantías precisas para asegurar:", "o": [{"letra": "a", "texto": "El mantenimiento de los servicios esenciales de la comunidad."}, {"letra": "b", "texto": "La negociación previa entre las partes."}, {"letra": "c", "texto": "El funcionamiento normal de las empresas durante la huelga."}], "k": "a", "x": "Art. 28.2 CE: «el mantenimiento de los servicios esenciales de la comunidad».", "f": "Art. 28.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a28-2-huelga:N2"}, {"c": "CE-a28-2-huelga", "n": 3, "e": "Huelga (art. 28.2) y medidas de conflicto colectivo (art. 37.2): ¿qué afirmación es correcta?", "o": [{"letra": "a", "texto": "La huelga es de trabajadores y empresarios; el conflicto colectivo, solo de los trabajadores."}, {"letra": "b", "texto": "La huelga es solo de los trabajadores; el conflicto colectivo, de trabajadores y empresarios."}, {"letra": "c", "texto": "Ambos derechos son solo de los trabajadores."}], "k": "b", "x": "Art. 28.2: derecho a la huelga «de los trabajadores». Art. 37.2: «de los trabajadores y empresarios».", "f": "Art. 28.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a28-2-huelga:N3"}]'::jsonb) AS x(c text, n int, e text, o jsonb, k text, x text, f text, h text);
UPDATE public.questions q SET enunciado = qq.e, opciones = qq.o, correcta = qq.k, explicacion = qq.x, fuente_normativa = qq.f, nivel = qq.n, concept_id = qq.c, estado = 'publicada', topic_id = (SELECT id FROM _tema) FROM _qq qq WHERE q.hash_dedupe = qq.h;
INSERT INTO public.questions (topic_id, enunciado, opciones, correcta, explicacion, fuente_normativa, estado, nivel, origen_tipo, origen_archivo, concept_id, hash_dedupe) SELECT (SELECT id FROM _tema), qq.e, qq.o, qq.k, qq.x, qq.f, 'publicada', qq.n, 'propio', 'data/constitucion/titulo-i.json', qq.c, qq.h FROM _qq qq WHERE NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.hash_dedupe = qq.h);
COMMIT;
-- BLOQUE
BEGIN;
CREATE TEMP TABLE _tema ON COMMIT DROP AS SELECT id FROM public.topics WHERE convocatoria_id = 1 AND numero = 1;
DO $$ BEGIN IF (SELECT count(*) FROM _tema) <> 1 THEN RAISE EXCEPTION 'tema 1 de la convocatoria 1 no encontrado o duplicado'; END IF; END $$;
WITH cc AS (SELECT * FROM jsonb_to_recordset('[{"id": "CE-a29-1-peticion", "apartado": "Título I · Art. 29.1", "orden": 900, "pregunta": "¿Cómo puede ejercerse el derecho de petición (art. 29.1 CE)?", "respuesta": "De forma individual y colectiva, por escrito, en la forma y con los efectos que determine la ley.", "fuente": "Constitución Española, art. 29.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Todos los españoles tendrán el derecho de petición individual y colectiva, por escrito, en la forma y con los efectos que determine la ley.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a29-2-militares"]}, {"id": "CE-a29-2-militares", "apartado": "Título I · Art. 29.2", "orden": 910, "pregunta": "¿Cómo pueden ejercer el derecho de petición los miembros de las Fuerzas o Institutos armados (art. 29.2 CE)?", "respuesta": "Solo individualmente y con arreglo a su legislación específica.", "fuente": "Constitución Española, art. 29.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "podrán ejercer este derecho sólo individualmente y con arreglo a lo dispuesto en su legislación específica", "tipo": "regla", "prioridad": 1, "conf": ["CE-a29-1-peticion", "CE-a28-1-sindicacion"]}, {"id": "CE-a30-1-defender", "apartado": "Título I · Art. 30.1", "orden": 920, "pregunta": "¿Qué derecho y deber tienen los españoles según el art. 30.1 CE?", "respuesta": "El derecho y el deber de defender a España.", "fuente": "Constitución Española, art. 30.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Los españoles tienen el derecho y el deber de defender a España.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a8-1-mision"]}, {"id": "CE-a30-2-objecion", "apartado": "Título I · Art. 30.2", "orden": 930, "pregunta": "¿Qué regulará la ley según el art. 30.2 CE?", "respuesta": "Las obligaciones militares de los españoles, la objeción de conciencia con las debidas garantías y las demás causas de exención del servicio militar obligatorio, pudiendo imponer una prestación social sustitutoria.", "fuente": "Constitución Española, art. 30.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "regulará, con las debidas garantías, la objeción de conciencia", "tipo": "regla", "prioridad": 1, "conf": ["CE-a53-2-amparo"]}, {"id": "CE-a30-3-servicio-civil", "apartado": "Título I · Art. 30.3", "orden": 940, "pregunta": "¿Qué puede establecerse según el art. 30.3 CE?", "respuesta": "Un servicio civil para el cumplimiento de fines de interés general.", "fuente": "Constitución Española, art. 30.3 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Podrá establecerse un servicio civil para el cumplimiento de fines de interés general.", "tipo": "regla", "prioridad": 3, "conf": ["CE-a30-4-catastrofe"]}, {"id": "CE-a30-4-catastrofe", "apartado": "Título I · Art. 30.4", "orden": 950, "pregunta": "¿Qué puede regularse mediante ley según el art. 30.4 CE?", "respuesta": "Los deberes de los ciudadanos en los casos de grave riesgo, catástrofe o calamidad pública.", "fuente": "Constitución Española, art. 30.4 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Mediante ley podrán regularse los deberes de los ciudadanos en los casos de grave riesgo, catástrofe o calamidad pública.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a30-3-servicio-civil"]}, {"id": "CE-a31-1-tributos", "apartado": "Título I · Art. 31.1", "orden": 960, "pregunta": "¿En qué principios se inspira el sistema tributario y qué alcance no puede tener (art. 31.1 CE)?", "respuesta": "Es un sistema justo inspirado en los principios de igualdad y progresividad que, en ningún caso, tendrá alcance confiscatorio; todos contribuyen según su capacidad económica.", "fuente": "Constitución Española, art. 31.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "mediante un sistema tributario justo inspirado en los principios de igualdad y progresividad que, en ningún caso, tendrá alcance confiscatorio", "tipo": "lista", "prioridad": 1, "conf": ["CE-a31-2-gasto"]}, {"id": "CE-a31-2-gasto", "apartado": "Título I · Art. 31.2", "orden": 970, "pregunta": "¿Qué criterios rigen el gasto público según el art. 31.2 CE?", "respuesta": "Realizará una asignación equitativa de los recursos públicos, y su programación y ejecución responderán a los criterios de eficiencia y economía.", "fuente": "Constitución Española, art. 31.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "su programación y ejecución responderán a los criterios de eficiencia y economía", "tipo": "regla", "prioridad": 2, "conf": ["CE-a31-1-tributos"]}, {"id": "CE-a31-3-prestaciones", "apartado": "Título I · Art. 31.3", "orden": 980, "pregunta": "¿Cómo pueden establecerse prestaciones personales o patrimoniales de carácter público (art. 31.3 CE)?", "respuesta": "Solo con arreglo a la ley.", "fuente": "Constitución Española, art. 31.3 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Sólo podrán establecerse prestaciones personales o patrimoniales de carácter público con arreglo a la ley.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a30-4-catastrofe"]}, {"id": "CE-a32-1-matrimonio", "apartado": "Título I · Art. 32.1", "orden": 990, "pregunta": "¿Qué derecho reconoce el art. 32.1 CE?", "respuesta": "El derecho del hombre y la mujer a contraer matrimonio con plena igualdad jurídica.", "fuente": "Constitución Española, art. 32.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "El hombre y la mujer tienen derecho a contraer matrimonio con plena igualdad jurídica.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a32-2-ley"]}, {"id": "CE-a32-2-ley", "apartado": "Título I · Art. 32.2", "orden": 1000, "pregunta": "¿Qué aspectos del matrimonio regulará la ley según el art. 32.2 CE?", "respuesta": "Las formas de matrimonio, la edad y capacidad para contraerlo, los derechos y deberes de los cónyuges, las causas de separación y disolución y sus efectos.", "fuente": "Constitución Española, art. 32.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "La ley regulará las formas de matrimonio, la edad y capacidad para contraerlo, los derechos y deberes de los cónyuges, las causas de separación y disolución y sus efectos.", "tipo": "lista", "prioridad": 3, "conf": ["CE-a32-1-matrimonio"]}, {"id": "CE-a33-1-propiedad", "apartado": "Título I · Art. 33.1", "orden": 1010, "pregunta": "¿Qué derechos reconoce el art. 33.1 CE?", "respuesta": "El derecho a la propiedad privada y a la herencia.", "fuente": "Constitución Española, art. 33.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Se reconoce el derecho a la propiedad privada y a la herencia.", "tipo": "lista", "prioridad": 2, "conf": ["CE-a33-2-funcion-social"]}, {"id": "CE-a33-2-funcion-social", "apartado": "Título I · Art. 33.2", "orden": 1020, "pregunta": "¿Qué delimitará el contenido de los derechos de propiedad y herencia (art. 33.2 CE)?", "respuesta": "Su función social, de acuerdo con las leyes.", "fuente": "Constitución Española, art. 33.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "La función social de estos derechos delimitará su contenido, de acuerdo con las leyes.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a33-1-propiedad", "CE-a33-3-expropiacion"]}, {"id": "CE-a33-3-expropiacion", "apartado": "Título I · Art. 33.3", "orden": 1030, "pregunta": "¿Qué requisitos exige el art. 33.3 CE para privar a alguien de sus bienes y derechos?", "respuesta": "Causa justificada de utilidad pública o interés social, la correspondiente indemnización y conformidad con lo dispuesto por las leyes.", "fuente": "Constitución Española, art. 33.3 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Nadie podrá ser privado de sus bienes y derechos sino por causa justificada de utilidad pública o interés social, mediante la correspondiente indemnización y de conformidad con lo dispuesto por las leyes.", "tipo": "lista", "prioridad": 1, "conf": ["CE-a33-2-funcion-social"]}, {"id": "CE-a34-1-fundacion", "apartado": "Título I · Art. 34.1", "orden": 1040, "pregunta": "¿Para qué fines se reconoce el derecho de fundación (art. 34.1 CE)?", "respuesta": "Para fines de interés general, con arreglo a la ley.", "fuente": "Constitución Española, art. 34.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Se reconoce el derecho de fundación para fines de interés general, con arreglo a la ley.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a22-1-asociacion"]}, {"id": "CE-a34-2-remision", "apartado": "Título I · Art. 34.2", "orden": 1050, "pregunta": "¿Qué apartados del art. 22 se aplican también a las fundaciones (art. 34.2 CE)?", "respuesta": "Los apartados 2 y 4: ilegalidad por fines o medios delictivos y disolución o suspensión solo por resolución judicial motivada.", "fuente": "Constitución Española, art. 34.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Regirá también para las fundaciones lo dispuesto en los apartados 2 y 4 del artículo 22.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a22-4-disolucion", "CE-a22-2-ilegales"]}, {"id": "CE-a35-1-trabajo", "apartado": "Título I · Art. 35.1", "orden": 1060, "pregunta": "¿Qué deber y qué derechos reconoce el art. 35.1 CE a los españoles?", "respuesta": "El deber de trabajar y el derecho al trabajo, a la libre elección de profesión u oficio, a la promoción a través del trabajo y a una remuneración suficiente, sin discriminación por razón de sexo.", "fuente": "Constitución Española, art. 35.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Todos los españoles tienen el deber de trabajar y el derecho al trabajo", "tipo": "lista", "prioridad": 1, "conf": ["CE-a40-1-pleno-empleo"]}, {"id": "CE-a35-2-estatuto", "apartado": "Título I · Art. 35.2", "orden": 1070, "pregunta": "¿Qué regulará la ley según el art. 35.2 CE?", "respuesta": "Un estatuto de los trabajadores.", "fuente": "Constitución Española, art. 35.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "La ley regulará un estatuto de los trabajadores.", "tipo": "dato", "prioridad": 2, "conf": ["CE-a37-1-negociacion"]}, {"id": "CE-a36-colegios", "apartado": "Título I · Art. 36", "orden": 1080, "pregunta": "¿Qué dice el art. 36 CE sobre los Colegios Profesionales?", "respuesta": "La ley regulará su régimen jurídico y el ejercicio de las profesiones tituladas; su estructura interna y funcionamiento deberán ser democráticos.", "fuente": "Constitución Española, art. 36 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "La estructura interna y el funcionamiento de los Colegios deberán ser democráticos.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a52-organizaciones", "CE-a6-partidos-regimen"]}, {"id": "CE-a37-1-negociacion", "apartado": "Título I · Art. 37.1", "orden": 1090, "pregunta": "¿Qué garantizará la ley según el art. 37.1 CE?", "respuesta": "El derecho a la negociación colectiva laboral entre representantes de trabajadores y empresarios, así como la fuerza vinculante de los convenios.", "fuente": "Constitución Española, art. 37.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "La ley garantizará el derecho a la negociación colectiva laboral entre los representantes de los trabajadores y empresarios, así como la fuerza vinculante de los convenios.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a37-2-conflicto"]}]'::jsonb) AS x(id text, apartado text, orden int, pregunta text, respuesta text, fuente text, cita text, tipo text, prioridad smallint, conf text[])) INSERT INTO public.concepts (id, topic_id, documento, apartado, orden, pregunta, respuesta, fuente, cita, tipo, prioridad, confundible_con, estado) SELECT cc.id, t.id, 'CE', cc.apartado, cc.orden, cc.pregunta, cc.respuesta, cc.fuente, cc.cita, cc.tipo, cc.prioridad, coalesce(cc.conf, '{}'), 'publicado' FROM cc, _tema t ON CONFLICT (id) DO UPDATE SET topic_id = EXCLUDED.topic_id, documento = EXCLUDED.documento, apartado = EXCLUDED.apartado, orden = EXCLUDED.orden, pregunta = EXCLUDED.pregunta, respuesta = EXCLUDED.respuesta, fuente = EXCLUDED.fuente, cita = EXCLUDED.cita, tipo = EXCLUDED.tipo, prioridad = EXCLUDED.prioridad, confundible_con = EXCLUDED.confundible_con, estado = EXCLUDED.estado;
CREATE TEMP TABLE _qq ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"c": "CE-a29-1-peticion", "n": 1, "e": "Según el art. 29.1 CE, el derecho de petición se ejerce…", "o": [{"letra": "a", "texto": "de forma oral o escrita"}, {"letra": "b", "texto": "por escrito"}], "k": "b", "x": "Art. 29.1 CE: por escrito.", "f": "Art. 29.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a29-1-peticion:N1"}, {"c": "CE-a29-1-peticion", "n": 2, "e": "Según el art. 29.1 CE, todos los españoles tendrán el derecho de petición:", "o": [{"letra": "a", "texto": "Individual y colectiva, por escrito."}, {"letra": "b", "texto": "Colectiva, a través de asociaciones inscritas."}, {"letra": "c", "texto": "Individual, oral o escrita."}], "k": "a", "x": "Art. 29.1 CE.", "f": "Art. 29.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a29-1-peticion:N2"}, {"c": "CE-a29-1-peticion", "n": 3, "e": "Según el art. 29.1 CE, ¿quiénes son titulares del derecho de petición?", "o": [{"letra": "a", "texto": "Los ciudadanos mayores de edad inscritos en el censo."}, {"letra": "b", "texto": "Todas las personas."}, {"letra": "c", "texto": "Todos los españoles."}], "k": "c", "x": "Art. 29.1 CE: «Todos los españoles».", "f": "Art. 29.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a29-1-peticion:N3"}, {"c": "CE-a29-2-militares", "n": 1, "e": "Según el art. 29.2 CE, los miembros de las Fuerzas Armadas pueden ejercer el derecho de petición…", "o": [{"letra": "a", "texto": "solo colectivamente"}, {"letra": "b", "texto": "solo individualmente"}], "k": "b", "x": "Art. 29.2 CE.", "f": "Art. 29.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a29-2-militares:N1"}, {"c": "CE-a29-2-militares", "n": 2, "e": "Según el art. 29.2 CE, los miembros de las Fuerzas o Institutos armados o de los Cuerpos sometidos a disciplina militar podrán ejercer el derecho de petición:", "o": [{"letra": "a", "texto": "No pueden ejercerlo mientras estén en servicio activo."}, {"letra": "b", "texto": "Individual y colectivamente, como el resto de los españoles, por escrito."}, {"letra": "c", "texto": "Sólo individualmente y con arreglo a lo dispuesto en su legislación específica."}], "k": "c", "x": "Art. 29.2 CE.", "f": "Art. 29.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a29-2-militares:N2"}, {"c": "CE-a29-2-militares", "n": 3, "e": "Para los miembros de los Cuerpos sometidos a disciplina militar, la Constitución:", "o": [{"letra": "a", "texto": "Permite a la ley limitar o exceptuar la sindicación y limita la petición a la forma individual."}, {"letra": "b", "texto": "Les prohíbe expresamente tanto la sindicación como el ejercicio del derecho de petición."}, {"letra": "c", "texto": "Les reconoce la sindicación sin límites, pero no el derecho de petición."}], "k": "a", "x": "Art. 28.1: la ley podrá limitar o exceptuar la sindicación. Art. 29.2: petición solo individual.", "f": "Art. 29.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a29-2-militares:N3"}, {"c": "CE-a30-1-defender", "n": 1, "e": "Según el art. 30.1 CE, defender a España es para los españoles…", "o": [{"letra": "a", "texto": "solo un deber"}, {"letra": "b", "texto": "un derecho y un deber"}], "k": "b", "x": "Art. 30.1 CE: «el derecho y el deber de defender a España».", "f": "Art. 30.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a30-1-defender:N1"}, {"c": "CE-a30-1-defender", "n": 2, "e": "Según el art. 30.1 CE, ¿quiénes tienen el derecho y el deber de defender a España?", "o": [{"letra": "a", "texto": "Los poderes públicos."}, {"letra": "b", "texto": "Las Fuerzas Armadas, exclusivamente."}, {"letra": "c", "texto": "Los españoles."}], "k": "c", "x": "Art. 30.1 CE. La defensa de la integridad territorial como misión corresponde a las Fuerzas Armadas (art. 8.1), pero el derecho-deber del art. 30.1 es de los españoles.", "f": "Art. 30.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a30-1-defender:N2"}, {"c": "CE-a30-1-defender", "n": 3, "e": "El art. 30.1 CE se encuentra en:", "o": [{"letra": "a", "texto": "El Capítulo tercero del Título I."}, {"letra": "b", "texto": "La Sección 1.ª del Capítulo segundo del Título I."}, {"letra": "c", "texto": "La Sección 2.ª del Capítulo segundo del Título I."}], "k": "c", "x": "La Sección 2.ª («De los derechos y deberes de los ciudadanos») abarca los arts. 30 a 38.", "f": "Art. 30.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a30-1-defender:N3"}, {"c": "CE-a30-2-objecion", "n": 1, "e": "¿Qué artículo de la Constitución menciona la objeción de conciencia al servicio militar?", "o": [{"letra": "a", "texto": "El art. 16.1"}, {"letra": "b", "texto": "El art. 30.2"}], "k": "b", "x": "Art. 30.2 CE.", "f": "Art. 30.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a30-2-objecion:N1"}, {"c": "CE-a30-2-objecion", "n": 2, "e": "Según el art. 30.2 CE, la ley regulará las causas de exención del servicio militar obligatorio, pudiendo imponer, en su caso:", "o": [{"letra": "a", "texto": "Una sanción económica."}, {"letra": "b", "texto": "Una prestación social sustitutoria."}, {"letra": "c", "texto": "Un servicio militar de duración reducida."}], "k": "b", "x": "Art. 30.2 CE: «pudiendo imponer, en su caso, una prestación social sustitutoria».", "f": "Art. 30.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a30-2-objecion:N2"}, {"c": "CE-a30-2-objecion", "n": 3, "e": "La objeción de conciencia del art. 30 CE, según el art. 53.2 CE:", "o": [{"letra": "a", "texto": "No tiene protección jurisdiccional específica."}, {"letra": "b", "texto": "Puede protegerse mediante recurso de amparo ante el Tribunal Constitucional."}, {"letra": "c", "texto": "Solo puede alegarse ante la jurisdicción ordinaria, según las leyes que la desarrollen."}], "k": "b", "x": "Art. 53.2 CE: el recurso de amparo «será aplicable a la objeción de conciencia reconocida en el artículo 30».", "f": "Art. 30.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a30-2-objecion:N3"}, {"c": "CE-a30-3-servicio-civil", "n": 1, "e": "Según el art. 30.3 CE, podrá establecerse un servicio civil para el cumplimiento de fines de…", "o": [{"letra": "a", "texto": "defensa nacional"}, {"letra": "b", "texto": "interés general"}], "k": "b", "x": "Art. 30.3 CE.", "f": "Art. 30.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a30-3-servicio-civil:N1"}, {"c": "CE-a30-3-servicio-civil", "n": 2, "e": "Según el art. 30.3 CE, ¿qué podrá establecerse para el cumplimiento de fines de interés general?", "o": [{"letra": "a", "texto": "Un servicio civil."}, {"letra": "b", "texto": "Una prestación patrimonial obligatoria."}, {"letra": "c", "texto": "Un servicio militar voluntario."}], "k": "a", "x": "Art. 30.3 CE.", "f": "Art. 30.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a30-3-servicio-civil:N2"}, {"c": "CE-a30-3-servicio-civil", "n": 3, "e": "Según el art. 30.3 CE, el servicio civil para fines de interés general:", "o": [{"letra": "a", "texto": "Podrá establecerse."}, {"letra": "b", "texto": "Sustituye siempre al servicio militar."}, {"letra": "c", "texto": "Es obligatorio para todos los españoles."}], "k": "a", "x": "Art. 30.3 CE: «Podrá establecerse»; es una posibilidad, no una obligación.", "f": "Art. 30.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a30-3-servicio-civil:N3"}, {"c": "CE-a30-4-catastrofe", "n": 1, "e": "Según el art. 30.4 CE, mediante ley podrán regularse los deberes de los ciudadanos en casos de grave riesgo, catástrofe o…", "o": [{"letra": "a", "texto": "calamidad pública"}, {"letra": "b", "texto": "conflicto armado"}], "k": "a", "x": "Art. 30.4 CE: grave riesgo, catástrofe o calamidad pública.", "f": "Art. 30.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a30-4-catastrofe:N1"}, {"c": "CE-a30-4-catastrofe", "n": 2, "e": "El fundamento constitucional de los deberes de los ciudadanos en protección civil ante una catástrofe se encuentra en el art.:", "o": [{"letra": "a", "texto": "30.4 CE."}, {"letra": "b", "texto": "15 CE."}, {"letra": "c", "texto": "43.2 CE."}], "k": "a", "x": "Art. 30.4 CE: deberes de los ciudadanos en casos de grave riesgo, catástrofe o calamidad pública.", "f": "Art. 30.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a30-4-catastrofe:N2"}, {"c": "CE-a30-4-catastrofe", "n": 3, "e": "Según el art. 30.4 CE, los deberes de los ciudadanos en casos de grave riesgo, catástrofe o calamidad pública:", "o": [{"letra": "a", "texto": "Los fija directamente la Constitución."}, {"letra": "b", "texto": "Podrán regularse mediante ley."}, {"letra": "c", "texto": "Solo pueden imponerse durante el estado de alarma."}], "k": "b", "x": "Art. 30.4 CE: «Mediante ley podrán regularse…».", "f": "Art. 30.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a30-4-catastrofe:N3"}, {"c": "CE-a31-1-tributos", "n": 1, "e": "Según el art. 31.1 CE, ¿puede el sistema tributario tener alcance confiscatorio?", "o": [{"letra": "a", "texto": "No, en ningún caso"}, {"letra": "b", "texto": "Sí, en casos excepcionales"}], "k": "a", "x": "Art. 31.1 CE.", "f": "Art. 31.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a31-1-tributos:N1"}, {"c": "CE-a31-1-tributos", "n": 2, "e": "Según el art. 31.1 CE, el sistema tributario justo se inspira en los principios de:", "o": [{"letra": "a", "texto": "Legalidad y seguridad jurídica."}, {"letra": "b", "texto": "Igualdad y progresividad."}, {"letra": "c", "texto": "Eficiencia y economía."}], "k": "b", "x": "Art. 31.1 CE. Eficiencia y economía son criterios del gasto público (art. 31.2).", "f": "Art. 31.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a31-1-tributos:N2"}, {"c": "CE-a31-1-tributos", "n": 3, "e": "Según el art. 31.1 CE, todos contribuirán al sostenimiento de los gastos públicos de acuerdo con:", "o": [{"letra": "a", "texto": "Su capacidad económica."}, {"letra": "b", "texto": "Su renta y su patrimonio."}, {"letra": "c", "texto": "Lo que disponga cada Comunidad Autónoma."}], "k": "a", "x": "Art. 31.1 CE: «de acuerdo con su capacidad económica».", "f": "Art. 31.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a31-1-tributos:N3"}, {"c": "CE-a31-2-gasto", "n": 1, "e": "Según el art. 31.2 CE, el gasto público realizará una asignación de los recursos públicos…", "o": [{"letra": "a", "texto": "equitativa"}, {"letra": "b", "texto": "proporcional a la población"}], "k": "a", "x": "Art. 31.2 CE: asignación equitativa.", "f": "Art. 31.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a31-2-gasto:N1"}, {"c": "CE-a31-2-gasto", "n": 2, "e": "Según el art. 31.2 CE, la programación y ejecución del gasto público responderán a los criterios de:", "o": [{"letra": "a", "texto": "Igualdad y progresividad."}, {"letra": "b", "texto": "Eficiencia y economía."}, {"letra": "c", "texto": "Transparencia y estabilidad presupuestaria."}], "k": "b", "x": "Art. 31.2 CE. Igualdad y progresividad son principios del sistema tributario (art. 31.1).", "f": "Art. 31.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a31-2-gasto:N2"}, {"c": "CE-a31-2-gasto", "n": 3, "e": "En el art. 31 CE, «igualdad y progresividad» y «eficiencia y economía» se refieren, respectivamente, a:", "o": [{"letra": "a", "texto": "Las prestaciones personales y las patrimoniales."}, {"letra": "b", "texto": "El gasto público y el sistema tributario."}, {"letra": "c", "texto": "El sistema tributario y el gasto público."}], "k": "c", "x": "Art. 31.1: sistema tributario. Art. 31.2: gasto público.", "f": "Art. 31.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a31-2-gasto:N3"}, {"c": "CE-a31-3-prestaciones", "n": 1, "e": "Según el art. 31.3 CE, las prestaciones personales o patrimoniales de carácter público solo pueden establecerse…", "o": [{"letra": "a", "texto": "con arreglo a la ley"}, {"letra": "b", "texto": "por decreto del Gobierno"}], "k": "a", "x": "Art. 31.3 CE.", "f": "Art. 31.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a31-3-prestaciones:N1"}, {"c": "CE-a31-3-prestaciones", "n": 2, "e": "Según el art. 31.3 CE, sólo podrán establecerse con arreglo a la ley las prestaciones de carácter público:", "o": [{"letra": "a", "texto": "Patrimoniales, exclusivamente."}, {"letra": "b", "texto": "Tributarias, exclusivamente."}, {"letra": "c", "texto": "Personales o patrimoniales."}], "k": "c", "x": "Art. 31.3 CE: personales o patrimoniales.", "f": "Art. 31.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a31-3-prestaciones:N2"}, {"c": "CE-a31-3-prestaciones", "n": 3, "e": "El art. 31.3 CE exige ley para establecer prestaciones públicas. ¿Qué tipo de prestaciones menciona?", "o": [{"letra": "a", "texto": "Las prestaciones de la Seguridad Social."}, {"letra": "b", "texto": "Personales o patrimoniales de carácter público."}, {"letra": "c", "texto": "Solo los impuestos estatales."}], "k": "b", "x": "Art. 31.3 CE.", "f": "Art. 31.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a31-3-prestaciones:N3"}, {"c": "CE-a32-1-matrimonio", "n": 1, "e": "Según el art. 32.1 CE, el hombre y la mujer tienen derecho a contraer matrimonio con plena…", "o": [{"letra": "a", "texto": "libertad religiosa"}, {"letra": "b", "texto": "igualdad jurídica"}], "k": "b", "x": "Art. 32.1 CE.", "f": "Art. 32.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a32-1-matrimonio:N1"}, {"c": "CE-a32-1-matrimonio", "n": 2, "e": "¿Qué artículo de la Constitución reconoce el derecho a contraer matrimonio?", "o": [{"letra": "a", "texto": "El 18."}, {"letra": "b", "texto": "El 32."}, {"letra": "c", "texto": "El 39."}], "k": "b", "x": "Art. 32 CE. El 39 trata de la protección de la familia.", "f": "Art. 32.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a32-1-matrimonio:N2"}, {"c": "CE-a32-1-matrimonio", "n": 3, "e": "El art. 32.1 CE reconoce el derecho a contraer matrimonio:", "o": [{"letra": "a", "texto": "Con plena igualdad jurídica."}, {"letra": "b", "texto": "Solo en forma civil."}, {"letra": "c", "texto": "Desde los dieciséis años."}], "k": "a", "x": "Art. 32.1 CE. La edad y las formas del matrimonio las regula la ley (art. 32.2).", "f": "Art. 32.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a32-1-matrimonio:N3"}, {"c": "CE-a32-2-ley", "n": 1, "e": "Según el art. 32.2 CE, ¿quién regula la edad para contraer matrimonio?", "o": [{"letra": "a", "texto": "La propia Constitución"}, {"letra": "b", "texto": "La ley"}], "k": "b", "x": "Art. 32.2 CE.", "f": "Art. 32.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a32-2-ley:N1"}, {"c": "CE-a32-2-ley", "n": 2, "e": "Según el art. 32.2 CE, la ley regulará, entre otros aspectos del matrimonio:", "o": [{"letra": "a", "texto": "Las causas de separación y disolución y sus efectos."}, {"letra": "b", "texto": "El régimen económico de las parejas de hecho."}, {"letra": "c", "texto": "La custodia de los hijos menores."}], "k": "a", "x": "Art. 32.2 CE.", "f": "Art. 32.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a32-2-ley:N2"}, {"c": "CE-a32-2-ley", "n": 3, "e": "¿Cuál de estos aspectos NO menciona el art. 32.2 CE como materia que la ley regulará?", "o": [{"letra": "a", "texto": "Los derechos y deberes de los cónyuges."}, {"letra": "b", "texto": "Las formas de matrimonio."}, {"letra": "c", "texto": "La filiación de los hijos."}], "k": "c", "x": "Art. 32.2 CE: formas, edad y capacidad, derechos y deberes de los cónyuges, separación y disolución. La filiación aparece en el art. 39.2.", "f": "Art. 32.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a32-2-ley:N3"}, {"c": "CE-a33-1-propiedad", "n": 1, "e": "Según el art. 33.1 CE, se reconoce el derecho a la propiedad privada y a…", "o": [{"letra": "a", "texto": "la vivienda"}, {"letra": "b", "texto": "la herencia"}], "k": "b", "x": "Art. 33.1 CE.", "f": "Art. 33.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a33-1-propiedad:N1"}, {"c": "CE-a33-1-propiedad", "n": 2, "e": "¿Qué artículo de la Constitución reconoce el derecho a la propiedad privada y a la herencia?", "o": [{"letra": "a", "texto": "El 33."}, {"letra": "b", "texto": "El 47."}, {"letra": "c", "texto": "El 38."}], "k": "a", "x": "Art. 33.1 CE. El 38 trata de la libertad de empresa y el 47, de la vivienda.", "f": "Art. 33.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a33-1-propiedad:N2"}, {"c": "CE-a33-1-propiedad", "n": 3, "e": "El derecho a la propiedad privada del art. 33 CE se ubica en:", "o": [{"letra": "a", "texto": "La Sección 2.ª del Capítulo segundo del Título I."}, {"letra": "b", "texto": "El Capítulo tercero del Título I."}, {"letra": "c", "texto": "La Sección 1.ª del Capítulo segundo del Título I."}], "k": "a", "x": "La Sección 2.ª abarca los arts. 30 a 38. Por eso la propiedad no tiene recurso de amparo (art. 53.2).", "f": "Art. 33.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a33-1-propiedad:N3"}, {"c": "CE-a33-2-funcion-social", "n": 1, "e": "Según el art. 33.2 CE, ¿qué delimitará el contenido del derecho de propiedad?", "o": [{"letra": "a", "texto": "Su función social"}, {"letra": "b", "texto": "El valor de mercado"}], "k": "a", "x": "Art. 33.2 CE.", "f": "Art. 33.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a33-2-funcion-social:N1"}, {"c": "CE-a33-2-funcion-social", "n": 2, "e": "Según el art. 33.2 CE, la función social de la propiedad privada y la herencia delimitará su contenido de acuerdo con:", "o": [{"letra": "a", "texto": "La Constitución y los tratados."}, {"letra": "b", "texto": "Los reglamentos de cada Comunidad Autónoma."}, {"letra": "c", "texto": "Las leyes."}], "k": "c", "x": "Art. 33.2 CE: «de acuerdo con las leyes».", "f": "Art. 33.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a33-2-funcion-social:N2"}, {"c": "CE-a33-2-funcion-social", "n": 3, "e": "La «función social» aparece en el art. 33.2 CE como:", "o": [{"letra": "a", "texto": "La causa que permite expropiar los bienes sin necesidad de indemnización."}, {"letra": "b", "texto": "Un principio rector de la política social y económica."}, {"letra": "c", "texto": "El criterio que delimita el contenido de la propiedad y la herencia."}], "k": "c", "x": "Art. 33.2 CE. La expropiación (33.3) exige siempre indemnización.", "f": "Art. 33.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a33-2-funcion-social:N3"}, {"c": "CE-a33-3-expropiacion", "n": 1, "e": "Según el art. 33.3 CE, ¿puede privarse a alguien de sus bienes sin indemnización?", "o": [{"letra": "a", "texto": "Sí, por interés social"}, {"letra": "b", "texto": "No"}], "k": "b", "x": "Art. 33.3 CE: siempre mediante la correspondiente indemnización.", "f": "Art. 33.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a33-3-expropiacion:N1"}, {"c": "CE-a33-3-expropiacion", "n": 2, "e": "Según el art. 33.3 CE, nadie podrá ser privado de sus bienes y derechos sino por causa justificada de:", "o": [{"letra": "a", "texto": "Utilidad pública o interés social."}, {"letra": "b", "texto": "Seguridad nacional u orden público."}, {"letra": "c", "texto": "Interés general o urgente necesidad."}], "k": "a", "x": "Art. 33.3 CE.", "f": "Art. 33.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a33-3-expropiacion:N2"}, {"c": "CE-a33-3-expropiacion", "n": 3, "e": "¿Cuál de estos requisitos NO exige el art. 33.3 CE para privar a alguien de sus bienes?", "o": [{"letra": "a", "texto": "Resolución judicial previa."}, {"letra": "b", "texto": "La correspondiente indemnización."}, {"letra": "c", "texto": "Causa justificada de utilidad pública o interés social."}], "k": "a", "x": "Art. 33.3 CE: causa justificada, indemnización y conformidad con las leyes. No exige resolución judicial.", "f": "Art. 33.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a33-3-expropiacion:N3"}, {"c": "CE-a34-1-fundacion", "n": 1, "e": "Según el art. 34.1 CE, el derecho de fundación se reconoce para fines de…", "o": [{"letra": "a", "texto": "lucro"}, {"letra": "b", "texto": "interés general"}], "k": "b", "x": "Art. 34.1 CE.", "f": "Art. 34.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a34-1-fundacion:N1"}, {"c": "CE-a34-1-fundacion", "n": 2, "e": "Según el art. 34.1 CE, se reconoce el derecho de fundación:", "o": [{"letra": "a", "texto": "Solo para fines culturales y benéficos."}, {"letra": "b", "texto": "Para fines de interés general, con arreglo a la ley."}, {"letra": "c", "texto": "Para cualquier fin lícito, sin necesidad de ley."}], "k": "b", "x": "Art. 34.1 CE.", "f": "Art. 34.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a34-1-fundacion:N2"}, {"c": "CE-a34-1-fundacion", "n": 3, "e": "¿En qué artículo y sección de la Constitución se reconoce el derecho de fundación?", "o": [{"letra": "a", "texto": "Art. 34, Sección 1.ª del Capítulo segundo."}, {"letra": "b", "texto": "Art. 34, Sección 2.ª del Capítulo segundo."}, {"letra": "c", "texto": "Art. 22, Sección 1.ª del Capítulo segundo."}], "k": "b", "x": "El derecho de fundación (art. 34) está en la Sección 2.ª; el de asociación (art. 22), en la Sección 1.ª.", "f": "Art. 34.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a34-1-fundacion:N3"}, {"c": "CE-a34-2-remision", "n": 1, "e": "Según el art. 34.2 CE, a las fundaciones se les aplican apartados del artículo…", "o": [{"letra": "a", "texto": "22"}, {"letra": "b", "texto": "21"}], "k": "a", "x": "Art. 34.2 CE: apartados 2 y 4 del art. 22.", "f": "Art. 34.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a34-2-remision:N1"}, {"c": "CE-a34-2-remision", "n": 2, "e": "Según el art. 34.2 CE, regirá también para las fundaciones lo dispuesto en los apartados del artículo 22:", "o": [{"letra": "a", "texto": "3 y 5."}, {"letra": "b", "texto": "1 y 3."}, {"letra": "c", "texto": "2 y 4."}], "k": "c", "x": "Art. 34.2 CE.", "f": "Art. 34.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a34-2-remision:N2"}, {"c": "CE-a34-2-remision", "n": 3, "e": "Por remisión del art. 34.2 CE, una fundación:", "o": [{"letra": "a", "texto": "Debe inscribirse en un registro a los solos efectos de publicidad."}, {"letra": "b", "texto": "Está prohibida si tiene carácter secreto."}, {"letra": "c", "texto": "Solo puede ser disuelta o suspendida por resolución judicial motivada."}], "k": "c", "x": "El art. 34.2 remite a los apartados 2 (ilegalidad) y 4 (disolución judicial) del art. 22, no al 3 (registro) ni al 5 (secretas y paramilitares).", "f": "Art. 34.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a34-2-remision:N3"}, {"c": "CE-a35-1-trabajo", "n": 1, "e": "Según el art. 35.1 CE, trabajar es para los españoles…", "o": [{"letra": "a", "texto": "solo un derecho"}, {"letra": "b", "texto": "un deber y un derecho"}], "k": "b", "x": "Art. 35.1 CE: «el deber de trabajar y el derecho al trabajo».", "f": "Art. 35.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a35-1-trabajo:N1"}, {"c": "CE-a35-1-trabajo", "n": 2, "e": "Según el art. 35.1 CE, la remuneración del trabajador debe ser suficiente para satisfacer:", "o": [{"letra": "a", "texto": "Sus necesidades y las de su familia."}, {"letra": "b", "texto": "Sus necesidades básicas de vivienda y alimentación."}, {"letra": "c", "texto": "Sus necesidades personales y de formación profesional."}], "k": "a", "x": "Art. 35.1 CE.", "f": "Art. 35.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a35-1-trabajo:N2"}, {"c": "CE-a35-1-trabajo", "n": 3, "e": "Según el art. 35.1 CE, en materia de trabajo no puede hacerse en ningún caso discriminación por razón de:", "o": [{"letra": "a", "texto": "Sexo."}, {"letra": "b", "texto": "Nacionalidad."}, {"letra": "c", "texto": "Edad."}], "k": "a", "x": "Art. 35.1 CE: «sin que en ningún caso pueda hacerse discriminación por razón de sexo».", "f": "Art. 35.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a35-1-trabajo:N3"}, {"c": "CE-a35-2-estatuto", "n": 1, "e": "Según el art. 35.2 CE, la ley regulará un estatuto de…", "o": [{"letra": "a", "texto": "los funcionarios"}, {"letra": "b", "texto": "los trabajadores"}], "k": "b", "x": "Art. 35.2 CE.", "f": "Art. 35.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a35-2-estatuto:N1"}, {"c": "CE-a35-2-estatuto", "n": 2, "e": "¿Qué artículo de la Constitución dispone que la ley regulará un estatuto de los trabajadores?", "o": [{"letra": "a", "texto": "El 37.1."}, {"letra": "b", "texto": "El 28.1."}, {"letra": "c", "texto": "El 35.2."}], "k": "c", "x": "Art. 35.2 CE.", "f": "Art. 35.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a35-2-estatuto:N2"}, {"c": "CE-a35-2-estatuto", "n": 3, "e": "El estatuto de los funcionarios públicos y el de los trabajadores se prevén, respectivamente, en los arts.:", "o": [{"letra": "a", "texto": "28.1 y 37.1."}, {"letra": "b", "texto": "103.3 y 35.2."}, {"letra": "c", "texto": "35.2 y 103.3."}], "k": "b", "x": "Art. 103.3 CE: «La ley regulará el estatuto de los funcionarios públicos». Art. 35.2: estatuto de los trabajadores.", "f": "Art. 35.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a35-2-estatuto:N3"}, {"c": "CE-a36-colegios", "n": 1, "e": "Según el art. 36 CE, la estructura interna y el funcionamiento de los Colegios Profesionales deberán ser…", "o": [{"letra": "a", "texto": "jerárquicos"}, {"letra": "b", "texto": "democráticos"}], "k": "b", "x": "Art. 36 CE.", "f": "Art. 36 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a36-colegios:N1"}, {"c": "CE-a36-colegios", "n": 2, "e": "Según el art. 36 CE, la ley regulará las peculiaridades propias del régimen jurídico de los Colegios Profesionales y:", "o": [{"letra": "a", "texto": "El ejercicio de las profesiones tituladas."}, {"letra": "b", "texto": "La colegiación obligatoria de todos los trabajadores."}, {"letra": "c", "texto": "Los convenios colectivos de los profesionales."}], "k": "a", "x": "Art. 36 CE.", "f": "Art. 36 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a36-colegios:N2"}, {"c": "CE-a36-colegios", "n": 3, "e": "¿A cuál de estas entidades NO exige la Constitución expresamente estructura interna y funcionamiento democráticos?", "o": [{"letra": "a", "texto": "Las fundaciones."}, {"letra": "b", "texto": "Los Colegios Profesionales."}, {"letra": "c", "texto": "Las organizaciones profesionales del art. 52."}], "k": "a", "x": "La exigencia aparece para partidos (6), sindicatos y asociaciones empresariales (7), Colegios Profesionales (36) y organizaciones profesionales (52), pero no para las fundaciones (34).", "f": "Art. 36 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a36-colegios:N3"}, {"c": "CE-a37-1-negociacion", "n": 1, "e": "Según el art. 37.1 CE, la ley garantizará la fuerza vinculante de…", "o": [{"letra": "a", "texto": "los convenios"}, {"letra": "b", "texto": "las huelgas"}], "k": "a", "x": "Art. 37.1 CE.", "f": "Art. 37.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a37-1-negociacion:N1"}, {"c": "CE-a37-1-negociacion", "n": 2, "e": "Según el art. 37.1 CE, la negociación colectiva laboral se produce entre:", "o": [{"letra": "a", "texto": "Los trabajadores individualmente y su empresa."}, {"letra": "b", "texto": "Los representantes de los trabajadores y empresarios."}, {"letra": "c", "texto": "Los sindicatos y el Gobierno."}], "k": "b", "x": "Art. 37.1 CE.", "f": "Art. 37.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a37-1-negociacion:N2"}, {"c": "CE-a37-1-negociacion", "n": 3, "e": "Según el art. 37.1 CE, ¿qué garantiza la ley además del derecho a la negociación colectiva laboral?", "o": [{"letra": "a", "texto": "La fuerza vinculante de los convenios."}, {"letra": "b", "texto": "El derecho a la huelga."}, {"letra": "c", "texto": "La participación de los trabajadores en la empresa."}], "k": "a", "x": "Art. 37.1 CE. La huelga está en el art. 28.2.", "f": "Art. 37.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a37-1-negociacion:N3"}]'::jsonb) AS x(c text, n int, e text, o jsonb, k text, x text, f text, h text);
UPDATE public.questions q SET enunciado = qq.e, opciones = qq.o, correcta = qq.k, explicacion = qq.x, fuente_normativa = qq.f, nivel = qq.n, concept_id = qq.c, estado = 'publicada', topic_id = (SELECT id FROM _tema) FROM _qq qq WHERE q.hash_dedupe = qq.h;
INSERT INTO public.questions (topic_id, enunciado, opciones, correcta, explicacion, fuente_normativa, estado, nivel, origen_tipo, origen_archivo, concept_id, hash_dedupe) SELECT (SELECT id FROM _tema), qq.e, qq.o, qq.k, qq.x, qq.f, 'publicada', qq.n, 'propio', 'data/constitucion/titulo-i.json', qq.c, qq.h FROM _qq qq WHERE NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.hash_dedupe = qq.h);
COMMIT;
-- BLOQUE
BEGIN;
CREATE TEMP TABLE _tema ON COMMIT DROP AS SELECT id FROM public.topics WHERE convocatoria_id = 1 AND numero = 1;
DO $$ BEGIN IF (SELECT count(*) FROM _tema) <> 1 THEN RAISE EXCEPTION 'tema 1 de la convocatoria 1 no encontrado o duplicado'; END IF; END $$;
WITH cc AS (SELECT * FROM jsonb_to_recordset('[{"id": "CE-a37-2-conflicto", "apartado": "Título I · Art. 37.2", "orden": 1100, "pregunta": "¿Qué derecho reconoce el art. 37.2 CE y a quién?", "respuesta": "El de trabajadores y empresarios a adoptar medidas de conflicto colectivo, con garantías para el funcionamiento de los servicios esenciales de la comunidad.", "fuente": "Constitución Española, art. 37.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Se reconoce el derecho de los trabajadores y empresarios a adoptar medidas de conflicto colectivo.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a28-2-huelga", "CE-a55-1-suspension"]}, {"id": "CE-a38-empresa", "apartado": "Título I · Art. 38", "orden": 1110, "pregunta": "¿Qué reconoce el art. 38 CE y en qué marco?", "respuesta": "La libertad de empresa en el marco de la economía de mercado; los poderes públicos garantizan y protegen su ejercicio y la defensa de la productividad.", "fuente": "Constitución Española, art. 38 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Se reconoce la libertad de empresa en el marco de la economía de mercado.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a33-1-propiedad"]}, {"id": "CE-a39-1-familia", "apartado": "Título I · Art. 39.1", "orden": 1120, "pregunta": "¿Qué protección de la familia aseguran los poderes públicos (art. 39.1 CE)?", "respuesta": "La protección social, económica y jurídica de la familia.", "fuente": "Constitución Española, art. 39.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Los poderes públicos aseguran la protección social, económica y jurídica de la familia.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a39-2-hijos"]}, {"id": "CE-a39-2-hijos", "apartado": "Título I · Art. 39.2", "orden": 1130, "pregunta": "¿A quién aseguran los poderes públicos protección integral según el art. 39.2 CE?", "respuesta": "A los hijos, iguales ante la ley con independencia de su filiación, y a las madres, cualquiera que sea su estado civil; la ley posibilitará la investigación de la paternidad.", "fuente": "Constitución Española, art. 39.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "La ley posibilitará la investigación de la paternidad.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a39-3-padres", "CE-a39-1-familia"]}, {"id": "CE-a39-3-padres", "apartado": "Título I · Art. 39.3", "orden": 1140, "pregunta": "¿Qué deben prestar los padres a sus hijos según el art. 39.3 CE?", "respuesta": "Asistencia de todo orden a los hijos habidos dentro o fuera del matrimonio, durante su minoría de edad y en los demás casos en que legalmente proceda.", "fuente": "Constitución Española, art. 39.3 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Los padres deben prestar asistencia de todo orden a los hijos habidos dentro o fuera del matrimonio", "tipo": "regla", "prioridad": 2, "conf": ["CE-a39-2-hijos", "CE-a27-3-formacion-religiosa"]}, {"id": "CE-a39-4-ninos", "apartado": "Título I · Art. 39.4", "orden": 1150, "pregunta": "¿De qué protección gozan los niños según el art. 39.4 CE?", "respuesta": "De la prevista en los acuerdos internacionales que velan por sus derechos.", "fuente": "Constitución Española, art. 39.4 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Los niños gozarán de la protección prevista en los acuerdos internacionales que velan por sus derechos.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a10-2-interpretacion"]}, {"id": "CE-a40-1-pleno-empleo", "apartado": "Título I · Art. 40.1", "orden": 1160, "pregunta": "¿Qué política realizarán de manera especial los poderes públicos según el art. 40.1 CE?", "respuesta": "Una política orientada al pleno empleo, dentro de las condiciones favorables para el progreso social y económico y una distribución de la renta más equitativa.", "fuente": "Constitución Española, art. 40.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "De manera especial realizarán una política orientada al pleno empleo.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a35-1-trabajo"]}, {"id": "CE-a40-2-seguridad-trabajo", "apartado": "Título I · Art. 40.2", "orden": 1170, "pregunta": "¿Qué tareas asigna el art. 40.2 CE a los poderes públicos en materia laboral?", "respuesta": "Fomentar la formación y readaptación profesionales, velar por la seguridad e higiene en el trabajo y garantizar el descanso necesario mediante la limitación de la jornada, las vacaciones periódicas retribuidas y la promoción de centros adecuados.", "fuente": "Constitución Española, art. 40.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "velarán por la seguridad e higiene en el trabajo", "tipo": "lista", "prioridad": 1, "conf": ["CE-a43-2-salud-publica"]}, {"id": "CE-a41-seguridad-social", "apartado": "Título I · Art. 41", "orden": 1180, "pregunta": "¿Qué régimen mantendrán los poderes públicos según el art. 41 CE?", "respuesta": "Un régimen público de Seguridad Social para todos los ciudadanos, con asistencia y prestaciones suficientes ante situaciones de necesidad, especialmente el desempleo; la asistencia y prestaciones complementarias serán libres.", "fuente": "Constitución Española, art. 41 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "La asistencia y prestaciones complementarias serán libres.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a50-tercera-edad"]}, {"id": "CE-a42-emigrantes", "apartado": "Título I · Art. 42", "orden": 1190, "pregunta": "¿Qué hará el Estado respecto de los trabajadores españoles en el extranjero (art. 42 CE)?", "respuesta": "Velará especialmente por la salvaguardia de sus derechos económicos y sociales y orientará su política hacia su retorno.", "fuente": "Constitución Española, art. 42 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "orientará su política hacia su retorno", "tipo": "regla", "prioridad": 3, "conf": []}, {"id": "CE-a43-1-salud", "apartado": "Título I · Art. 43.1", "orden": 1200, "pregunta": "¿Qué derecho reconoce el art. 43.1 CE?", "respuesta": "El derecho a la protección de la salud.", "fuente": "Constitución Española, art. 43.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Se reconoce el derecho a la protección de la salud.", "tipo": "dato", "prioridad": 1, "conf": ["CE-a15-vida-integridad"]}, {"id": "CE-a43-2-salud-publica", "apartado": "Título I · Art. 43.2", "orden": 1210, "pregunta": "¿Qué compete a los poderes públicos según el art. 43.2 CE?", "respuesta": "Organizar y tutelar la salud pública a través de medidas preventivas y de las prestaciones y servicios necesarios; la ley establecerá los derechos y deberes de todos al respecto.", "fuente": "Constitución Española, art. 43.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Compete a los poderes públicos organizar y tutelar la salud pública a través de medidas preventivas y de las prestaciones y servicios necesarios.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a40-2-seguridad-trabajo", "CE-a43-3-deporte"]}, {"id": "CE-a43-3-deporte", "apartado": "Título I · Art. 43.3", "orden": 1220, "pregunta": "¿Qué fomentarán los poderes públicos según el art. 43.3 CE?", "respuesta": "La educación sanitaria, la educación física y el deporte; además facilitarán la adecuada utilización del ocio.", "fuente": "Constitución Española, art. 43.3 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Los poderes públicos fomentarán la educación sanitaria, la educación física y el deporte.", "tipo": "lista", "prioridad": 2, "conf": ["CE-a43-2-salud-publica", "CE-a50-tercera-edad"]}, {"id": "CE-a44-1-cultura", "apartado": "Título I · Art. 44.1", "orden": 1230, "pregunta": "¿Qué promoverán y tutelarán los poderes públicos según el art. 44.1 CE?", "respuesta": "El acceso a la cultura, a la que todos tienen derecho.", "fuente": "Constitución Española, art. 44.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Los poderes públicos promoverán y tutelarán el acceso a la cultura, a la que todos tienen derecho.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a46-patrimonio", "CE-a44-2-ciencia"]}, {"id": "CE-a44-2-ciencia", "apartado": "Título I · Art. 44.2", "orden": 1240, "pregunta": "¿Qué promoverán los poderes públicos según el art. 44.2 CE?", "respuesta": "La ciencia y la investigación científica y técnica en beneficio del interés general.", "fuente": "Constitución Española, art. 44.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Los poderes públicos promoverán la ciencia y la investigación científica y técnica en beneficio del interés general.", "tipo": "regla", "prioridad": 3, "conf": ["CE-a44-1-cultura"]}, {"id": "CE-a45-1-medio-ambiente", "apartado": "Título I · Art. 45.1", "orden": 1250, "pregunta": "¿Qué derecho y qué deber recoge el art. 45.1 CE?", "respuesta": "El derecho de todos a disfrutar de un medio ambiente adecuado para el desarrollo de la persona y el deber de conservarlo.", "fuente": "Constitución Española, art. 45.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Todos tienen el derecho a disfrutar de un medio ambiente adecuado para el desarrollo de la persona, así como el deber de conservarlo.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a45-2-recursos"]}, {"id": "CE-a45-2-recursos", "apartado": "Título I · Art. 45.2", "orden": 1260, "pregunta": "¿Por qué velarán los poderes públicos según el art. 45.2 CE y con qué apoyo?", "respuesta": "Por la utilización racional de todos los recursos naturales, para proteger y mejorar la calidad de vida y defender y restaurar el medio ambiente, apoyándose en la indispensable solidaridad colectiva.", "fuente": "Constitución Española, art. 45.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "apoyándose en la indispensable solidaridad colectiva", "tipo": "regla", "prioridad": 2, "conf": ["CE-a45-1-medio-ambiente", "CE-a45-3-sanciones"]}, {"id": "CE-a45-3-sanciones", "apartado": "Título I · Art. 45.3", "orden": 1270, "pregunta": "¿Qué consecuencias prevé el art. 45.3 CE para quienes dañen el medio ambiente?", "respuesta": "Sanciones penales o, en su caso, administrativas en los términos que la ley fije, y la obligación de reparar el daño causado.", "fuente": "Constitución Española, art. 45.3 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "se establecerán sanciones penales o, en su caso, administrativas, así como la obligación de reparar el daño causado", "tipo": "regla", "prioridad": 2, "conf": ["CE-a46-patrimonio"]}, {"id": "CE-a46-patrimonio", "apartado": "Título I · Art. 46", "orden": 1280, "pregunta": "¿Qué garantizarán y promoverán los poderes públicos según el art. 46 CE?", "respuesta": "La conservación y el enriquecimiento del patrimonio histórico, cultural y artístico de los pueblos de España, cualquiera que sea su régimen jurídico y titularidad; la ley penal sancionará los atentados contra él.", "fuente": "Constitución Española, art. 46 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "La ley penal sancionará los atentados contra este patrimonio.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a44-1-cultura", "CE-a45-3-sanciones"]}, {"id": "CE-a47-vivienda", "apartado": "Título I · Art. 47", "orden": 1290, "pregunta": "¿Qué derecho reconoce el art. 47 CE y qué deben hacer los poderes públicos?", "respuesta": "El derecho a disfrutar de una vivienda digna y adecuada; los poderes públicos regularán la utilización del suelo de acuerdo con el interés general para impedir la especulación, y la comunidad participará en las plusvalías de la acción urbanística pública.", "fuente": "Constitución Española, art. 47 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Todos los españoles tienen derecho a disfrutar de una vivienda digna y adecuada.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a33-1-propiedad"]}]'::jsonb) AS x(id text, apartado text, orden int, pregunta text, respuesta text, fuente text, cita text, tipo text, prioridad smallint, conf text[])) INSERT INTO public.concepts (id, topic_id, documento, apartado, orden, pregunta, respuesta, fuente, cita, tipo, prioridad, confundible_con, estado) SELECT cc.id, t.id, 'CE', cc.apartado, cc.orden, cc.pregunta, cc.respuesta, cc.fuente, cc.cita, cc.tipo, cc.prioridad, coalesce(cc.conf, '{}'), 'publicado' FROM cc, _tema t ON CONFLICT (id) DO UPDATE SET topic_id = EXCLUDED.topic_id, documento = EXCLUDED.documento, apartado = EXCLUDED.apartado, orden = EXCLUDED.orden, pregunta = EXCLUDED.pregunta, respuesta = EXCLUDED.respuesta, fuente = EXCLUDED.fuente, cita = EXCLUDED.cita, tipo = EXCLUDED.tipo, prioridad = EXCLUDED.prioridad, confundible_con = EXCLUDED.confundible_con, estado = EXCLUDED.estado;
CREATE TEMP TABLE _qq ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"c": "CE-a37-2-conflicto", "n": 1, "e": "Según el art. 37.2 CE, ¿tienen los empresarios derecho a adoptar medidas de conflicto colectivo?", "o": [{"letra": "a", "texto": "Sí"}, {"letra": "b", "texto": "No, solo los trabajadores"}], "k": "a", "x": "Art. 37.2 CE: trabajadores y empresarios.", "f": "Art. 37.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a37-2-conflicto:N1"}, {"c": "CE-a37-2-conflicto", "n": 2, "e": "Según el art. 37.2 CE, la ley que regule las medidas de conflicto colectivo incluirá las garantías precisas para asegurar:", "o": [{"letra": "a", "texto": "El cumplimiento de los convenios colectivos."}, {"letra": "b", "texto": "La continuidad de la producción y el abastecimiento de las empresas."}, {"letra": "c", "texto": "El funcionamiento de los servicios esenciales de la comunidad."}], "k": "c", "x": "Art. 37.2 CE.", "f": "Art. 37.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a37-2-conflicto:N2"}, {"c": "CE-a37-2-conflicto", "n": 3, "e": "Según el art. 55.1 CE, el derecho a adoptar medidas de conflicto colectivo del art. 37.2:", "o": [{"letra": "a", "texto": "No puede suspenderse en ningún caso."}, {"letra": "b", "texto": "Puede suspenderse en los estados de excepción o de sitio."}, {"letra": "c", "texto": "Solo puede suspenderse en el estado de alarma."}], "k": "b", "x": "El art. 55.1 incluye expresamente el art. 37.2 entre los derechos suspendibles en los estados de excepción o de sitio.", "f": "Art. 37.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a37-2-conflicto:N3"}, {"c": "CE-a38-empresa", "n": 1, "e": "Según el art. 38 CE, se reconoce la libertad de empresa en el marco de…", "o": [{"letra": "a", "texto": "la economía de mercado"}, {"letra": "b", "texto": "la planificación central"}], "k": "a", "x": "Art. 38 CE.", "f": "Art. 38 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a38-empresa:N1"}, {"c": "CE-a38-empresa", "n": 2, "e": "Según el art. 38 CE, los poderes públicos garantizan y protegen el ejercicio de la libertad de empresa y la defensa de:", "o": [{"letra": "a", "texto": "La productividad."}, {"letra": "b", "texto": "Los consumidores y usuarios."}, {"letra": "c", "texto": "El pleno empleo."}], "k": "a", "x": "Art. 38 CE. El pleno empleo es del art. 40.1 y los consumidores, del art. 51.", "f": "Art. 38 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a38-empresa:N2"}, {"c": "CE-a38-empresa", "n": 3, "e": "Según el art. 38 CE, la defensa de la productividad se hará de acuerdo con:", "o": [{"letra": "a", "texto": "Las directrices de política económica de la Unión Europea."}, {"letra": "b", "texto": "Las exigencias de la economía general y, en su caso, de la planificación."}, {"letra": "c", "texto": "Los convenios colectivos vigentes en cada sector de actividad."}], "k": "b", "x": "Art. 38 CE.", "f": "Art. 38 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a38-empresa:N3"}, {"c": "CE-a39-1-familia", "n": 1, "e": "Según el art. 39.1 CE, los poderes públicos aseguran la protección social, económica y jurídica de…", "o": [{"letra": "a", "texto": "la juventud"}, {"letra": "b", "texto": "la familia"}], "k": "b", "x": "Art. 39.1 CE.", "f": "Art. 39.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a39-1-familia:N1"}, {"c": "CE-a39-1-familia", "n": 2, "e": "Según el art. 39.1 CE, la protección de la familia que aseguran los poderes públicos es:", "o": [{"letra": "a", "texto": "Social, económica y jurídica."}, {"letra": "b", "texto": "Integral."}, {"letra": "c", "texto": "Social, sanitaria y educativa."}], "k": "a", "x": "Art. 39.1 CE. «Integral» es la protección de los hijos y de las madres (art. 39.2).", "f": "Art. 39.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a39-1-familia:N2"}, {"c": "CE-a39-1-familia", "n": 3, "e": "El art. 39 CE, sobre la protección de la familia, es el primer artículo del:", "o": [{"letra": "a", "texto": "Capítulo cuarto del Título I (garantías)."}, {"letra": "b", "texto": "Capítulo tercero del Título I (principios rectores)."}, {"letra": "c", "texto": "Capítulo segundo del Título I, Sección 2.ª."}], "k": "b", "x": "El Capítulo tercero (arts. 39 a 52) recoge los principios rectores de la política social y económica.", "f": "Art. 39.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a39-1-familia:N3"}, {"c": "CE-a39-2-hijos", "n": 1, "e": "Según el art. 39.2 CE, la ley posibilitará la investigación de…", "o": [{"letra": "a", "texto": "la filiación adoptiva"}, {"letra": "b", "texto": "la paternidad"}], "k": "b", "x": "Art. 39.2 CE.", "f": "Art. 39.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a39-2-hijos:N1"}, {"c": "CE-a39-2-hijos", "n": 2, "e": "Según el art. 39.2 CE, los poderes públicos aseguran la protección integral de las madres:", "o": [{"letra": "a", "texto": "Cualquiera que sea su estado civil."}, {"letra": "b", "texto": "Casadas o con pareja inscrita."}, {"letra": "c", "texto": "Menores de edad."}], "k": "a", "x": "Art. 39.2 CE.", "f": "Art. 39.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a39-2-hijos:N2"}, {"c": "CE-a39-2-hijos", "n": 3, "e": "Según el art. 39.2 CE, los hijos son iguales ante la ley:", "o": [{"letra": "a", "texto": "Desde su inscripción en el Registro Civil."}, {"letra": "b", "texto": "Con independencia de su filiación."}, {"letra": "c", "texto": "Si han nacido dentro del matrimonio."}], "k": "b", "x": "Art. 39.2 CE: «iguales éstos ante la ley con independencia de su filiación».", "f": "Art. 39.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a39-2-hijos:N3"}, {"c": "CE-a39-3-padres", "n": 1, "e": "Según el art. 39.3 CE, ¿deben los padres asistir a los hijos nacidos fuera del matrimonio?", "o": [{"letra": "a", "texto": "Sí"}, {"letra": "b", "texto": "Solo si los han reconocido ante notario"}], "k": "a", "x": "Art. 39.3 CE: hijos habidos dentro o fuera del matrimonio.", "f": "Art. 39.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a39-3-padres:N1"}, {"c": "CE-a39-3-padres", "n": 2, "e": "Según el art. 39.3 CE, los padres deben prestar a los hijos asistencia:", "o": [{"letra": "a", "texto": "De todo orden."}, {"letra": "b", "texto": "Sanitaria y educativa."}, {"letra": "c", "texto": "Económica."}], "k": "a", "x": "Art. 39.3 CE: «asistencia de todo orden».", "f": "Art. 39.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a39-3-padres:N2"}, {"c": "CE-a39-3-padres", "n": 3, "e": "Según el art. 39.3 CE, la asistencia de los padres a los hijos se presta:", "o": [{"letra": "a", "texto": "Solo durante su minoría de edad, sin excepción."}, {"letra": "b", "texto": "Durante su minoría de edad y en los demás casos en que legalmente proceda."}, {"letra": "c", "texto": "Hasta que los hijos cumplan veinticinco años o se emancipen."}], "k": "b", "x": "Art. 39.3 CE.", "f": "Art. 39.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a39-3-padres:N3"}, {"c": "CE-a39-4-ninos", "n": 1, "e": "Según el art. 39.4 CE, los niños gozarán de la protección prevista en…", "o": [{"letra": "a", "texto": "el Código Civil"}, {"letra": "b", "texto": "los acuerdos internacionales que velan por sus derechos"}], "k": "b", "x": "Art. 39.4 CE.", "f": "Art. 39.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a39-4-ninos:N1"}, {"c": "CE-a39-4-ninos", "n": 2, "e": "¿Qué apartado del art. 39 CE remite a los acuerdos internacionales que velan por los derechos de los niños?", "o": [{"letra": "a", "texto": "El 2."}, {"letra": "b", "texto": "El 3."}, {"letra": "c", "texto": "El 4."}], "k": "c", "x": "Art. 39.4 CE.", "f": "Art. 39.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a39-4-ninos:N2"}, {"c": "CE-a39-4-ninos", "n": 3, "e": "El art. 39.4 CE dispone que los niños gozarán de la protección prevista en:", "o": [{"letra": "a", "texto": "Los acuerdos internacionales que velan por sus derechos."}, {"letra": "b", "texto": "La legislación de protección de menores de cada Comunidad Autónoma."}, {"letra": "c", "texto": "La legislación civil sobre filiación y patria potestad."}], "k": "a", "x": "Art. 39.4 CE. No remite al art. 10.2 ni a la legislación autonómica.", "f": "Art. 39.4 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a39-4-ninos:N3"}, {"c": "CE-a40-1-pleno-empleo", "n": 1, "e": "Según el art. 40.1 CE, los poderes públicos realizarán de manera especial una política orientada al…", "o": [{"letra": "a", "texto": "pleno empleo"}, {"letra": "b", "texto": "equilibrio presupuestario"}], "k": "a", "x": "Art. 40.1 CE.", "f": "Art. 40.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a40-1-pleno-empleo:N1"}, {"c": "CE-a40-1-pleno-empleo", "n": 2, "e": "Según el art. 40.1 CE, los poderes públicos promoverán una distribución de la renta regional y personal más equitativa en el marco de:", "o": [{"letra": "a", "texto": "Una política de estabilidad económica."}, {"letra": "b", "texto": "La planificación económica general."}, {"letra": "c", "texto": "La economía de mercado."}], "k": "a", "x": "Art. 40.1 CE: «en el marco de una política de estabilidad económica». La economía de mercado es el marco de la libertad de empresa (art. 38).", "f": "Art. 40.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a40-1-pleno-empleo:N2"}, {"c": "CE-a40-1-pleno-empleo", "n": 3, "e": "El derecho al trabajo y la política orientada al pleno empleo aparecen, respectivamente, en los arts.:", "o": [{"letra": "a", "texto": "35.1 y 41."}, {"letra": "b", "texto": "40.1 y 35.1."}, {"letra": "c", "texto": "35.1 y 40.1."}], "k": "c", "x": "Derecho al trabajo: art. 35.1 (Sección 2.ª). Política de pleno empleo: art. 40.1 (principio rector).", "f": "Art. 40.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a40-1-pleno-empleo:N3"}, {"c": "CE-a40-2-seguridad-trabajo", "n": 1, "e": "Según el art. 40.2 CE, los poderes públicos velarán por la seguridad e higiene en…", "o": [{"letra": "a", "texto": "los espacios públicos"}, {"letra": "b", "texto": "el trabajo"}], "k": "b", "x": "Art. 40.2 CE: fundamento constitucional de la prevención de riesgos laborales.", "f": "Art. 40.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a40-2-seguridad-trabajo:N1"}, {"c": "CE-a40-2-seguridad-trabajo", "n": 2, "e": "Según el art. 40.2 CE, los poderes públicos garantizarán el descanso necesario mediante:", "o": [{"letra": "a", "texto": "El salario mínimo y la negociación colectiva."}, {"letra": "b", "texto": "La limitación de la jornada laboral, las vacaciones periódicas retribuidas y la promoción de centros adecuados."}, {"letra": "c", "texto": "La reducción de la edad de jubilación, el trabajo a tiempo parcial y la conciliación familiar."}], "k": "b", "x": "Art. 40.2 CE.", "f": "Art. 40.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a40-2-seguridad-trabajo:N2"}, {"c": "CE-a40-2-seguridad-trabajo", "n": 3, "e": "El fundamento constitucional de la Ley de Prevención de Riesgos Laborales se encuentra en el art. 40.2 CE, que encomienda a los poderes públicos:", "o": [{"letra": "a", "texto": "Garantizar la defensa de los consumidores y usuarios."}, {"letra": "b", "texto": "Velar por la seguridad e higiene en el trabajo."}, {"letra": "c", "texto": "Organizar y tutelar la salud pública."}], "k": "b", "x": "Art. 40.2 CE. La salud pública es del art. 43.2 y los consumidores, del art. 51.1.", "f": "Art. 40.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a40-2-seguridad-trabajo:N3"}, {"c": "CE-a41-seguridad-social", "n": 1, "e": "Según el art. 41 CE, el régimen de Seguridad Social es…", "o": [{"letra": "a", "texto": "público y para todos los ciudadanos"}, {"letra": "b", "texto": "privado y voluntario"}], "k": "a", "x": "Art. 41 CE.", "f": "Art. 41 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a41-seguridad-social:N1"}, {"c": "CE-a41-seguridad-social", "n": 2, "e": "Según el art. 41 CE, el régimen público de Seguridad Social garantizará la asistencia y prestaciones sociales suficientes ante situaciones de necesidad, especialmente en caso de:", "o": [{"letra": "a", "texto": "Jubilación."}, {"letra": "b", "texto": "Desempleo."}, {"letra": "c", "texto": "Enfermedad."}], "k": "b", "x": "Art. 41 CE: «especialmente en caso de desempleo».", "f": "Art. 41 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a41-seguridad-social:N2"}, {"c": "CE-a41-seguridad-social", "n": 3, "e": "Según el art. 41 CE, la asistencia y prestaciones complementarias:", "o": [{"letra": "a", "texto": "Serán obligatorias para los trabajadores por cuenta ajena."}, {"letra": "b", "texto": "Serán libres."}, {"letra": "c", "texto": "Las gestionará en exclusiva la Seguridad Social."}], "k": "b", "x": "Art. 41 CE: «serán libres».", "f": "Art. 41 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a41-seguridad-social:N3"}, {"c": "CE-a42-emigrantes", "n": 1, "e": "Según el art. 42 CE, el Estado orientará su política respecto de los trabajadores españoles en el extranjero hacia su…", "o": [{"letra": "a", "texto": "retorno"}, {"letra": "b", "texto": "integración en el país de acogida"}], "k": "a", "x": "Art. 42 CE.", "f": "Art. 42 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a42-emigrantes:N1"}, {"c": "CE-a42-emigrantes", "n": 2, "e": "Según el art. 42 CE, el Estado velará especialmente por la salvaguardia de los derechos de los trabajadores españoles en el extranjero, en concreto de sus derechos:", "o": [{"letra": "a", "texto": "Civiles y familiares."}, {"letra": "b", "texto": "Políticos y electorales."}, {"letra": "c", "texto": "Económicos y sociales."}], "k": "c", "x": "Art. 42 CE.", "f": "Art. 42 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a42-emigrantes:N2"}, {"c": "CE-a42-emigrantes", "n": 3, "e": "El art. 42 CE asigna la salvaguardia de los derechos de los trabajadores españoles en el extranjero a:", "o": [{"letra": "a", "texto": "El Estado."}, {"letra": "b", "texto": "Las Comunidades Autónomas de origen."}, {"letra": "c", "texto": "Los poderes públicos en general."}], "k": "a", "x": "Art. 42 CE: «El Estado velará…»; a diferencia de la mayoría de principios rectores, que hablan de «los poderes públicos».", "f": "Art. 42 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a42-emigrantes:N3"}, {"c": "CE-a43-1-salud", "n": 1, "e": "¿Qué artículo de la Constitución reconoce el derecho a la protección de la salud?", "o": [{"letra": "a", "texto": "El 15"}, {"letra": "b", "texto": "El 43"}], "k": "b", "x": "Art. 43.1 CE. El 15 reconoce el derecho a la vida y a la integridad física y moral.", "f": "Art. 43.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a43-1-salud:N1"}, {"c": "CE-a43-1-salud", "n": 2, "e": "El derecho a la protección de la salud del art. 43 CE está ubicado entre:", "o": [{"letra": "a", "texto": "Los principios rectores de la política social y económica."}, {"letra": "b", "texto": "Los derechos fundamentales de la Sección 1.ª."}, {"letra": "c", "texto": "Los derechos y deberes de los ciudadanos de la Sección 2.ª."}], "k": "a", "x": "El art. 43 está en el Capítulo tercero (principios rectores). Por eso, según el art. 53.3, solo puede alegarse ante la jurisdicción ordinaria según las leyes que lo desarrollen.", "f": "Art. 43.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a43-1-salud:N2"}, {"c": "CE-a43-1-salud", "n": 3, "e": "Según el art. 43.1 CE, se reconoce el derecho:", "o": [{"letra": "a", "texto": "A la asistencia sanitaria gratuita."}, {"letra": "b", "texto": "A la salud."}, {"letra": "c", "texto": "A la protección de la salud."}], "k": "c", "x": "Art. 43.1 CE: «el derecho a la protección de la salud»; no habla de gratuidad ni de un derecho «a la salud» sin más.", "f": "Art. 43.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a43-1-salud:N3"}, {"c": "CE-a43-2-salud-publica", "n": 1, "e": "Según el art. 43.2 CE, compete a los poderes públicos organizar y tutelar…", "o": [{"letra": "a", "texto": "la sanidad privada"}, {"letra": "b", "texto": "la salud pública"}], "k": "b", "x": "Art. 43.2 CE.", "f": "Art. 43.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a43-2-salud-publica:N1"}, {"c": "CE-a43-2-salud-publica", "n": 2, "e": "Según el art. 43.2 CE, los poderes públicos organizan y tutelan la salud pública a través de:", "o": [{"letra": "a", "texto": "Medidas preventivas y de las prestaciones y servicios necesarios."}, {"letra": "b", "texto": "Los hospitales públicos y los centros concertados."}, {"letra": "c", "texto": "Un sistema nacional de salud gratuito, universal y de gestión pública."}], "k": "a", "x": "Art. 43.2 CE.", "f": "Art. 43.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a43-2-salud-publica:N2"}, {"c": "CE-a43-2-salud-publica", "n": 3, "e": "Según el art. 43.2 CE, los derechos y deberes de todos respecto de la salud pública:", "o": [{"letra": "a", "texto": "Los establecerá la ley."}, {"letra": "b", "texto": "Los regula cada Comunidad Autónoma por reglamento."}, {"letra": "c", "texto": "Los fija directamente la Constitución."}], "k": "a", "x": "Art. 43.2 CE: «La ley establecerá los derechos y deberes de todos al respecto».", "f": "Art. 43.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a43-2-salud-publica:N3"}, {"c": "CE-a43-3-deporte", "n": 1, "e": "Según el art. 43.3 CE, los poderes públicos fomentarán la educación sanitaria, la educación física y…", "o": [{"letra": "a", "texto": "el deporte"}, {"letra": "b", "texto": "la investigación médica"}], "k": "a", "x": "Art. 43.3 CE.", "f": "Art. 43.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a43-3-deporte:N1"}, {"c": "CE-a43-3-deporte", "n": 2, "e": "Según el art. 43.3 CE, los poderes públicos facilitarán:", "o": [{"letra": "a", "texto": "La práctica del deporte profesional."}, {"letra": "b", "texto": "El acceso gratuito a instalaciones deportivas."}, {"letra": "c", "texto": "La adecuada utilización del ocio."}], "k": "c", "x": "Art. 43.3 CE: «Asimismo facilitarán la adecuada utilización del ocio».", "f": "Art. 43.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a43-3-deporte:N2"}, {"c": "CE-a43-3-deporte", "n": 3, "e": "¿En qué artículo del Título I de la Constitución aparece el deporte?", "o": [{"letra": "a", "texto": "En el 27.2."}, {"letra": "b", "texto": "En el 44.1."}, {"letra": "c", "texto": "En el 43.3."}], "k": "c", "x": "Art. 43.3 CE: «la educación física y el deporte».", "f": "Art. 43.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a43-3-deporte:N3"}, {"c": "CE-a44-1-cultura", "n": 1, "e": "Según el art. 44.1 CE, ¿quiénes tienen derecho a la cultura?", "o": [{"letra": "a", "texto": "Solo los españoles"}, {"letra": "b", "texto": "Todos"}], "k": "b", "x": "Art. 44.1 CE: «a la que todos tienen derecho».", "f": "Art. 44.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a44-1-cultura:N1"}, {"c": "CE-a44-1-cultura", "n": 2, "e": "Según el art. 44.1 CE, los poderes públicos promoverán y tutelarán:", "o": [{"letra": "a", "texto": "El acceso a la cultura."}, {"letra": "b", "texto": "La conservación del patrimonio histórico."}, {"letra": "c", "texto": "La libertad de creación artística."}], "k": "a", "x": "Art. 44.1 CE. El patrimonio está en el art. 46 y la creación artística, en el art. 20.1.b).", "f": "Art. 44.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a44-1-cultura:N2"}, {"c": "CE-a44-1-cultura", "n": 3, "e": "Según el art. 44.1 CE, respecto del acceso a la cultura, los poderes públicos:", "o": [{"letra": "a", "texto": "Promoverán y tutelarán."}, {"letra": "b", "texto": "Fomentarán y protegerán."}, {"letra": "c", "texto": "Garantizarán y financiarán."}], "k": "a", "x": "Art. 44.1 CE: «promoverán y tutelarán».", "f": "Art. 44.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a44-1-cultura:N3"}, {"c": "CE-a44-2-ciencia", "n": 1, "e": "Según el art. 44.2 CE, los poderes públicos promoverán la ciencia y la investigación científica y técnica en beneficio del…", "o": [{"letra": "a", "texto": "sector privado"}, {"letra": "b", "texto": "interés general"}], "k": "b", "x": "Art. 44.2 CE.", "f": "Art. 44.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a44-2-ciencia:N1"}, {"c": "CE-a44-2-ciencia", "n": 2, "e": "¿Qué apartado de la Constitución dispone que los poderes públicos promoverán la ciencia y la investigación científica y técnica?", "o": [{"letra": "a", "texto": "El art. 44.2."}, {"letra": "b", "texto": "El art. 27.10."}, {"letra": "c", "texto": "El art. 20.1.b)."}], "k": "a", "x": "Art. 44.2 CE. El 20.1.b) reconoce el derecho a la producción y creación científica y técnica; el 27.10, la autonomía universitaria.", "f": "Art. 44.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a44-2-ciencia:N2"}, {"c": "CE-a44-2-ciencia", "n": 3, "e": "Según el art. 44.2 CE, la promoción de la investigación científica y técnica se hace:", "o": [{"letra": "a", "texto": "Con fondos de la Unión Europea."}, {"letra": "b", "texto": "En el marco de la autonomía universitaria."}, {"letra": "c", "texto": "En beneficio del interés general."}], "k": "c", "x": "Art. 44.2 CE.", "f": "Art. 44.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a44-2-ciencia:N3"}, {"c": "CE-a45-1-medio-ambiente", "n": 1, "e": "Según el art. 45.1 CE, conservar el medio ambiente es…", "o": [{"letra": "a", "texto": "un deber de todos"}, {"letra": "b", "texto": "solo una tarea de los poderes públicos"}], "k": "a", "x": "Art. 45.1 CE: derecho a disfrutarlo y deber de conservarlo.", "f": "Art. 45.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a45-1-medio-ambiente:N1"}, {"c": "CE-a45-1-medio-ambiente", "n": 2, "e": "Según el art. 45.1 CE, todos tienen el derecho a disfrutar de un medio ambiente:", "o": [{"letra": "a", "texto": "Libre de contaminación."}, {"letra": "b", "texto": "Adecuado para el desarrollo de la persona."}, {"letra": "c", "texto": "Sano y ecológicamente equilibrado."}], "k": "b", "x": "Art. 45.1 CE: «adecuado para el desarrollo de la persona».", "f": "Art. 45.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a45-1-medio-ambiente:N2"}, {"c": "CE-a45-1-medio-ambiente", "n": 3, "e": "El art. 45.1 CE configura el medio ambiente como:", "o": [{"letra": "a", "texto": "Un derecho a disfrutarlo y un deber de conservarlo para todos."}, {"letra": "b", "texto": "Una competencia exclusiva del Estado."}, {"letra": "c", "texto": "Un derecho fundamental de la Sección 1.ª protegido por el recurso de amparo."}], "k": "a", "x": "Art. 45.1 CE. Está en el Capítulo tercero, sin recurso de amparo (art. 53).", "f": "Art. 45.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a45-1-medio-ambiente:N3"}, {"c": "CE-a45-2-recursos", "n": 1, "e": "Según el art. 45.2 CE, los poderes públicos velarán por la utilización racional de…", "o": [{"letra": "a", "texto": "todos los recursos naturales"}, {"letra": "b", "texto": "los recursos energéticos"}], "k": "a", "x": "Art. 45.2 CE.", "f": "Art. 45.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a45-2-recursos:N1"}, {"c": "CE-a45-2-recursos", "n": 2, "e": "Según el art. 45.2 CE, los poderes públicos velarán por la utilización racional de los recursos naturales apoyándose en:", "o": [{"letra": "a", "texto": "La iniciativa privada."}, {"letra": "b", "texto": "La indispensable solidaridad colectiva."}, {"letra": "c", "texto": "La cooperación internacional en materia ambiental."}], "k": "b", "x": "Art. 45.2 CE.", "f": "Art. 45.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a45-2-recursos:N2"}, {"c": "CE-a45-2-recursos", "n": 3, "e": "Según el art. 45.2 CE, la utilización racional de los recursos naturales tiene como fin:", "o": [{"letra": "a", "texto": "Asegurar la autosuficiencia de recursos y el desarrollo del medio rural."}, {"letra": "b", "texto": "Proteger y mejorar la calidad de la vida y defender y restaurar el medio ambiente."}, {"letra": "c", "texto": "Garantizar un crecimiento económico sostenible y compatible con el empleo."}], "k": "b", "x": "Art. 45.2 CE.", "f": "Art. 45.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a45-2-recursos:N3"}, {"c": "CE-a45-3-sanciones", "n": 1, "e": "Según el art. 45.3 CE, además de las sanciones, quienes violen lo dispuesto en el apartado anterior tienen la obligación de…", "o": [{"letra": "a", "texto": "reparar el daño causado"}, {"letra": "b", "texto": "indemnizar al Estado con el doble del daño"}], "k": "a", "x": "Art. 45.3 CE.", "f": "Art. 45.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a45-3-sanciones:N1"}, {"c": "CE-a45-3-sanciones", "n": 2, "e": "Según el art. 45.3 CE, para quienes violen lo dispuesto en el apartado anterior se establecerán, en los términos que la ley fije, sanciones:", "o": [{"letra": "a", "texto": "Penales o, en su caso, administrativas."}, {"letra": "b", "texto": "Administrativas, con exclusión de las penales."}, {"letra": "c", "texto": "Penales, con exclusión de las administrativas."}], "k": "a", "x": "Art. 45.3 CE: «sanciones penales o, en su caso, administrativas, así como la obligación de reparar el daño causado».", "f": "Art. 45.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a45-3-sanciones:N2"}, {"c": "CE-a45-3-sanciones", "n": 3, "e": "En materia de medio ambiente (art. 45.3) y de patrimonio histórico (art. 46), la Constitución prevé, respectivamente:", "o": [{"letra": "a", "texto": "Sanciones penales o administrativas y reparación; y sanción penal de los atentados."}, {"letra": "b", "texto": "Reparación del daño en ambos casos, sin que se prevean sanciones penales."}, {"letra": "c", "texto": "Solo sanciones administrativas en ambos casos, sin reparación."}], "k": "a", "x": "Art. 45.3: sanciones penales o administrativas y reparación. Art. 46: «La ley penal sancionará los atentados contra este patrimonio».", "f": "Art. 45.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a45-3-sanciones:N3"}, {"c": "CE-a46-patrimonio", "n": 1, "e": "Según el art. 46 CE, los atentados contra el patrimonio histórico, cultural y artístico los sancionará…", "o": [{"letra": "a", "texto": "la ley penal"}, {"letra": "b", "texto": "la Administración cultural"}], "k": "a", "x": "Art. 46 CE.", "f": "Art. 46 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a46-patrimonio:N1"}, {"c": "CE-a46-patrimonio", "n": 2, "e": "Según el art. 46 CE, los poderes públicos garantizarán la conservación y promoverán el enriquecimiento del patrimonio histórico, cultural y artístico:", "o": [{"letra": "a", "texto": "Cualquiera que sea su régimen jurídico y su titularidad."}, {"letra": "b", "texto": "Solo el de titularidad pública o declarado Bien de Interés Cultural."}, {"letra": "c", "texto": "Declarado Bien de Interés Cultural."}], "k": "a", "x": "Art. 46 CE.", "f": "Art. 46 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a46-patrimonio:N2"}, {"c": "CE-a46-patrimonio", "n": 3, "e": "Según el art. 46 CE, respecto del patrimonio histórico, cultural y artístico, los poderes públicos:", "o": [{"letra": "a", "texto": "Promoverán su conservación y garantizarán su enriquecimiento."}, {"letra": "b", "texto": "Tutelarán su acceso y fomentarán su difusión."}, {"letra": "c", "texto": "Garantizarán su conservación y promoverán su enriquecimiento."}], "k": "c", "x": "Art. 46 CE: «garantizarán la conservación y promoverán el enriquecimiento».", "f": "Art. 46 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a46-patrimonio:N3"}, {"c": "CE-a47-vivienda", "n": 1, "e": "Según el art. 47 CE, los españoles tienen derecho a disfrutar de una vivienda…", "o": [{"letra": "a", "texto": "en propiedad"}, {"letra": "b", "texto": "digna y adecuada"}], "k": "b", "x": "Art. 47 CE.", "f": "Art. 47 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a47-vivienda:N1"}, {"c": "CE-a47-vivienda", "n": 2, "e": "Según el art. 47 CE, los poderes públicos regularán la utilización del suelo de acuerdo con el interés general para impedir:", "o": [{"letra": "a", "texto": "La construcción ilegal."}, {"letra": "b", "texto": "La especulación."}, {"letra": "c", "texto": "La despoblación rural."}], "k": "b", "x": "Art. 47 CE.", "f": "Art. 47 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a47-vivienda:N2"}, {"c": "CE-a47-vivienda", "n": 3, "e": "Según el art. 47 CE, ¿quién participará en las plusvalías que genere la acción urbanística de los entes públicos?", "o": [{"letra": "a", "texto": "Los propietarios del suelo."}, {"letra": "b", "texto": "Los ayuntamientos, en exclusiva."}, {"letra": "c", "texto": "La comunidad."}], "k": "c", "x": "Art. 47 CE: «La comunidad participará en las plusvalías…».", "f": "Art. 47 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a47-vivienda:N3"}]'::jsonb) AS x(c text, n int, e text, o jsonb, k text, x text, f text, h text);
UPDATE public.questions q SET enunciado = qq.e, opciones = qq.o, correcta = qq.k, explicacion = qq.x, fuente_normativa = qq.f, nivel = qq.n, concept_id = qq.c, estado = 'publicada', topic_id = (SELECT id FROM _tema) FROM _qq qq WHERE q.hash_dedupe = qq.h;
INSERT INTO public.questions (topic_id, enunciado, opciones, correcta, explicacion, fuente_normativa, estado, nivel, origen_tipo, origen_archivo, concept_id, hash_dedupe) SELECT (SELECT id FROM _tema), qq.e, qq.o, qq.k, qq.x, qq.f, 'publicada', qq.n, 'propio', 'data/constitucion/titulo-i.json', qq.c, qq.h FROM _qq qq WHERE NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.hash_dedupe = qq.h);
COMMIT;
-- BLOQUE
BEGIN;
CREATE TEMP TABLE _tema ON COMMIT DROP AS SELECT id FROM public.topics WHERE convocatoria_id = 1 AND numero = 1;
DO $$ BEGIN IF (SELECT count(*) FROM _tema) <> 1 THEN RAISE EXCEPTION 'tema 1 de la convocatoria 1 no encontrado o duplicado'; END IF; END $$;
WITH cc AS (SELECT * FROM jsonb_to_recordset('[{"id": "CE-a48-juventud", "apartado": "Título I · Art. 48", "orden": 1300, "pregunta": "¿Qué participación de la juventud promoverán los poderes públicos (art. 48 CE)?", "respuesta": "La participación libre y eficaz de la juventud en el desarrollo político, social, económico y cultural.", "fuente": "Constitución Española, art. 48 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Los poderes públicos promoverán las condiciones para la participación libre y eficaz de la juventud en el desarrollo político, social, económico y cultural.", "tipo": "regla", "prioridad": 3, "conf": ["CE-a9-2-igualdad-real"]}, {"id": "CE-a49-1-discapacidad", "apartado": "Título I · Art. 49.1", "orden": 1310, "pregunta": "¿Qué dice el art. 49.1 CE, tras la reforma de 2024, sobre las personas con discapacidad?", "respuesta": "Que ejercen los derechos del Título I en condiciones de libertad e igualdad reales y efectivas; la ley regulará la protección especial necesaria para dicho ejercicio.", "fuente": "Constitución Española, art. 49.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Las personas con discapacidad ejercen los derechos previstos en este Título en condiciones de libertad e igualdad reales y efectivas.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a49-2-politicas", "CE-a9-2-igualdad-real"]}, {"id": "CE-a49-2-politicas", "apartado": "Título I · Art. 49.2", "orden": 1320, "pregunta": "¿Qué políticas impulsarán los poderes públicos según el art. 49.2 CE?", "respuesta": "Las que garanticen la plena autonomía personal y la inclusión social de las personas con discapacidad en entornos universalmente accesibles; fomentarán la participación de sus organizaciones y atenderán en particular a mujeres y menores con discapacidad.", "fuente": "Constitución Española, art. 49.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Se atenderán particularmente las necesidades específicas de las mujeres y los menores con discapacidad.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a49-1-discapacidad"]}, {"id": "CE-a50-tercera-edad", "apartado": "Título I · Art. 50", "orden": 1330, "pregunta": "¿Cómo garantizan los poderes públicos la suficiencia económica en la tercera edad y qué problemas atenderán los servicios sociales (art. 50 CE)?", "respuesta": "Mediante pensiones adecuadas y periódicamente actualizadas; los servicios sociales atenderán sus problemas específicos de salud, vivienda, cultura y ocio.", "fuente": "Constitución Española, art. 50 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "mediante pensiones adecuadas y periódicamente actualizadas, la suficiencia económica a los ciudadanos durante la tercera edad", "tipo": "lista", "prioridad": 2, "conf": ["CE-a41-seguridad-social"]}, {"id": "CE-a51-1-consumidores", "apartado": "Título I · Art. 51.1", "orden": 1340, "pregunta": "¿Qué protegerán los poderes públicos al garantizar la defensa de consumidores y usuarios (art. 51.1 CE)?", "respuesta": "Mediante procedimientos eficaces, su seguridad, su salud y sus legítimos intereses económicos.", "fuente": "Constitución Española, art. 51.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "protegiendo, mediante procedimientos eficaces, la seguridad, la salud y los legítimos intereses económicos de los mismos", "tipo": "lista", "prioridad": 2, "conf": ["CE-a51-2-informacion", "CE-a38-empresa"]}, {"id": "CE-a51-2-informacion", "apartado": "Título I · Art. 51.2", "orden": 1350, "pregunta": "¿Qué harán los poderes públicos respecto de los consumidores según el art. 51.2 CE?", "respuesta": "Promoverán su información y educación, fomentarán sus organizaciones y oirán a éstas en las cuestiones que puedan afectarles.", "fuente": "Constitución Española, art. 51.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Los poderes públicos promoverán la información y la educación de los consumidores y usuarios, fomentarán sus organizaciones y oirán a éstas en las cuestiones que puedan afectar a aquéllos", "tipo": "lista", "prioridad": 3, "conf": ["CE-a51-1-consumidores"]}, {"id": "CE-a51-3-comercio", "apartado": "Título I · Art. 51.3", "orden": 1360, "pregunta": "¿Qué regulará la ley según el art. 51.3 CE?", "respuesta": "El comercio interior y el régimen de autorización de productos comerciales.", "fuente": "Constitución Española, art. 51.3 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "la ley regulará el comercio interior y el régimen de autorización de productos comerciales", "tipo": "regla", "prioridad": 3, "conf": ["CE-a51-1-consumidores"]}, {"id": "CE-a52-organizaciones", "apartado": "Título I · Art. 52", "orden": 1370, "pregunta": "¿Qué organizaciones regulará la ley según el art. 52 CE y cómo deben funcionar?", "respuesta": "Las organizaciones profesionales que contribuyan a la defensa de sus intereses económicos propios; su estructura interna y funcionamiento deberán ser democráticos.", "fuente": "Constitución Española, art. 52 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "La ley regulará las organizaciones profesionales que contribuyan a la defensa de los intereses económicos que les sean propios.", "tipo": "regla", "prioridad": 3, "conf": ["CE-a36-colegios", "CE-a7-sindicatos-funciones"]}, {"id": "CE-a53-1-vinculacion", "apartado": "Título I · Art. 53.1", "orden": 1380, "pregunta": "¿Qué garantías da el art. 53.1 CE a los derechos del Capítulo segundo?", "respuesta": "Vinculan a todos los poderes públicos; su ejercicio solo puede regularse por ley, que deberá respetar su contenido esencial; y se tutelan por el recurso de inconstitucionalidad (art. 161.1.a).", "fuente": "Constitución Española, art. 53.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Sólo por ley, que en todo caso deberá respetar su contenido esencial, podrá regularse el ejercicio de tales derechos y libertades", "tipo": "regla", "prioridad": 1, "conf": ["CE-a53-2-amparo", "CE-a53-3-principios"]}, {"id": "CE-a53-2-amparo", "apartado": "Título I · Art. 53.2", "orden": 1390, "pregunta": "¿Qué derechos tienen procedimiento preferente y sumario y recurso de amparo (art. 53.2 CE)?", "respuesta": "Los del art. 14 y de la Sección primera del Capítulo segundo (arts. 15 a 29), más la objeción de conciencia del art. 30 en el caso del amparo.", "fuente": "Constitución Española, art. 53.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Cualquier ciudadano podrá recabar la tutela de las libertades y derechos reconocidos en el artículo 14 y la Sección primera del Capítulo segundo ante los Tribunales ordinarios por un procedimiento basado en los principios de preferencia y sumariedad", "tipo": "regla", "prioridad": 1, "conf": ["CE-a53-1-vinculacion", "CE-a30-2-objecion"]}, {"id": "CE-a53-3-principios", "apartado": "Título I · Art. 53.3", "orden": 1400, "pregunta": "¿Qué eficacia tienen los principios rectores del Capítulo tercero (art. 53.3 CE)?", "respuesta": "Informan la legislación positiva, la práctica judicial y la actuación de los poderes públicos; solo pueden alegarse ante la Jurisdicción ordinaria según las leyes que los desarrollen.", "fuente": "Constitución Española, art. 53.3 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Sólo podrán ser alegados ante la Jurisdicción ordinaria de acuerdo con lo que dispongan las leyes que los desarrollen.", "tipo": "regla", "prioridad": 1, "conf": ["CE-a53-1-vinculacion"]}, {"id": "CE-a54-defensor", "apartado": "Título I · Art. 54", "orden": 1410, "pregunta": "¿Qué es el Defensor del Pueblo según el art. 54 CE y qué norma lo regula?", "respuesta": "Alto comisionado de las Cortes Generales, designado por éstas para defender los derechos del Título I; puede supervisar la actividad de la Administración dando cuenta a las Cortes. Lo regula una ley orgánica.", "fuente": "Constitución Española, art. 54 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Una ley orgánica regulará la institución del Defensor del Pueblo, como alto comisionado de las Cortes Generales, designado por éstas para la defensa de los derechos comprendidos en este Título", "tipo": "definicion", "prioridad": 1, "conf": ["CE-a53-2-amparo"]}, {"id": "CE-a55-1-suspension", "apartado": "Título I · Art. 55.1", "orden": 1420, "pregunta": "¿Qué derechos pueden suspenderse en los estados de excepción o de sitio (art. 55.1 CE)?", "respuesta": "Arts. 17, 18.2 y 18.3, 19, 20.1.a) y d) y 20.5, 21, 28.2 y 37.2.", "fuente": "Constitución Española, art. 55.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "podrán ser suspendidos cuando se acuerde la declaración del estado de excepción o de sitio en los términos previstos en la Constitución", "tipo": "lista", "prioridad": 1, "conf": ["CE-a55-1-excepcion-17-3", "CE-a55-2-terrorismo"]}, {"id": "CE-a55-1-excepcion-17-3", "apartado": "Título I · Art. 55.1", "orden": 1430, "pregunta": "¿Qué derecho del art. 17 no puede suspenderse en el estado de excepción (art. 55.1 CE)?", "respuesta": "El del apartado 3 del art. 17 (derechos del detenido: información, no declarar, asistencia de abogado).", "fuente": "Constitución Española, art. 55.1 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "Se exceptúa de lo establecido anteriormente el apartado 3 del artículo 17 para el supuesto de declaración de estado de excepción.", "tipo": "regla", "prioridad": 2, "conf": ["CE-a55-1-suspension", "CE-a17-3-detenido"]}, {"id": "CE-a55-2-terrorismo", "apartado": "Título I · Art. 55.2", "orden": 1440, "pregunta": "¿Qué derechos puede suspender individualmente una ley orgánica según el art. 55.2 CE y en qué casos?", "respuesta": "Los de los arts. 17.2, 18.2 y 18.3, para personas determinadas, en relación con investigaciones sobre bandas armadas o elementos terroristas, con intervención judicial y control parlamentario.", "fuente": "Constitución Española, art. 55.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "en relación con las investigaciones correspondientes a la actuación de bandas armadas o elementos terroristas", "tipo": "regla", "prioridad": 1, "conf": ["CE-a55-1-suspension", "CE-a13-3-extradicion"]}, {"id": "CE-a55-2-responsabilidad", "apartado": "Título I · Art. 55.2", "orden": 1450, "pregunta": "¿Qué consecuencia tiene el uso injustificado o abusivo de las facultades de la ley orgánica del art. 55.2 CE?", "respuesta": "Producirá responsabilidad penal, como violación de los derechos y libertades reconocidos por las leyes.", "fuente": "Constitución Española, art. 55.2 (BOE-A-1978-31229, texto consolidado, act. 20/05/2026)", "cita": "La utilización injustificada o abusiva de las facultades reconocidas en dicha ley orgánica producirá responsabilidad penal", "tipo": "regla", "prioridad": 2, "conf": ["CE-a55-2-terrorismo"]}]'::jsonb) AS x(id text, apartado text, orden int, pregunta text, respuesta text, fuente text, cita text, tipo text, prioridad smallint, conf text[])) INSERT INTO public.concepts (id, topic_id, documento, apartado, orden, pregunta, respuesta, fuente, cita, tipo, prioridad, confundible_con, estado) SELECT cc.id, t.id, 'CE', cc.apartado, cc.orden, cc.pregunta, cc.respuesta, cc.fuente, cc.cita, cc.tipo, cc.prioridad, coalesce(cc.conf, '{}'), 'publicado' FROM cc, _tema t ON CONFLICT (id) DO UPDATE SET topic_id = EXCLUDED.topic_id, documento = EXCLUDED.documento, apartado = EXCLUDED.apartado, orden = EXCLUDED.orden, pregunta = EXCLUDED.pregunta, respuesta = EXCLUDED.respuesta, fuente = EXCLUDED.fuente, cita = EXCLUDED.cita, tipo = EXCLUDED.tipo, prioridad = EXCLUDED.prioridad, confundible_con = EXCLUDED.confundible_con, estado = EXCLUDED.estado;
CREATE TEMP TABLE _qq ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"c": "CE-a48-juventud", "n": 1, "e": "Según el art. 48 CE, los poderes públicos promoverán la participación libre y eficaz de…", "o": [{"letra": "a", "texto": "la juventud"}, {"letra": "b", "texto": "la tercera edad"}], "k": "a", "x": "Art. 48 CE.", "f": "Art. 48 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a48-juventud:N1"}, {"c": "CE-a48-juventud", "n": 2, "e": "Según el art. 48 CE, la participación de la juventud que promueven los poderes públicos es en el desarrollo:", "o": [{"letra": "a", "texto": "Deportivo y cultural."}, {"letra": "b", "texto": "Político, social, económico y cultural."}, {"letra": "c", "texto": "Educativo, profesional y deportivo."}], "k": "b", "x": "Art. 48 CE.", "f": "Art. 48 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a48-juventud:N2"}, {"c": "CE-a48-juventud", "n": 3, "e": "Según el art. 48 CE, la participación de la juventud que promueven los poderes públicos debe ser:", "o": [{"letra": "a", "texto": "Libre y eficaz."}, {"letra": "b", "texto": "Real y efectiva."}, {"letra": "c", "texto": "Directa y representativa."}], "k": "a", "x": "Art. 48 CE: «participación libre y eficaz». «Reales y efectivas» es la expresión del art. 9.2.", "f": "Art. 48 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a48-juventud:N3"}, {"c": "CE-a49-1-discapacidad", "n": 1, "e": "Según el art. 49.1 CE, las personas con discapacidad ejercen los derechos del Título I en condiciones de libertad e igualdad…", "o": [{"letra": "a", "texto": "formales"}, {"letra": "b", "texto": "reales y efectivas"}], "k": "b", "x": "Art. 49.1 CE, redacción de la reforma de 15 de febrero de 2024.", "f": "Art. 49.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a49-1-discapacidad:N1"}, {"c": "CE-a49-1-discapacidad", "n": 2, "e": "El art. 49 CE se reformó en:", "o": [{"letra": "a", "texto": "2024."}, {"letra": "b", "texto": "1992."}, {"letra": "c", "texto": "2011."}], "k": "a", "x": "Reforma de 15 de febrero de 2024. En 1992 se reformó el art. 13.2 y en 2011, el art. 135.", "f": "Art. 49.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a49-1-discapacidad:N2"}, {"c": "CE-a49-1-discapacidad", "n": 3, "e": "Según el art. 49.1 CE vigente, la protección especial necesaria para que las personas con discapacidad ejerzan sus derechos:", "o": [{"letra": "a", "texto": "La fija directamente la Constitución."}, {"letra": "b", "texto": "La regulan los poderes públicos mediante reglamento."}, {"letra": "c", "texto": "Se regulará por ley."}], "k": "c", "x": "Art. 49.1 CE: «Se regulará por ley la protección especial que sea necesaria para dicho ejercicio».", "f": "Art. 49.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a49-1-discapacidad:N3"}, {"c": "CE-a49-2-politicas", "n": 1, "e": "Según el art. 49.2 CE, las políticas para las personas con discapacidad se desarrollarán en entornos…", "o": [{"letra": "a", "texto": "universalmente accesibles"}, {"letra": "b", "texto": "especialmente protegidos"}], "k": "a", "x": "Art. 49.2 CE.", "f": "Art. 49.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a49-2-politicas:N1"}, {"c": "CE-a49-2-politicas", "n": 2, "e": "Según el art. 49.2 CE, se atenderán particularmente las necesidades específicas de:", "o": [{"letra": "a", "texto": "Las personas mayores con discapacidad."}, {"letra": "b", "texto": "Las personas con discapacidad en el medio rural."}, {"letra": "c", "texto": "Las mujeres y los menores con discapacidad."}], "k": "c", "x": "Art. 49.2 CE.", "f": "Art. 49.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a49-2-politicas:N2"}, {"c": "CE-a49-2-politicas", "n": 3, "e": "Según el art. 49.2 CE, las políticas que impulsen los poderes públicos deben garantizar:", "o": [{"letra": "a", "texto": "La atención especializada y el amparo especial de las personas con discapacidad."}, {"letra": "b", "texto": "La previsión, tratamiento, rehabilitación e integración de las personas con discapacidad."}, {"letra": "c", "texto": "La plena autonomía personal y la inclusión social de las personas con discapacidad."}], "k": "c", "x": "Art. 49.2 CE vigente. «Previsión, tratamiento, rehabilitación e integración» es la redacción anterior a la reforma de 2024.", "f": "Art. 49.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a49-2-politicas:N3"}, {"c": "CE-a50-tercera-edad", "n": 1, "e": "Según el art. 50 CE, las pensiones de la tercera edad serán adecuadas y…", "o": [{"letra": "a", "texto": "fijas e iguales para todos"}, {"letra": "b", "texto": "periódicamente actualizadas"}], "k": "b", "x": "Art. 50 CE.", "f": "Art. 50 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a50-tercera-edad:N1"}, {"c": "CE-a50-tercera-edad", "n": 2, "e": "Según el art. 50 CE, los servicios sociales para la tercera edad atenderán sus problemas específicos de:", "o": [{"letra": "a", "texto": "Salud, vivienda, cultura y ocio."}, {"letra": "b", "texto": "Vivienda, transporte y alimentación."}, {"letra": "c", "texto": "Salud, dependencia y soledad."}], "k": "a", "x": "Art. 50 CE.", "f": "Art. 50 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a50-tercera-edad:N2"}, {"c": "CE-a50-tercera-edad", "n": 3, "e": "Según el art. 50 CE, los poderes públicos promoverán el bienestar de la tercera edad mediante un sistema de servicios sociales:", "o": [{"letra": "a", "texto": "Gestionado por la Seguridad Social."}, {"letra": "b", "texto": "Con independencia de las obligaciones familiares."}, {"letra": "c", "texto": "Subsidiario de las obligaciones familiares."}], "k": "b", "x": "Art. 50 CE: «Asimismo, y con independencia de las obligaciones familiares, promoverán su bienestar…».", "f": "Art. 50 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a50-tercera-edad:N3"}, {"c": "CE-a51-1-consumidores", "n": 1, "e": "Según el art. 51.1 CE, los poderes públicos garantizarán la defensa de los consumidores y…", "o": [{"letra": "a", "texto": "empresarios"}, {"letra": "b", "texto": "usuarios"}], "k": "b", "x": "Art. 51.1 CE.", "f": "Art. 51.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a51-1-consumidores:N1"}, {"c": "CE-a51-1-consumidores", "n": 2, "e": "Según el art. 51.1 CE, al defender a los consumidores y usuarios, los poderes públicos protegerán, mediante procedimientos eficaces, su:", "o": [{"letra": "a", "texto": "Seguridad, salud y legítimos intereses económicos."}, {"letra": "b", "texto": "Libertad de elección y la calidad de los productos."}, {"letra": "c", "texto": "Información, educación y derecho de asociación."}], "k": "a", "x": "Art. 51.1 CE. Información, educación y organizaciones son del art. 51.2.", "f": "Art. 51.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a51-1-consumidores:N2"}, {"c": "CE-a51-1-consumidores", "n": 3, "e": "Según el art. 51.1 CE, la protección de los consumidores y usuarios se hará:", "o": [{"letra": "a", "texto": "Mediante procedimientos eficaces."}, {"letra": "b", "texto": "Mediante tribunales especiales de consumo."}, {"letra": "c", "texto": "Mediante el arbitraje obligatorio."}], "k": "a", "x": "Art. 51.1 CE.", "f": "Art. 51.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a51-1-consumidores:N3"}, {"c": "CE-a51-2-informacion", "n": 1, "e": "Según el art. 51.2 CE, ¿oirán los poderes públicos a las organizaciones de consumidores?", "o": [{"letra": "a", "texto": "No"}, {"letra": "b", "texto": "Sí, en las cuestiones que puedan afectarles"}], "k": "b", "x": "Art. 51.2 CE.", "f": "Art. 51.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a51-2-informacion:N1"}, {"c": "CE-a51-2-informacion", "n": 2, "e": "Según el art. 51.2 CE, los poderes públicos promoverán de los consumidores y usuarios:", "o": [{"letra": "a", "texto": "La información y la educación."}, {"letra": "b", "texto": "La seguridad y la salud."}, {"letra": "c", "texto": "La libertad de empresa."}], "k": "a", "x": "Art. 51.2 CE.", "f": "Art. 51.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a51-2-informacion:N2"}, {"c": "CE-a51-2-informacion", "n": 3, "e": "Según el art. 51.2 CE, respecto de las organizaciones de consumidores y usuarios, los poderes públicos:", "o": [{"letra": "a", "texto": "Las financiarán y controlarán que su funcionamiento sea democrático."}, {"letra": "b", "texto": "Las inscribirán en un registro a efectos de publicidad."}, {"letra": "c", "texto": "Las fomentarán y las oirán en las cuestiones que puedan afectar a los consumidores."}], "k": "c", "x": "Art. 51.2 CE.", "f": "Art. 51.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a51-2-informacion:N3"}, {"c": "CE-a51-3-comercio", "n": 1, "e": "Según el art. 51.3 CE, la ley regulará el comercio…", "o": [{"letra": "a", "texto": "interior"}, {"letra": "b", "texto": "exterior"}], "k": "a", "x": "Art. 51.3 CE.", "f": "Art. 51.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a51-3-comercio:N1"}, {"c": "CE-a51-3-comercio", "n": 2, "e": "Según el art. 51.3 CE, en el marco de la defensa de los consumidores, la ley regulará:", "o": [{"letra": "a", "texto": "Los precios de los productos de primera necesidad."}, {"letra": "b", "texto": "La publicidad comercial y las garantías de los productos de consumo."}, {"letra": "c", "texto": "El comercio interior y el régimen de autorización de productos comerciales."}], "k": "c", "x": "Art. 51.3 CE.", "f": "Art. 51.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a51-3-comercio:N2"}, {"c": "CE-a51-3-comercio", "n": 3, "e": "¿Qué apartado del art. 51 CE se refiere al régimen de autorización de productos comerciales?", "o": [{"letra": "a", "texto": "El 2."}, {"letra": "b", "texto": "El 3."}, {"letra": "c", "texto": "El 1."}], "k": "b", "x": "Art. 51.3 CE.", "f": "Art. 51.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a51-3-comercio:N3"}, {"c": "CE-a52-organizaciones", "n": 1, "e": "Según el art. 52 CE, la estructura interna y el funcionamiento de las organizaciones profesionales deberán ser…", "o": [{"letra": "a", "texto": "democráticos"}, {"letra": "b", "texto": "públicos"}], "k": "a", "x": "Art. 52 CE.", "f": "Art. 52 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a52-organizaciones:N1"}, {"c": "CE-a52-organizaciones", "n": 2, "e": "Según el art. 52 CE, la ley regulará las organizaciones profesionales que contribuyan a la defensa de los intereses:", "o": [{"letra": "a", "texto": "Económicos que les sean propios."}, {"letra": "b", "texto": "Generales de la profesión."}, {"letra": "c", "texto": "Económicos y sociales de los trabajadores."}], "k": "a", "x": "Art. 52 CE. «Económicos y sociales que les son propios» es la fórmula del art. 7 para sindicatos y asociaciones empresariales.", "f": "Art. 52 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a52-organizaciones:N2"}, {"c": "CE-a52-organizaciones", "n": 3, "e": "El art. 52 CE, sobre las organizaciones profesionales, es el último artículo del:", "o": [{"letra": "a", "texto": "Capítulo tercero del Título I."}, {"letra": "b", "texto": "Título Preliminar."}, {"letra": "c", "texto": "Capítulo segundo del Título I."}], "k": "a", "x": "El Capítulo tercero abarca los arts. 39 a 52.", "f": "Art. 52 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a52-organizaciones:N3"}, {"c": "CE-a53-1-vinculacion", "n": 1, "e": "Según el art. 53.1 CE, la ley que regule el ejercicio de los derechos del Capítulo segundo deberá respetar en todo caso su…", "o": [{"letra": "a", "texto": "desarrollo reglamentario"}, {"letra": "b", "texto": "contenido esencial"}], "k": "b", "x": "Art. 53.1 CE.", "f": "Art. 53.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a53-1-vinculacion:N1"}, {"c": "CE-a53-1-vinculacion", "n": 2, "e": "Según el art. 53.1 CE, los derechos y libertades reconocidos en el Capítulo segundo del Título I:", "o": [{"letra": "a", "texto": "Vinculan solo al poder legislativo."}, {"letra": "b", "texto": "Solo pueden alegarse según las leyes que los desarrollen."}, {"letra": "c", "texto": "Vinculan a todos los poderes públicos."}], "k": "c", "x": "Art. 53.1 CE. «Solo pueden alegarse… según las leyes que los desarrollen» es el régimen de los principios rectores (art. 53.3).", "f": "Art. 53.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a53-1-vinculacion:N2"}, {"c": "CE-a53-1-vinculacion", "n": 3, "e": "Según el art. 53.1 CE, los derechos del Capítulo segundo se tutelarán de acuerdo con lo previsto en el artículo:", "o": [{"letra": "a", "texto": "24.1."}, {"letra": "b", "texto": "161.1.a)."}, {"letra": "c", "texto": "161.1.b)."}], "k": "b", "x": "Art. 53.1 CE: «se tutelarán de acuerdo con lo previsto en el artículo 161, 1, a)» (recurso de inconstitucionalidad). El 161.1.b) es el recurso de amparo, que el art. 53.2 reserva al art. 14 y a la Sección 1.ª.", "f": "Art. 53.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a53-1-vinculacion:N3"}, {"c": "CE-a53-2-amparo", "n": 1, "e": "Según el art. 53.2 CE, el recurso de amparo se interpone ante…", "o": [{"letra": "a", "texto": "el Tribunal Constitucional"}, {"letra": "b", "texto": "el Tribunal Supremo"}], "k": "a", "x": "Art. 53.2 CE.", "f": "Art. 53.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a53-2-amparo:N1"}, {"c": "CE-a53-2-amparo", "n": 2, "e": "Según el art. 53.2 CE, el procedimiento ante los Tribunales ordinarios para tutelar los derechos del art. 14 y la Sección primera se basa en los principios de:", "o": [{"letra": "a", "texto": "Preferencia y sumariedad."}, {"letra": "b", "texto": "Oralidad e inmediación."}, {"letra": "c", "texto": "Gratuidad y celeridad."}], "k": "a", "x": "Art. 53.2 CE.", "f": "Art. 53.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a53-2-amparo:N2"}, {"c": "CE-a53-2-amparo", "n": 3, "e": "¿Cuál de estos derechos se puede proteger mediante recurso de amparo según el art. 53.2 CE?", "o": [{"letra": "a", "texto": "La objeción de conciencia del art. 30."}, {"letra": "b", "texto": "El derecho al trabajo del art. 35."}, {"letra": "c", "texto": "El derecho a la propiedad privada del art. 33."}], "k": "a", "x": "El amparo cubre el art. 14, la Sección 1.ª (arts. 15-29) y, expresamente, la objeción de conciencia del art. 30. Los arts. 33 y 35 son de la Sección 2.ª.", "f": "Art. 53.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a53-2-amparo:N3"}, {"c": "CE-a53-3-principios", "n": 1, "e": "Según el art. 53.3 CE, ¿pueden los principios rectores del Capítulo tercero alegarse directamente en recurso de amparo?", "o": [{"letra": "a", "texto": "Sí"}, {"letra": "b", "texto": "No"}], "k": "b", "x": "Art. 53.3 CE: solo ante la Jurisdicción ordinaria y de acuerdo con las leyes que los desarrollen.", "f": "Art. 53.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a53-3-principios:N1"}, {"c": "CE-a53-3-principios", "n": 2, "e": "Según el art. 53.3 CE, el reconocimiento, el respeto y la protección de los principios del Capítulo tercero informarán:", "o": [{"letra": "a", "texto": "La legislación positiva, la práctica judicial y la actuación de los poderes públicos."}, {"letra": "b", "texto": "Solo la actuación de la Administración y de sus funcionarios."}, {"letra": "c", "texto": "La interpretación de los tratados internacionales sobre derechos humanos."}], "k": "a", "x": "Art. 53.3 CE.", "f": "Art. 53.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a53-3-principios:N2"}, {"c": "CE-a53-3-principios", "n": 3, "e": "Un ciudadano quiere invocar ante un juez el derecho a una vivienda digna (art. 47 CE). Según el art. 53.3 CE:", "o": [{"letra": "a", "texto": "No podrá alegarlo en ningún caso ante los tribunales."}, {"letra": "b", "texto": "Podrá alegarlo directamente ante cualquier tribunal y, en último término, en amparo."}, {"letra": "c", "texto": "Solo podrá alegarlo ante la Jurisdicción ordinaria según las leyes que lo desarrollen."}], "k": "c", "x": "El art. 47 está en el Capítulo tercero; se aplica el régimen del art. 53.3.", "f": "Art. 53.3 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a53-3-principios:N3"}, {"c": "CE-a54-defensor", "n": 1, "e": "Según el art. 54 CE, el Defensor del Pueblo es alto comisionado de…", "o": [{"letra": "a", "texto": "las Cortes Generales"}, {"letra": "b", "texto": "el Gobierno"}], "k": "a", "x": "Art. 54 CE.", "f": "Art. 54 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a54-defensor:N1"}, {"c": "CE-a54-defensor", "n": 2, "e": "Según el art. 54 CE, para la defensa de los derechos del Título I, el Defensor del Pueblo podrá:", "o": [{"letra": "a", "texto": "Imponer sanciones a las autoridades y funcionarios."}, {"letra": "b", "texto": "Anular los actos de la Administración que vulneren los derechos del Título I."}, {"letra": "c", "texto": "Supervisar la actividad de la Administración, dando cuenta a las Cortes Generales."}], "k": "c", "x": "Art. 54 CE: supervisa y da cuenta a las Cortes; no anula actos ni sanciona.", "f": "Art. 54 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a54-defensor:N2"}, {"c": "CE-a54-defensor", "n": 3, "e": "Según el art. 54 CE, la institución del Defensor del Pueblo:", "o": [{"letra": "a", "texto": "La regula una ley orgánica y su titular lo designan las Cortes Generales."}, {"letra": "b", "texto": "La regula el Reglamento del Congreso y su titular lo elige el Congreso."}, {"letra": "c", "texto": "La regula una ley ordinaria y su titular lo nombra el Rey a propuesta del Gobierno."}], "k": "a", "x": "Art. 54 CE: «Una ley orgánica regulará… designado por éstas [las Cortes Generales]».", "f": "Art. 54 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a54-defensor:N3"}, {"c": "CE-a55-1-suspension", "n": 1, "e": "Según el art. 55.1 CE, ¿puede suspenderse el derecho de reunión (art. 21) en el estado de excepción?", "o": [{"letra": "a", "texto": "No"}, {"letra": "b", "texto": "Sí"}], "k": "b", "x": "Art. 55.1 CE: el art. 21 está entre los suspendibles.", "f": "Art. 55.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a55-1-suspension:N1"}, {"c": "CE-a55-1-suspension", "n": 2, "e": "Según el art. 55.1 CE, ¿en qué estados pueden suspenderse los derechos que enumera?", "o": [{"letra": "a", "texto": "En los de excepción o de sitio."}, {"letra": "b", "texto": "En los de alarma, excepción o sitio."}, {"letra": "c", "texto": "Solo en el de sitio."}], "k": "a", "x": "Art. 55.1 CE: estado de excepción o de sitio. El estado de alarma no permite suspender derechos.", "f": "Art. 55.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a55-1-suspension:N2"}, {"c": "CE-a55-1-suspension", "n": 3, "e": "¿Cuál de estos derechos NO figura entre los que el art. 55.1 CE permite suspender?", "o": [{"letra": "a", "texto": "La inviolabilidad del domicilio del art. 18.2."}, {"letra": "b", "texto": "El derecho de huelga del art. 28.2."}, {"letra": "c", "texto": "La libertad ideológica del art. 16."}], "k": "c", "x": "El art. 16 no está en la lista del art. 55.1; sí lo están el 18.2 y el 28.2.", "f": "Art. 55.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a55-1-suspension:N3"}, {"c": "CE-a55-1-excepcion-17-3", "n": 1, "e": "Según el art. 55.1 CE, en el estado de excepción, ¿pueden suspenderse los derechos del detenido del art. 17.3?", "o": [{"letra": "a", "texto": "Sí"}, {"letra": "b", "texto": "No"}], "k": "b", "x": "Art. 55.1 CE: se exceptúa el apartado 3 del art. 17 para el estado de excepción.", "f": "Art. 55.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a55-1-excepcion-17-3:N1"}, {"c": "CE-a55-1-excepcion-17-3", "n": 2, "e": "Según el art. 55.1 CE, ¿qué apartado del art. 17 se exceptúa de la suspensión en el estado de excepción?", "o": [{"letra": "a", "texto": "El apartado 4."}, {"letra": "b", "texto": "El apartado 2."}, {"letra": "c", "texto": "El apartado 3."}], "k": "c", "x": "Art. 55.1 CE.", "f": "Art. 55.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a55-1-excepcion-17-3:N2"}, {"c": "CE-a55-1-excepcion-17-3", "n": 3, "e": "Según el art. 55.1 CE, la excepción del art. 17.3 se aplica:", "o": [{"letra": "a", "texto": "Solo al estado de sitio."}, {"letra": "b", "texto": "Al estado de excepción, no al de sitio."}, {"letra": "c", "texto": "A los estados de excepción y de sitio."}], "k": "b", "x": "Art. 55.1 CE: «para el supuesto de declaración de estado de excepción». En el estado de sitio, el 17.3 puede suspenderse.", "f": "Art. 55.1 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a55-1-excepcion-17-3:N3"}, {"c": "CE-a55-2-terrorismo", "n": 1, "e": "Según el art. 55.2 CE, la suspensión individual de derechos se prevé en investigaciones sobre…", "o": [{"letra": "a", "texto": "delitos contra la Hacienda Pública"}, {"letra": "b", "texto": "bandas armadas o elementos terroristas"}], "k": "b", "x": "Art. 55.2 CE.", "f": "Art. 55.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a55-2-terrorismo:N1"}, {"c": "CE-a55-2-terrorismo", "n": 2, "e": "Según el art. 55.2 CE, la suspensión individual de derechos para personas determinadas exige:", "o": [{"letra": "a", "texto": "La necesaria intervención judicial y el adecuado control parlamentario."}, {"letra": "b", "texto": "La autorización del Consejo de Ministros."}, {"letra": "c", "texto": "La declaración previa del estado de excepción por el Congreso."}], "k": "a", "x": "Art. 55.2 CE.", "f": "Art. 55.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a55-2-terrorismo:N2"}, {"c": "CE-a55-2-terrorismo", "n": 3, "e": "¿Qué derechos pueden suspenderse individualmente según el art. 55.2 CE?", "o": [{"letra": "a", "texto": "Los de los arts. 17.2, 18.2 y 18.3."}, {"letra": "b", "texto": "Los de los arts. 17.3, 18.1 y 20.1."}, {"letra": "c", "texto": "Los de los arts. 17, 18, 19 y 21."}], "k": "a", "x": "Art. 55.2 CE: duración de la detención (17.2), inviolabilidad del domicilio (18.2) y secreto de las comunicaciones (18.3).", "f": "Art. 55.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a55-2-terrorismo:N3"}, {"c": "CE-a55-2-responsabilidad", "n": 1, "e": "Según el art. 55.2 CE, el uso abusivo de las facultades de suspensión individual produce responsabilidad…", "o": [{"letra": "a", "texto": "penal"}, {"letra": "b", "texto": "solo disciplinaria"}], "k": "a", "x": "Art. 55.2 CE.", "f": "Art. 55.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a55-2-responsabilidad:N1"}, {"c": "CE-a55-2-responsabilidad", "n": 2, "e": "Según el art. 55.2 CE, la utilización injustificada o abusiva de las facultades reconocidas en la ley orgánica de suspensión individual producirá:", "o": [{"letra": "a", "texto": "Responsabilidad patrimonial de la Administración frente al afectado."}, {"letra": "b", "texto": "Responsabilidad penal, como violación de los derechos y libertades."}, {"letra": "c", "texto": "La nulidad de las pruebas obtenidas con ellas, sin otra consecuencia."}], "k": "b", "x": "Art. 55.2 CE.", "f": "Art. 55.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a55-2-responsabilidad:N2"}, {"c": "CE-a55-2-responsabilidad", "n": 3, "e": "El art. 55.2 CE califica la utilización injustificada o abusiva de las facultades de la ley orgánica de suspensión individual como:", "o": [{"letra": "a", "texto": "Infracción administrativa muy grave."}, {"letra": "b", "texto": "Delito de terrorismo cometido por funcionario público."}, {"letra": "c", "texto": "Violación de los derechos y libertades reconocidos por las leyes."}], "k": "c", "x": "Art. 55.2 CE.", "f": "Art. 55.2 CE (texto consolidado BOE, act. 20/05/2026)", "h": "CE:CE-a55-2-responsabilidad:N3"}]'::jsonb) AS x(c text, n int, e text, o jsonb, k text, x text, f text, h text);
UPDATE public.questions q SET enunciado = qq.e, opciones = qq.o, correcta = qq.k, explicacion = qq.x, fuente_normativa = qq.f, nivel = qq.n, concept_id = qq.c, estado = 'publicada', topic_id = (SELECT id FROM _tema) FROM _qq qq WHERE q.hash_dedupe = qq.h;
INSERT INTO public.questions (topic_id, enunciado, opciones, correcta, explicacion, fuente_normativa, estado, nivel, origen_tipo, origen_archivo, concept_id, hash_dedupe) SELECT (SELECT id FROM _tema), qq.e, qq.o, qq.k, qq.x, qq.f, 'publicada', qq.n, 'propio', 'data/constitucion/titulo-i.json', qq.c, qq.h FROM _qq qq WHERE NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.hash_dedupe = qq.h);
COMMIT;
